
/* ============================================================
   Synthetic fleet data generator
   Deterministic (seeded) so the demo is stable across reloads.
   ============================================================ */

function mulberry32(seed){
  return function(){
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const SEED = parseInt(
  sessionStorage.getItem("eam_demo_seed") || localStorage.getItem("eam_demo_seed") || "9137",
  10
);
localStorage.setItem("eam_demo_seed", String(SEED));
sessionStorage.setItem("eam_demo_seed", String(SEED));
const rng = mulberry32(SEED);
const rnd = (min, max) => min + rng() * (max - min);
const rndInt = (min, max) => Math.floor(rnd(min, max + 1));
const pick = (arr) => arr[Math.floor(rng() * arr.length)];
const round1 = (n) => Math.round(n * 10) / 10;
const round2 = (n) => Math.round(n * 100) / 100;
const round4 = (n) => Math.round(n * 10000) / 10000;
