/* ---------------- Monthly portfolio trend series (24 months) ---------------- */
const MONTHS = (()=>{
  const out=[]; const names=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const now = new Date(2026,6,1); // July 2026
  for(let i=23;i>=0;i--){
    const d = new Date(now.getFullYear(), now.getMonth()-i, 1);
    out.push(names[d.getMonth()] + " '" + String(d.getFullYear()).slice(2));
  }
  return out;
})();

const PR_TREND = MONTHS.map((m,i)=> round1(92.4 + Math.sin(i/3.6)*1.6 + (i/23)*2.3 + rnd(-0.5,0.5)));
const AVAIL_TREND = MONTHS.map((m,i)=> round1(97.1 + Math.sin(i/4.2 + 1)*0.9 + (i/23)*1.1 + rnd(-0.3,0.3)));
const MTTR_TREND = MONTHS.map((m,i)=> round1(30 - (i/23)*11 + Math.sin(i/3)*2.5 + rnd(-1.2,1.2))); // hours, trending down
const MTBF_TREND = MONTHS.map((m,i)=> Math.round(620 + (i/23)*260 + Math.sin(i/4)*35 + rnd(-15,15))); // hours, trending up

