const PRIORITIES = ["Critical","High","Medium","Low"];
const PRIORITY_WEIGHTS = [0.09,0.26,0.42,0.23];
function weightedPick(arr,w){
  let r = rng(), acc=0;
  for(let i=0;i<arr.length;i++){ acc+=w[i]; if(r<=acc) return arr[i]; }
  return arr[arr.length-1];
}

function genWorkOrders(type, count, descPool, statusMix){
  const out=[];
  for(let i=0;i<count;i++){
    const plant = pick(PLANTS);
    const daysAgo = rndInt(0, 75);
    const created = new Date(2026,6,14); created.setDate(created.getDate()-daysAgo);
    const priority = weightedPick(PRIORITIES, PRIORITY_WEIGHTS);
    const status = weightedPick(statusMix.s, statusMix.w);
    const slaHours = priority==="Critical"?8:priority==="High"?24:priority==="Medium"?72:168;
    out.push({
      id: type.slice(0,3).toUpperCase()+"-"+String(4000+i+ (type==="Adaptive"?400:type==="Predictive"?800:type==="Preventive"?1200:0)),
      type, plant: plant.id, plantName: plant.name,
      asset: pick(ASSET_CLASSES) + " " + (rndInt(1,plant.inverters||24)),
      desc: pick(descPool).replace("#", String(rndInt(1,plant.inverters||18))),
      priority, status,
      created: created.toISOString().slice(0,10),
      slaHours,
      source: type==="Corrective" ? "Fault-code correlation engine" : type==="Adaptive" ? "Condition-monitoring trigger" : type==="Preventive" ? "Fixed PM calendar" : "AI/ML prediction model",
    });
  }
  out.sort((a,b)=> a.created<b.created?1:-1);
  return out;
}

