const PM_FREQUENCIES = [30,60,90,180,270,365];
const PM_COMPLIANCE_AS_OF = "2026-07-14";
const PM_COMPLIANCE_TOLERANCE_DAYS = 0;

function aipDateOnly(d){ return d.toISOString().slice(0,10); }
function aipAddDays(dateStr,days){
  const d=new Date(dateStr+"T00:00:00");
  d.setDate(d.getDate()+Number(days||0));
  return aipDateOnly(d);
}
function aipDayDiff(a,b){
  const A=new Date(a+"T00:00:00"), B=new Date(b+"T00:00:00");
  return Math.round((A-B)/86400000);
}

function aipDisplayDate(v){
  const s=String(v||"").slice(0,10);
  if(!s) return "—";
  const m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : s;
}
function aipFrequencyLabel(days){
  const n=Number(days);
  return Number.isFinite(n) && n>0 ? `${Math.round(n)} days` : "0";
}

function filterPreventiveWorkOrders(value){
  const q=String(value||"").trim().toLowerCase();
  const root=document.getElementById("view-preventive")||document;
  const table=root.querySelector(".table-scroll table");
  if(!table) return;
  const rows=Array.from(table.querySelectorAll("tbody tr"));
  let visible=0;
  rows.forEach(tr=>{
    const hay=String(tr.innerText||tr.textContent||"").toLowerCase();
    const show=!q || hay.includes(q);
    tr.style.display=show?"":"none";
    if(show) visible++;
  });
  const count=document.getElementById("pmWoSearchCount");
  if(count){
    count.textContent=q ? `${visible} match${visible===1?"":"es"}` : "";
    count.style.display=q ? "block" : "none";
  }
  const clear=document.getElementById("pmWoSearchClear");
  if(clear) clear.style.visibility=q?"visible":"hidden";
}
function clearPreventiveWorkOrderSearch(){
  const input=document.getElementById("pmWoSearch");
  if(input){ input.value=""; filterPreventiveWorkOrders(""); input.focus(); }
}
function restorePreventiveWorkOrderSearch(){
  const input=document.getElementById("pmWoSearch");
  filterPreventiveWorkOrders(input?.value||"");
}

PREVENTIVE_WOS.forEach(w=>{
  w.frequencyDays = pick(PM_FREQUENCIES);
  const seq = Number(String(w.id||"").replace(/\D/g,"")) || 0;

  // Cycle context remains available for policy analysis.
  const lastDone = new Date(2026,6,14);
  lastDone.setDate(lastDone.getDate() - rndInt(5, w.frequencyDays));
  const nextDue = new Date(lastDone);
  nextDue.setDate(nextDue.getDate() + w.frequencyDays);
  w.lastDone = aipDateOnly(lastDone);
  w.nextDue = aipDateOnly(nextDue);

  // Current PM work-order due/completion dates used specifically for schedule compliance.
  if(w.status==="Overdue Actions"){
    w.overdueDays = 2 + (seq % 20);
    w.pmDueDate = aipAddDays(PM_COMPLIANCE_AS_OF,-w.overdueDays);
    w.pmCompletionDate = "";
  }else if(w.status==="Completed"){
    // Completed work is part of the due population. A deterministic minority is
    // completed after its PM due date, so actual compliance is not automatically 100%.
    const daysBeforeAsOf = 4 + (seq % 48);
    w.pmDueDate = aipAddDays(PM_COMPLIANCE_AS_OF,-daysBeforeAsOf);
    const lateDays = (seq % 5===0) ? 1 + (seq % 5) : -(seq % 4);
    let completed = aipAddDays(w.pmDueDate,lateDays);
    if(completed>PM_COMPLIANCE_AS_OF) completed=PM_COMPLIANCE_AS_OF;
    w.pmCompletionDate = completed;
    w.overdueDays = Math.max(0,aipDayDiff(w.pmCompletionDate,w.pmDueDate));
  }else{
    w.overdueDays = 0;
    w.pmDueDate = aipAddDays(PM_COMPLIANCE_AS_OF,2+(seq%28));
    w.pmCompletionDate = "";
  }

  w.pmDue = w.pmDueDate<=PM_COMPLIANCE_AS_OF;
  w.pmOnTime = !!(w.pmDue && w.pmCompletionDate && aipDayDiff(w.pmCompletionDate,w.pmDueDate)<=PM_COMPLIANCE_TOLERANCE_DAYS);
  w.pmComplianceResult = !w.pmDue ? "Not Due" : w.pmOnTime ? "On Time" : w.pmCompletionDate ? "Completed Late" : "Overdue";
});

function pmComplianceState(w){
  const dueDate=String(w?.pmDueDate||w?.PM_Due_Date||"").slice(0,10);
  const completionDate=String(w?.pmCompletionDate||w?.Actual_PM_Completion_Date||"").slice(0,10);
  const toleranceRaw=Number(w?.pmTolerance ?? w?.PM_Compliance_Tolerance_Days ?? PM_COMPLIANCE_TOLERANCE_DAYS);
  const tolerance=Number.isFinite(toleranceRaw)?toleranceRaw:PM_COMPLIANCE_TOLERANCE_DAYS;
  if(!dueDate) return {due:false,onTime:false,result:"Insufficient Evidence",dueDate:"",completionDate:""};
  const due=dueDate<=PM_COMPLIANCE_AS_OF;
  if(!due) return {due:false,onTime:false,result:"Not Due",dueDate,completionDate};
  const onTime=!!(completionDate && aipDayDiff(completionDate,dueDate)<=tolerance);
  return {
    due:true,
    onTime,
    result:onTime?"On Time":completionDate?"Completed Late":"Overdue",
    dueDate,
    completionDate
  };
}

function pmComplianceStats(rows){
  const states=(rows||[]).map(w=>({w,state:pmComplianceState(w)}));
  const due=states.filter(x=>x.state.due);
  const onTime=due.filter(x=>x.state.onTime);
  const late=due.filter(x=>x.state.result==="Completed Late");
  const overdue=due.filter(x=>x.state.result==="Overdue");
  return {
    due:due.length,
    onTime:onTime.length,
    late:late.length,
    overdue:overdue.length,
    rate:due.length ? round2(onTime.length/due.length*100) : null
  };
}

// v87_795 — one governed PM-compliance population for portfolio KPI + site chart.
function pmCompliancePlantKey(v){
  return String(v??"").trim().toLowerCase();
}
function pmComplianceCanonical(){
  const rows=Array.isArray(PREVENTIVE_WOS)?PREVENTIVE_WOS:[];
  const overall=pmComplianceStats(rows);
  const sites=(Array.isArray(PLANTS)?PLANTS:[]).map(p=>{
    const pid=pmCompliancePlantKey(p?.id);
    const pname=pmCompliancePlantKey(p?.name);
    const wos=rows.filter(w=>{
      const keys=[w?.plant,w?.Plant_ID,w?.plantId,w?.plantName,w?.Plant_Name].map(pmCompliancePlantKey).filter(Boolean);
      return keys.includes(pid) || (pname && keys.includes(pname));
    });
    const stats=pmComplianceStats(wos);
    return {id:p?.id||'',name:p?.name||p?.id||'',...stats};
  });
  return {rows,overall,sites};
}
