/* ---------------- Predictive: RUL / risk ranking ---------------- */
const RISK_ASSETS = [];
(function(){
  const comps = ["Inverter IGBT module","Cooling fan","DC contactor","Capacitor bank","Tracker gearbox","Transformer bushing","String fuse array","Slip-ring assembly"];
  for(let i=0;i<14;i++){
    const plant = pick(PLANTS);
    const rul = rndInt(6, 210);
    const risk = round2(Math.max(0.05, Math.min(0.97, 1 - rul/230 + rnd(-0.05,0.08))));
    RISK_ASSETS.push({
      asset: pick(comps) + " · " + plant.id + "-INV" + rndInt(1,24),
      plant: plant.name,
      rulDays: rul,
      riskScore: risk,
      model: pick(["XGBoost failure model","Survival (Random Survival Forest)","Autoencoder + CUSUM","LSTM sequence model"]),
      confidence: rndInt(74,97),
    });
  }
  RISK_ASSETS.sort((a,b)=> b.riskScore - a.riskScore);
})();

