function sparklineSVG(trend){
  const pts = trend==="crit" ? [[0,14],[6,13],[12,11],[18,12],[24,8],[30,5],[36,2]]
            : trend==="warn" ? [[0,12],[6,11],[12,12],[18,9],[24,10],[30,7],[36,8]]
            : [[0,10],[6,8],[12,11],[18,7],[24,9],[30,5],[36,7]];
  const col = trend==="crit"?"#C0392B":trend==="warn"?"#C9821F":"#1E8E5A";
  const d = pts.map((p,i)=>(i?"L":"M")+p[0]+","+p[1]).join(" ");
  return `<svg width="38" height="16" viewBox="0 0 38 16" fill="none"><path d="${d}" stroke="${col}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

/* ---------------- Prescriptive: ranked action recommendations ---------------- */
const RX_ACTIONS = ["Repair now","Bundle with next visit","Defer to outage window","Monitor — no action"];
const PRESCRIPTIVE_RECS = RISK_ASSETS.slice(0,12).map((r,i)=>{
  const action = r.riskScore>0.7 ? "Repair now" : r.riskScore>0.5 ? pick(["Bundle with next visit","Repair now"]) : r.riskScore>0.3 ? "Defer to outage window" : "Monitor — no action";
  const costNow = rndInt(8,60)*1000;
  const costDeferred = Math.round(costNow * rnd(1.4,3.2));
  return {
    id: "RX-"+String(5000+i),
    asset: r.asset, plant: r.plant, riskScore: r.riskScore, rulDays: r.rulDays,
    action,
    rationale: action==="Repair now" ? "High failure risk within SLA-critical window — deferring risks unplanned outage"
      : action==="Bundle with next visit" ? "Moderate risk; next scheduled site visit falls within safe RUL margin"
      : action==="Defer to outage window" ? "Low urgency; next planned outage window covers RUL margin at lower cost"
      : "Risk within tolerance — continue monitoring, no crew dispatch warranted",
    costNow, costDeferred, costAvoided: Math.max(0, costDeferred-costNow),
    confidence: r.confidence,
    accepted: rng() < 0.82,
  };
}).sort((a,b)=> b.riskScore-a.riskScore);

/* ---------------- Risk-Based Maintenance: fleet-wide criticality queue ---------------- */
const RISK_QUEUE = (()=>{
  const items = [];
  RISK_ASSETS.forEach(r=>{
    items.push({ asset:r.asset, plant:r.plant, category:"Predictive",
      energyImpact: rndInt(2,10), safetyRisk: rndInt(1,10), accessibility: rndInt(1,10), rulDays:r.rulDays });
  });
  CORRECTIVE_WOS.filter(w=>w.emergency).slice(0,6).forEach(w=>{
    items.push({ asset:w.asset, plant:w.plantName, category:"Corrective (emergency)",
      energyImpact: rndInt(5,10), safetyRisk: rndInt(6,10), accessibility: rndInt(1,10), rulDays:null });
  });
  ADAPTIVE_WOS.filter(w=>w.priority==="Critical"||w.priority==="High").slice(0,4).forEach(w=>{
    items.push({ asset:w.asset, plant:w.plantName, category:"Adaptive",
      energyImpact: rndInt(2,8), safetyRisk: rndInt(1,6), accessibility: rndInt(1,10), rulDays:null });
  });
  items.forEach(it=>{
    it.composite = round2((it.energyImpact*0.4 + it.safetyRisk*0.4 + (11-it.accessibility)*0.2)/10);
    it.tier = it.composite>0.7 ? "Critical" : it.composite>0.5 ? "High" : it.composite>0.3 ? "Medium" : "Low";
  });
  items.sort((a,b)=> b.composite-a.composite);
  return items;
})();

/* ---------------- Reliability-Centered Maintenance: strategy decision matrix ---------------- */
const RCM_MATRIX = [
  { cls:"Inverter IGBT module",     mode:"Over-temperature / thermal fatigue cracking",   detect:"Heat-sink temp trend + fault codes",        consequence:"Inverter derate or trip — energy loss",              strategy:"Predictive",  rationale:"Rich telemetry + gradual degradation signature suits ML failure models" },
  { cls:"DC string fuse",           mode:"Sudden open-circuit (surge / overcurrent)",     detect:"Peer-string current comparison",            consequence:"Zero yield on affected string until replaced",       strategy:"Corrective",  rationale:"Low-cost, fast to replace — predicting exact failure timing adds little value" },
  { cls:"Tracker slew-drive motor", mode:"Bearing wear / lubrication breakdown",          detect:"Motor current signature + duty-cycle count", consequence:"Mis-tracking — persistent yield loss",               strategy:"Adaptive",    rationale:"Wear rate varies strongly with dust/cycle load — fixed interval over- or under-services it" },
  { cls:"MV transformer bushing",   mode:"Insulation degradation (DGA-detectable)",       detect:"Dissolved gas analysis, oil temperature",   consequence:"Catastrophic failure — safety + fire risk",          strategy:"Risk-Based",  rationale:"Rare but severe consequence — prioritized by risk regardless of predicted timing" },
  { cls:"Weather station sensors",  mode:"Calibration drift",                             detect:"Cross-reference vs. nearby station/satellite",consequence:"Bad expected-production baseline, not equipment loss", strategy:"Preventive",  rationale:"Slow, predictable drift — fixed annual calibration is cheaper than condition monitoring" },
  { cls:"Module hot spots",         mode:"Cell crack / bypass diode failure",             detect:"Thermal imagery (drone/fixed)",             consequence:"Localized yield loss, fire risk if severe",           strategy:"Predictive",  rationale:"Periodic imagery + CV classification catches this before hard failure" },
  { cls:"Combiner box enclosure",   mode:"Moisture ingress / insulation resistance drop", detect:"IR test on inspection rounds",              consequence:"Ground fault risk",                                   strategy:"Preventive",  rationale:"Enclosure ingress is slow and inspection-driven, not sensor-driven" },
  { cls:"SCADA communication gateway", mode:"Firmware fault / connectivity loss",         detect:"Heartbeat/telemetry gap monitoring",        consequence:"Blind spot on affected plant segment",                strategy:"Corrective",  rationale:"Binary up/down failure mode — nothing to predict, just detect and dispatch fast" },
  { cls:"Capacitor bank (inverter)",mode:"ESR drift / dielectric aging",                  detect:"ESR trend + ripple-current signature",      consequence:"Inverter efficiency loss, eventual trip",             strategy:"Adaptive",    rationale:"Aging rate tracks thermal duty — condition-based interval outperforms fixed calendar" },
  { cls:"Vegetation / ground cover",mode:"Encroachment reducing clearance or shading",    detect:"Drone/satellite RGB segmentation",          consequence:"Gradual shading loss, tracker obstruction risk",      strategy:"Opportunistic", rationale:"Low urgency, geographically distributed — cheapest when bundled into routine site visits" },
  { cls:"Perimeter fencing/cameras",mode:"Physical damage, theft exposure",               detect:"Scheduled inspection rounds",               consequence:"Security exposure — module/cable theft risk",         strategy:"Preventive",  rationale:"No meaningful sensor signal — calendar-based physical inspection is the only lever" },
  { cls:"Tracker row obstruction",  mode:"Debris/foreign object blocking rotation",       detect:"CV object detection on drone imagery",      consequence:"Row-level yield loss",                                strategy:"Opportunistic", rationale:"Individually minor — addressed efficiently alongside other bundled site work" },
];

/* ---------------- Opportunistic & Outage-window bundling ---------------- */
const OUTAGE_WINDOWS = (()=>{
  const backlog = [...ADAPTIVE_WOS, ...PREVENTIVE_WOS].filter(w=> w.status!=="Closed" && w.status!=="Completed" && w.priority!=="Critical");
  const out = [];
  for(let i=0;i<8;i++){
    const plant = pick(PLANTS);
    const isOutage = i%3===0;
    const d = new Date(2026,6,14); d.setDate(d.getDate() + rndInt(3,45));
    const bundleCount = rndInt(2,6);
    const bundled = [];
    for(let j=0;j<bundleCount;j++){ bundled.push(pick(backlog)); }
    out.push({
      id: "VIS-"+String(6000+i),
      plant: plant.id, plantName: plant.name,
      date: d.toISOString().slice(0,10),
      type: isOutage ? "Planned outage window" : "Scheduled site visit",
      primaryTask: isOutage ? "Transformer overhaul / string re-torque" : pick(PREVENTIVE_TASKS),
      bundled,
      truckRollsSaved: Math.max(0, bundled.length-1),
    });
  }
  return out.sort((a,b)=> a.date<b.date?-1:1);
})();


