/* ---------------- Spare parts inventory ---------------- */
const PART_TO_RISK_COMPONENT = {
  "IGBT power module (central inverter)": "Inverter IGBT module",
  "Inverter cooling fan assembly": "Cooling fan",
  "DC string fuse (15A)": "String fuse array",
  "Tracker slew-drive motor": "Tracker gearbox",
  "DC contactor (400A)": "DC contactor",
  "Capacitor bank module": "Capacitor bank",
  "Transformer bushing (MV)": "Transformer bushing",
  "Transformer cooling fan": "Cooling fan",
  "Slip-ring assembly (tracker)": "Slip-ring assembly",
  "Inverter control card": "Inverter IGBT module",
};
function computeRulLinkage(p){
  const comp = PART_TO_RISK_COMPONENT[p.part];
  const linked = comp ? RISK_ASSETS.filter(r=>r.asset && r.asset.startsWith(comp+" ·")) : [];
  p.linkedCount = linked.length;
  p.linkedRUL = linked.length ? Math.min(...linked.map(r=>r.rulDays)) : null;
  p.urgentLinked = linked.filter(r=>r.rulDays<45).length;
  const boost = 1 + Math.min(0.6, p.urgentLinked*0.15);
  p.baselineReorder = Math.max(1, Math.round(p.reorder/boost));
  p.rulBoostPct = Math.round((boost-1)*100);
}
