/* ---------------- 30-day quantity-balance ledger (opening + receipts - issues = closing) ---------------- */
const FAST_MOVERS = ["DC string fuse (15A)","Junction box connector kit"];
const SLOW_MOVERS = ["Transformer bushing (MV)","Tracker slew-drive motor","SCADA communication gateway","Slip-ring assembly (tracker)"];
SPARE_PARTS.forEach(p=>{
  const velocity = FAST_MOVERS.includes(p.part) ? "fast" : SLOW_MOVERS.includes(p.part) ? "slow" : "medium";
  p.velocity = velocity;
  const issues30 = velocity==="fast" ? rndInt(45,95) : velocity==="slow" ? rndInt(0,2) : rndInt(3,9);
  // simulate a restock GRN this period if stock is at/near reorder point, else a smaller routine receipt
  const restocked = p.stock < p.reorder * 1.15;
  const receipts30 = restocked ? rndInt(Math.max(issues30,6), issues30 + Math.round(p.max*0.35)+6) : Math.max(0, issues30 - rndInt(0,3));
  const opening = Math.max(0, p.stock - receipts30 + issues30);
  p.opening = opening;
  p.receipts30 = receipts30;
  p.issues30 = issues30;
  p.closing = p.stock; // ledger reconciles to current on-hand
  p.avgDailyConsumption = +(issues30/30).toFixed(2);
  p.doi = p.avgDailyConsumption > 0 ? Math.round(p.closing / p.avgDailyConsumption) : null; // null = no movement in period
});

/* (s,S) simulated stock trajectory for IGBT power module — 90 days */
const SS_SIM = (()=>{
  const s=12, S=30; let stock = 24; const out=[];
  for(let d=0; d<90; d++){
    stock -= rng() < 0.12 ? rndInt(1,3) : 0;
    if(stock <= s){ stock += (S - stock); out.push({d, stock, reorderFired:true}); }
    else out.push({d, stock, reorderFired:false});
    if(stock<0) stock=0;
  }
  return out;
})();

