const fmtINR = (n) => "₹" + (n>=10000000? round1(n/10000000)+" Cr" : n>=100000? round1(n/100000)+" L" : n.toLocaleString("en-IN"));
const fmtNum = (n) => n.toLocaleString("en-IN");
const capFirst = (s) => s.charAt(0).toUpperCase()+s.slice(1);

function tagFor(type){
  const cls = type.toLowerCase()==="corrective"?"corrective":type.toLowerCase()==="adaptive"?"adaptive":"predictive";
  return `<span class="tag ${cls}">${type}</span>`;
}
function statusTag(status){
  const raw=String(status??"").trim();
  const key=raw.toLowerCase().replace(/[_-]+/g," ").replace(/\s+/g," ");
  const map={
    "open":"open",
    "Overdue Actions":"critical",
    "critical":"critical",
    "action required":"critical",
    "blocked":"critical",
    "escalated":"critical",
    "watch":"watch",
    "at risk":"watch",
    "due soon":"watch",
    "high":"watch",
    "in progress":"progress",
    "under review":"progress",
    "manual review":"progress",
    "scheduled":"scheduled",
    "on track":"ontrack",
    "healthy":"ontrack",
    "good":"ontrack",
    "compliant":"ontrack",
    "connected":"ontrack",
    "completed":"closed",
    "closed":"closed",
    "resolved":"closed",
    "approved":"closed",
    "low":"info",
    "medium":"info",
    "planned":"info",
    "pending":"info"
  };
  const cls=map[key]||"ghost";
  return `<span class="tag ${cls}">${raw||"—"}</span>`;
}
function prioDot(p){
  const map={Critical:"prio-critical",High:"prio-high",Medium:"prio-medium",Low:"prio-low"};
  return `<span class="prio-dot ${map[p]}"></span>${p}`;
}

