 if(!rows)return VISION_FINDINGS.map((f,i)=>{const ai=visionResolveAssetIdentity({Finding_ID:f.id,Asset_ID:f.asset,Asset_Tag:f.asset,Site_ID:f.site});return {...f,asset:ai.tag,assetId:ai.id,assetTag:ai.tag,missionId:`VIS-MSN-${String(i+1).padStart(5,'0')}`,workflowStage:(f.status==='Resolved'||f.status==='Work Order Created')?'Actioned':f.status==='Under Review'?'Reviewed':'Impact Calculated'};});
