 window.AIP_CONTEXT_NAV=ctx;window.AIP_SELECTED_ASSET_CONTEXT=ctx;window.AIP_ASSET_EXPLORER_PENDING_CONTEXT=ctx;window.AIP_ASSET_EXPLORER_SELECTED_ID=identity.assetId;
