function aipVision659GroundedCallout(mode,finding,measurement){
  finding=finding||{}; measurement=measurement||{};
  const object=finding.Inspected_Object_Ref||finding.Asset_Tag||finding.Asset_ID||'Inspected object';
  const loc=finding.Physical_Location||finding.Location||finding.Site||'Inspection location';
  const conf=finding.Detection_Confidence??finding.AI_Confidence??finding.Confidence;
  const dt=finding.Delta_T_C??finding.Thermal_Deviation_C??finding.DeltaT_C??measurement.Delta_T_C;
  const imb=finding.String_Current_Imbalance_pct??finding.Current_Imbalance_pct??measurement.String_Current_Imbalance_pct;
  const prE=measurement.PR_Expected_pct??finding.PR_Expected_pct;
  const prM=measurement.PR_Measured_pct??finding.PR_Measured_pct;
  const fmt=(v,s='')=> (v===undefined||v===null||v==='')?'—':`${Number(v).toFixed(2)}${s}`;
  if(mode==='RGB'){const bits=[]; if(object&&object!=='Inspected object')bits.push(aapVisionSafe(object)); if(loc&&loc!=='Inspection location')bits.push(aapVisionSafe(loc)); if(conf!==undefined)bits.push(`Detection confidence ${fmt(conf,'%')}`); return bits.length?`<div class="v659-callout rgb"><b>RGB evidence</b>${bits.join(' · ')}</div>`:'';}
  if(mode==='Thermal'){const bits=[]; if(object&&object!=='Inspected object')bits.push(aapVisionSafe(object)); if(loc&&loc!=='Inspection location')bits.push(aapVisionSafe(loc)); if(dt!==undefined)bits.push(`Thermal deviation ${fmt(dt,' °C')}`); if(imb!==undefined)bits.push(`Current imbalance ${fmt(imb,'%')}`); return bits.length?`<div class="v659-callout thermal"><b>Thermal anomaly</b>${bits.join(' · ')}</div>`:'';}
  if(mode==='AI Overlay'){const bits=[]; if(object&&object!=='Inspected object')bits.push(aapVisionSafe(object)); if(loc&&loc!=='Inspection location')bits.push(aapVisionSafe(loc)); if(conf!==undefined)bits.push(`Detection confidence ${fmt(conf,'%')}`); if(dt!==undefined)bits.push(`ΔT ${fmt(dt,' °C')}`); if(imb!==undefined)bits.push(`Current imbalance ${fmt(imb,'%')}`); return bits.length?`<div class="v659-callout overlay"><b>AI-confirmed detection</b>${bits.join(' · ')}</div>`:'';}
  return '';
}
function aapVisionSafe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

