const SCENARIO_SIM_STATE={
  type:"maintenance",
  maintenanceDelay:30,
  maintenanceAssetRisk:72,
  cleaningShift:-10,
  cleaningSoiling:4.2,
  repairAge:8,
  repairRisk:64
};

function scenarioBaseContext(){
  const plants=(typeof PLANTS!=="undefined"&&Array.isArray(PLANTS))?PLANTS:[];
  const risks=(typeof RISK_ASSETS!=="undefined"&&Array.isArray(RISK_ASSETS))?RISK_ASSETS:[];
  const avgMW=plants.length?plants.reduce((s,p)=>s+Number(p.mw||0),0)/plants.length:50;
  const avgPR=plants.length?plants.reduce((s,p)=>s+Number(p.pr||0),0)/plants.length:78;
  const topRisk=[...risks].sort((a,b)=>Number(b.riskScore||0)-Number(a.riskScore||0))[0];
  return {avgMW,avgPR,topRisk};
}

function scenarioMaintenanceOptions(){
  const c=scenarioBaseContext(),delay=Number(SCENARIO_SIM_STATE.maintenanceDelay||30);
  const baseRisk=Math.max(20,Math.min(95,Number(SCENARIO_SIM_STATE.maintenanceAssetRisk||72)));
  const tariff=4500;
  const nowCost=650000;
  const options=[
    {name:"Maintain now",delay:0,failure:Math.max(6,baseRisk-46),downtime:8,lostMWh:c.avgMW*.012,revenue:-nowCost,maintenance:nowCost,warranty:2},
    {name:`Delay ${delay} days`,delay,failure:Math.min(97,baseRisk+delay*.18),downtime:22+delay*.15,lostMWh:c.avgMW*(.035+delay*.00045),maintenance:nowCost*1.18,warranty:Math.min(70,10+delay*.55)},
    {name:"Delay 90 days",delay:90,failure:Math.min(99,baseRisk+24),downtime:52,lostMWh:c.avgMW*.11,maintenance:nowCost*1.65,warranty:68}
  ];
  options.forEach(o=>{o.revenueImpact=-(o.lostMWh*tariff+o.maintenance);o.netBenefit=-o.revenueImpact;});
  return {title:"Maintenance Timing",source:"Predictive Maintenance",target:"predictive",options,recommended:0,
    summary:"Performing maintenance now minimizes failure probability, lost generation and warranty exposure."};
}

function scenarioCleaningOptions(){
  const c=scenarioBaseContext(),shift=Number(SCENARIO_SIM_STATE.cleaningShift||-10);
  const soiling=Math.max(.5,Math.min(12,Number(SCENARIO_SIM_STATE.cleaningSoiling||4.2)));
  const tariff=4500,waterRate=3.4,cleaningCost=210000;
  const options=[
    {name:"Clean now",days:0,prGain:soiling*.72,generation:c.avgMW*1550*(soiling*.72/100),cost:cleaningCost,water:c.avgMW*waterRate,risk:8},
    {name:shift<0?`Advance ${Math.abs(shift)} days`:`Delay ${shift} days`,days:shift,prGain:shift<0?soiling*.86:soiling*.48,generation:c.avgMW*1550*((shift<0?soiling*.86:soiling*.48)/100),cost:cleaningCost*1.06,water:c.avgMW*waterRate*1.04,risk:shift<0?5:22},
    {name:"Delay 15 days",days:15,prGain:soiling*.32,generation:c.avgMW*1550*(soiling*.32/100),cost:cleaningCost*.96,water:c.avgMW*waterRate*.98,risk:35}
  ];
  options.forEach(o=>{o.revenueGain=o.generation*tariff;o.netBenefit=o.revenueGain-o.cost;});
  const recommended=options.reduce((best,o,i,a)=>o.netBenefit>a[best].netBenefit?i:best,0);
  return {title:"Module Cleaning Optimization",source:"Site Performance",target:"siteperformance",options,recommended,
    summary:"The recommended cleaning timing maximizes net generation benefit after cleaning cost."};
}

function scenarioRepairReplaceOptions(){
  const age=Math.max(1,Math.min(20,Number(SCENARIO_SIM_STATE.repairAge||8)));
  const risk=Math.max(10,Math.min(95,Number(SCENARIO_SIM_STATE.repairRisk||64)));
  const tariff=4500;
  const options=[
    {name:"Repair inverter",cost:1150000,downtime:28,life:Math.max(2,8-age*.35),recurrence:Math.min(70,18+age*2.8),lostMWh:84},
    {name:"Replace inverter",cost:4200000,downtime:42,life:15,recurrence:7,lostMWh:126},
    {name:"Continue monitoring",cost:180000,downtime:10,life:Math.max(.5,4-age*.18),recurrence:Math.min(96,risk+18),lostMWh:210}
  ];
  options.forEach(o=>{
    o.riskCost=o.recurrence/100*2500000;
    o.totalCost=o.cost+o.lostMWh*tariff+o.riskCost;
    o.netBenefit=Math.max(0,6500000-o.totalCost);
    o.roi=o.cost>0?o.netBenefit/o.cost*100:0;
    o.payback=o.netBenefit>0?Math.min(36,o.cost/o.netBenefit*12):36;
  });
  const recommended=options.reduce((best,o,i,a)=>o.totalCost<a[best].totalCost?i:best,0);
  return {title:"Repair versus Replace",source:"Prescriptive Maintenance",target:"prescriptive",options,recommended,
    summary:"The recommendation balances upfront cost, downtime, recurrence risk and remaining useful life."};
}

function activeScenarioModel(){
  if(SCENARIO_SIM_STATE.type==="cleaning")return scenarioCleaningOptions();
  if(SCENARIO_SIM_STATE.type==="repair")return scenarioRepairReplaceOptions();
  return scenarioMaintenanceOptions();
}

