 {id:"DI-1048",asset:"INV-14",site:"Rajasthan Solar I",risk:91,confidence:92,model:"Inverter Thermal Risk v3.2",event:"EV-9081",workOrder:"WO-AI-1048",benefit:"₹14.70 lakh",status:"Approved"},
 {id:"DI-1046",asset:"TR-03",site:"Gujarat Solar II",risk:84,confidence:88,model:"Transformer Cooling Risk v2.4",event:"EV-9074",workOrder:"WO-AI-1046",benefit:"₹9.30 lakh",status:"Scheduled"},
 {id:"DI-1041",asset:"CB-22",site:"Karnataka Solar I",risk:79,confidence:86,model:"DC Imbalance Detection v2.7",event:"EV-9068",workOrder:"WO-AI-1041",benefit:"₹5.80 lakh",status:"Executed"}
