      <div class="rigour-trace">${trace.map((x,i)=>`<div class="rigour-trace-item rigour-clickable" onclick="rigourGo('${x[3]}')" title="Open ${x[2]}"><div class="rigour-trace-num">${i+1}</div><div><b>${x[0]}</b><small>${x[1]}</small><div class="rigour-unit">Unit: <b>${x[4]}</b> · Source: <span class="rigour-link">${x[2]}</span></div></div><em>Open →</em></div>`).join("")}</div>
