/* =============================== GOVERNED PORTFOLIO ACTION PRIORITIZATION v87_174 =============================== */
const AIP_ACTION_PRIORITY_DEFAULT={
  urgencyWeight:35,
  operationalRiskWeight:25,
  businessImpactWeight:25,
  recoverabilityWeight:15,
  priorityThreshold:70
};
window.AIP_ACTION_PRIORITY=window.AIP_ACTION_PRIORITY||(()=>{
  try{return {...AIP_ACTION_PRIORITY_DEFAULT,...JSON.parse(localStorage.getItem('aipActionPrioritization')||'{}')}}catch(_){return {...AIP_ACTION_PRIORITY_DEFAULT}}
})();
function aipActionPriorityConfig(){return {...AIP_ACTION_PRIORITY_DEFAULT,...(window.AIP_ACTION_PRIORITY||{})}}
function aipClamp(v,min=0,max=100){v=Number(v);return Number.isFinite(v)?Math.max(min,Math.min(max,v)):0}
function aipActionMoney(r){
  const keys=['revenueAtRisk','Revenue_At_Risk','financialImpact','Financial_Impact','estimatedLoss','Estimated_Loss','costAvoided','Cost_Avoided','exposure','Exposure_INR'];
  for(const k of keys){const n=Number(r?.[k]);if(Number.isFinite(n)&&n>0)return n}
  return 0;
}
function aipActionAssetText(r){return String(r?.asset||r?.assetId||r?.Asset_ID||r?.tag||r?.Asset_Tag||r?.name||'').trim()}
function aipBuildActionPopulation(){
  const cfg=aipActionPriorityConfig(), actions=[];
  const score=(x)=>{
    const total=cfg.urgencyWeight+cfg.operationalRiskWeight+cfg.businessImpactWeight+cfg.recoverabilityWeight||100;
    return Math.round((x.urgency*cfg.urgencyWeight+x.operationalRisk*cfg.operationalRiskWeight+x.businessImpact*cfg.businessImpactWeight+x.recoverability*cfg.recoverabilityWeight)/total);
  };
  const push=x=>{
    x.urgency=aipClamp(x.urgency);x.operationalRisk=aipClamp(x.operationalRisk);x.businessImpact=aipClamp(x.businessImpact);x.recoverability=aipClamp(x.recoverability);
    x.score=score(x);
    x.band=x.score>=85?'Critical':x.score>=cfg.priorityThreshold?'High':x.score>=50?'Medium':'Standard';
    x.reason=[
      `Urgency ${x.urgency}/100`,
      `Operational risk ${x.operationalRisk}/100`,
      `Business impact ${x.businessImpact}/100`,
      `Recoverability ${x.recoverability}/100`
    ].join(' · ');
    actions.push(x);
  };

  ALL_WOS.filter(w=>w.priority==='Critical'&&w.status!=='Closed'&&w.status!=='Completed').forEach(w=>{
    const overdue=Number(w.overdueDays||0);
    const sla=String(w.slaResult||w.SLA_Result||w.status||'').toLowerCase();
    const money=aipActionMoney(w);
    push({
      id:String(w.id||w.workOrderId||'WO'),
      category:'Critical Work Orders',
      type:'Work Order',
      title:`Critical work order ${w.id||''}`.trim(),
      entity:aipActionAssetText(w)||String(w.plant||w.site||'Portfolio'),
      site:String(w.plant||w.site||''),
      sourceView:'workorderintelligence',
      urgency:/breach|overdue/.test(sla)||overdue>0?100:90,
      operationalRisk:95,
      businessImpact:money>0?Math.min(100,55+Math.log10(Math.max(1,money))*6):72,
      recoverability:82,
      exposureINR:money,
      detail:String(w.desc||w.description||w.task||'Critical work order requiring governed action')
    });
  });

  PREVENTIVE_WOS.filter(w=>w.status==='Overdue Actions'||Number(w.overdueDays||0)>0).forEach(w=>{
    const days=Math.max(1,Number(w.overdueDays||1));
    push({
      id:String(w.id||'PM'),
      category:'Overdue Preventive Tasks',
      type:'Preventive',
      title:`Overdue preventive task ${w.id||''}`.trim(),
      entity:aipActionAssetText(w)||String(w.plant||''),
      site:String(w.plant||w.site||''),
      sourceView:'preventive',
      urgency:Math.min(100,62+days*2),
      operationalRisk:68,
      businessImpact:55,
      recoverability:86,
      exposureINR:aipActionMoney(w),
      detail:String(w.desc||w.task||`Overdue by ${days} day${days===1?'':'s'}`)
    });
  });

  SPARE_PARTS.filter(p=>Number(p.stock||0)<=Number(p.reorder||0)||p.status!=='OK').forEach(p=>{
    const stock=Number(p.stock||0), reorder=Math.max(1,Number(p.reorder||1));
    const shortage=Math.max(0,(reorder-stock)/reorder);
    push({
      id:String(p.id||p.sku||p.partNo||p.part||'SKU'),
      category:'Spares Reorder Requirements',
      type:'Spares',
      title:`Replenish ${p.part||p.name||p.sku||p.id||'spare part'}`,
      entity:String(p.sku||p.partNo||p.part||p.name||''),
      site:String(p.plant||p.site||''),
      sourceView:'inventory',
      urgency:Math.min(100,55+shortage*45),
      operationalRisk:Math.min(100,62+shortage*30),
      businessImpact:52,
      recoverability:90,
      exposureINR:aipActionMoney(p),
      detail:`Stock ${stock} · reorder point ${reorder}${p.status&&p.status!=='OK'?' · '+p.status:''}`
    });
  });

  ASSET_REGISTRY.filter(a=>a.riskBand==='High').forEach(a=>{
    const rs=Number(a.riskScore);
    const risk=Number.isFinite(rs)?(rs<=1?rs*100:rs):82;
    push({
      id:String(a.assetId||a.id||a.tag||'ASSET'),
      category:'High-Risk Assets',
      type:'Asset Risk',
      title:`Review high-risk asset ${a.assetId||a.tag||a.id||''}`.trim(),
      entity:aipActionAssetText(a),
      site:String(a.plant||a.site||''),
      sourceView:'predictive',
      urgency:74,
      operationalRisk:Math.max(80,aipClamp(risk)),
      businessImpact:62,
      recoverability:68,
      exposureINR:aipActionMoney(a),
      detail:String(a.riskReason||a.reason||a.assetClass||'High-risk asset requiring condition review')
    });
  });

  return actions.sort((a,b)=>b.score-a.score||b.urgency-a.urgency||String(a.id).localeCompare(String(b.id)));
}
function aipPriorityActions(){
  const c=aipActionPriorityConfig(), all=aipBuildActionPopulation();
  return {all,priority:all.filter(a=>a.score>=c.priorityThreshold),config:c};
}
function aipActionMixGroup(a){
  const c=String(a?.category||'');
  if(c==='Critical Work Orders'||c==='Overdue Preventive Tasks'||c==='Spares Reorder Requirements')return 'Maintenance & Reliability';
  if(c==='High-Risk Assets')return 'Asset Risk & Performance';
  if(/commercial|ppa|revenue/i.test(c))return 'Commercial & PPA';
  if(/generation|performance|availability|pr/i.test(c))return 'Generation & Performance';
  if(/esg|risk|sustainability/i.test(c))return 'ESG & Risk';
  return 'Other';
}
function aipOpenActionMix(group){
  window.AIP_ACTION_FILTER='Mix:'+String(group||'Other');
  aipRenderActionsModal();
}
window.AIP_ACTION_FILTER='All';
function aipSetActionFilter(f){window.AIP_ACTION_FILTER=f||'All';aipRenderActionsModal()}
function aipActionRoute(view){document.getElementById('aipActionsModal')?.remove();activate(view)}
function aipActionRow(a,i){
  return `<tr>
    <td class="mono">${i+1}</td><td><b>${aipEsc(a.id)}</b><small>${aipEsc(a.type)}</small></td>
    <td>${aipEsc(a.category)}</td><td>${aipEsc(a.entity||'—')}</td>
    <td><span class="aip-ap-score ${a.band.toLowerCase()}">${a.score}</span></td>
    <td class="wrap">${aipEsc(a.reason)}</td>
    <td><button class="btn" onclick="aipActionRoute('${a.sourceView}')">Open</button></td>
  </tr>`;
}
function aipEsc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function aipOpenActions(kind='all'){
  window.AIP_ACTION_FILTER=kind==='priority'?'Priority':'All';
  aipRenderActionsModal();
}
function aipRenderActionsModal(){
  document.getElementById('aipActionsModal')?.remove();
  const {all,priority,config}=aipPriorityActions();
  const counts={
    'Critical Work Orders':all.filter(a=>a.category==='Critical Work Orders').length,
    'Overdue Preventive Tasks':all.filter(a=>a.category==='Overdue Preventive Tasks').length,
    'Spares Reorder Requirements':all.filter(a=>a.category==='Spares Reorder Requirements').length,
    'High-Risk Assets':all.filter(a=>a.category==='High-Risk Assets').length
  };
  const f=window.AIP_ACTION_FILTER||'All';
  const rows=f==='All'?all:f==='Priority'?priority:f.startsWith('Mix:')?priority.filter(a=>aipActionMixGroup(a)===f.slice(4)):all.filter(a=>a.category===f);
  const modal=document.createElement('div');
  modal.id='aipActionsModal';modal.className='aip-actions-modal open';
  modal.innerHTML=`<div class="aip-actions-shell">
    <header><div><h2>Portfolio Actions</h2><p>${all.length} evaluated actions · ${priority.length} Priority Actions at score ≥ ${config.priorityThreshold}</p></div><button class="aip-actions-x" onclick="document.getElementById('aipActionsModal')?.remove()">×</button></header>
    <div class="aip-actions-body">
      <div class="aip-actions-cats">
        <button class="${f==='All'?'active':''}" onclick="aipSetActionFilter('All')"><b>${all.length}</b><span>Evaluated Actions</span></button>
        <button class="${f==='Priority'?'active':''}" onclick="aipSetActionFilter('Priority')"><b>${priority.length}</b><span>Priority Actions</span></button>
        ${f.startsWith('Mix:')?`<button class="active" onclick="aipOpenActionMix('${f.slice(4).replace(/'/g,"\\'")}')"><b>${rows.length}</b><span>${aipEsc(f.slice(4))}</span></button>`:''}
        ${Object.entries(counts).map(([k,v])=>`<button class="${f===k?'active':''}" onclick="aipSetActionFilter('${k.replace(/'/g,"\\'")}')"><b>${v}</b><span>${aipEsc(k)}</span></button>`).join('')}
      </div>
      <div class="aip-actions-main">
        <div class="aip-actions-table-wrap"><table><thead><tr><th>#</th><th>Action</th><th>Category</th><th>Asset / Entity</th><th>Score</th><th>Ranking basis</th><th></th></tr></thead><tbody>${rows.map(aipActionRow).join('')||'<tr><td colspan="7">No actions in this filter.</td></tr>'}</tbody></table></div>
        <aside class="aip-ask-panel">
          <div class="aip-ask-suggestions">
            <button onclick="aipAskSuggestion('Why are these the highest priority actions?')">Why are these highest priority?</button>
            <button onclick="aipAskSuggestion('What should I address in the next 48 hours?')">What should I address next?</button>
            <button onclick="aipAskSuggestion('Show high-risk inverter actions')">Show high-risk inverter actions</button>
          </div>
          <textarea id="aipAskInput" placeholder="Ask about these actions, ranking, site, asset, urgency or exposure..."></textarea>
          <button class="btn primary" onclick="aipAskActions()">Ask AIP</button>
          <div id="aipAskAnswer" class="aip-ask-answer"></div>
        </aside>
      </div>
    </div>
  </div>`;
  document.body.appendChild(modal);
}
function aipAskSuggestion(q){const e=document.getElementById('aipAskInput');if(e)e.value=q;aipAskActions()}
function aipAskActions(){
  const q=String(document.getElementById('aipAskInput')?.value||'').trim();
  const out=document.getElementById('aipAskAnswer');if(!out)return;
  const {all,priority,config}=aipPriorityActions();
  if(!q){out.textContent='Enter a question about the current action population.';return}
  const l=q.toLowerCase();
  let answer='';
  if(/why.*(highest|priority)|highest.*why/.test(l)){
    const top=priority.slice(0,Math.min(5,priority.length));
    answer=top.length?`The highest-priority actions are selected because they exceed the governed score threshold of ${config.priorityThreshold}. `+
      top.map((a,i)=>`${i+1}. ${a.id} (${a.score}/100): ${a.reason}.`).join(' '):`No action currently exceeds the governed priority threshold of ${config.priorityThreshold}.`;
  }else if(/48\s*hours|next\s*(48|two)\s*hours|address.*next/.test(l)){
    const urgent=all.filter(a=>a.urgency>=80).slice(0,8);
    answer=urgent.length?`Based on urgency and the governed ranking, address these first: `+urgent.map(a=>`${a.id} (${a.score}/100, urgency ${a.urgency}/100)`).join('; ')+'.':`No current action has an urgency score of 80 or above.`;
  }else if(/exclude.*(revenue|business impact)|without.*(revenue|business impact)/.test(l)){
    const c={...config,businessImpactWeight:0};
    const denom=c.urgencyWeight+c.operationalRiskWeight+c.recoverabilityWeight||1;
    const reranked=all.map(a=>({...a,scenarioScore:Math.round((a.urgency*c.urgencyWeight+a.operationalRisk*c.operationalRiskWeight+a.recoverability*c.recoverabilityWeight)/denom)})).sort((a,b)=>b.scenarioScore-a.scenarioScore).slice(0,5);
    answer=`Scenario only — business-impact weight excluded. The leading actions become: `+reranked.map(a=>`${a.id} (${a.scenarioScore}/100)`).join('; ')+'. The active governed configuration has not been changed.';
  }else if(/compare/i.test(l)){
    const ids=all.filter(a=>l.includes(String(a.id).toLowerCase())).slice(0,2);
    answer=ids.length===2?`${ids[0].id} scores ${ids[0].score}/100 (${ids[0].reason}); ${ids[1].id} scores ${ids[1].score}/100 (${ids[1].reason}). ${ids[0].score>=ids[1].score?ids[0].id:ids[1].id} ranks higher under the active weights.`:'Include two visible action IDs in the question, for example: “Compare WO-101 and WO-205.”';
  }else{
    let filtered=all;
    if(/inverter/.test(l))filtered=filtered.filter(a=>/inverter/i.test(`${a.entity} ${a.detail}`));
    if(/work order/.test(l))filtered=filtered.filter(a=>a.type==='Work Order');
    if(/spare|inventory/.test(l))filtered=filtered.filter(a=>a.type==='Spares');
    if(/overdue|preventive/.test(l))filtered=filtered.filter(a=>a.type==='Preventive');
    if(/high.?risk/.test(l))filtered=filtered.filter(a=>a.type==='Asset Risk'||a.operationalRisk>=80);
    const money=l.match(/(?:₹|rs\.?\s*)?([\d.]+)\s*(lakh|lakhs|crore|cr)?/i);
    if(/revenue|exposure/.test(l)&&money){
      let n=Number(money[1]);const unit=(money[2]||'').toLowerCase();
      if(unit.startsWith('lakh'))n*=100000;if(unit==='crore'||unit==='cr')n*=10000000;
      filtered=filtered.filter(a=>a.exposureINR>=n);
    }
    const siteMatch=PLANTS.find(p=>l.includes(String(p.name||'').toLowerCase())||l.includes(String(p.id||'').toLowerCase()));
    if(siteMatch)filtered=filtered.filter(a=>String(a.site).toLowerCase()===String(siteMatch.id).toLowerCase()||String(a.site).toLowerCase().includes(String(siteMatch.name).toLowerCase()));
    filtered=filtered.slice(0,10);
    answer=filtered.length?`I found ${filtered.length}${filtered.length===10?' or more':''} matching actions. `+filtered.map(a=>`${a.id} · ${a.category} · score ${a.score}/100`).join('; ')+'.':'No current governed actions match that query.';
  }
  out.textContent=answer;
}

function aipOverviewAttentionSetSite(siteId,siteName){
  if(!siteId)return;
  try{window.AIPPortfolioContext?.set?.(siteId,'overview-attention');}catch(e){console.warn('Unable to set Portfolio Attention context',e);}
}
function aipOverviewAttentionSelectAssetExplorerSite(siteId,siteName){
  const clean=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const desiredId=String(siteId||'').trim();
  const desiredName=String(siteName||window.AIPPortfolioContext?.get?.().plantName||'').trim();
  let attempts=0;
  const apply=()=>{
    const root=document.getElementById('view-assetexplorer');
    if(!root||!root.classList.contains('active'))return false;
    const buttons=[...root.querySelectorAll('[data-ax-site]')];
    const btn=buttons.find(b=>{
      const v=String(b.dataset.axSite||'');
      const txt=String(b.textContent||'');
      return (desiredName&&(clean(v)===clean(desiredName)||clean(txt).includes(clean(desiredName)))) ||
             (desiredId&&(clean(v)===clean(desiredId)||clean(txt).includes(clean(desiredId))));
    });
    if(btn){
      btn.click();
      const siteRow=btn.closest('.ax-site');
      root.querySelectorAll('.ax-site.aip-attention-target').forEach(x=>x.classList.remove('aip-attention-target'));
      if(siteRow){siteRow.classList.add('aip-attention-target');siteRow.scrollIntoView?.({block:'center',behavior:'auto'});}
      else btn.scrollIntoView?.({block:'nearest',behavior:'auto'});
      return true;
    }
    return false;
  };
  const retry=()=>{if(apply())return;if(++attempts<15)setTimeout(retry,80)};
  requestAnimationFrame(retry);
}
function aipOverviewAttentionSite(siteId,siteName){
  aipOverviewAttentionSetSite(siteId,siteName);
  activate('assetexplorer');
  // v87_213: carry the selected site into Asset Explorer's own site selector,
  // rather than merely navigating to the module and leaving its prior selection active.
  aipOverviewAttentionSelectAssetExplorerSite(siteId,siteName);
}
function aipOverviewAttentionAvailability(siteId,siteName){
  aipOverviewAttentionSetSite(siteId,siteName);
  window.AIP_PORTFOLIO_SITE_CONTEXT={plantId:String(siteId||''),plantName:String(siteName||siteId||''),source:'Portfolio Attention · Lowest Availability',timestamp:Date.now()};
  try{sessionStorage.setItem('aip.portfolio.site.context',JSON.stringify(window.AIP_PORTFOLIO_SITE_CONTEXT));}catch(_){}
  activate('portfoliobenchmarking');
  const openPerformance=()=>{
    try{
      const panel=document.querySelector('#view-portfoliobenchmarking [data-pp-panel="performance"]');
      if(panel)panel.dataset.rendered='';
      if(typeof window.setPortfolioPerformanceTab==='function')window.setPortfolioPerformanceTab('performance');
      if(typeof window.renderPortfolioBenchmarking==='function')window.renderPortfolioBenchmarking();
      requestAnimationFrame(()=>document.querySelector('#view-portfoliobenchmarking .v214-attention-row')?.scrollIntoView?.({block:'center',behavior:'auto'}));
    }catch(e){console.warn('Unable to open availability evidence in Portfolio Performance',e);}
  };
  requestAnimationFrame(()=>setTimeout(openPerformance,40));
}
