function corr773Esc(v){return String(v??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function corr773SourceWOs(){
  const rows=correctiveDataSheet('Work Orders');
  const sites=correctiveDataSheet('Sites');
  const siteMap=new Map(sites.map(r=>[String(r.Plant_ID||r.Site_ID||''),String(r.Plant_Name||r.Site_Name||r.Plant_ID||r.Site_ID||'')]));
  return rows.filter(r=>String(r.Maintenance_Type||'').trim().toLowerCase()==='corrective').map(r=>({
    id:String(r.Work_Order_ID||''),
    plantId:String(r.Plant_ID||''),
    plant:String(siteMap.get(String(r.Plant_ID||''))||r.Plant_ID||''),
    assetId:String(r.Asset_ID||''),
    asset:String(r.Asset_Tag||r.Asset_ID||''),
    desc:String(r.Description||''),
    priority:String(r.Priority||''),
    status:String(r.Status||''),
    created:String(r.Created_Date||''),
    slaHours:Number(r.SLA_Hours),
    source:String(r.Source||'')
  })).filter(r=>r.id);
}
function corr773Breakdowns30d(){
  const rows=correctiveDataSheet('Corrective Breakdown Events');
  if(!Array.isArray(rows)||!rows.length)return {value:null,status:'Insufficient Evidence',detail:'No governed dated Corrective Breakdown Events population is available.'};
  const parsed=rows.map(r=>{
    const id=String(r.Breakdown_ID||r.Incident_ID||r.Event_ID||'').trim();
    const raw=r.Event_Start||r.Event_Date_Time||r.Start_Timestamp||r.Event_Time||r.Event_Date;
    const dt=raw?new Date(raw):null;
    return {id,dt,raw};
  }).filter(r=>r.id&&r.dt&&!isNaN(+r.dt));
  if(!parsed.length)return {value:null,status:'Insufficient Evidence',detail:'Breakdown-event records exist but do not contain usable governed event timestamps.'};
  const asOf=new Date(Math.max(...parsed.map(r=>+r.dt)));
  const from=new Date(+asOf-30*86400000);
  const ids=new Set(parsed.filter(r=>r.dt>from&&r.dt<=asOf).map(r=>r.id));
  return {value:ids.size,status:'Derived',detail:`Distinct governed breakdown incidents from ${from.toISOString().slice(0,10)} through ${asOf.toISOString().slice(0,10)}.`};
}
function corr773FmtDate(v){
  const d=v?new Date(v):null;if(!d||isNaN(+d))return '—';
  return String(d.getDate()).padStart(2,'0')+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+d.getFullYear();
}
function corr773OpenWO(id){
  const wo=String(id||'').trim();if(!wo)return;
  CORR773_SELECTED_WO=wo;
  window.AIP_CORRECTIVE_WO_CONTEXT={active:true,returnView:'corrective',workOrderId:wo,search:CORR773_SEARCH};
  const focus=()=>{
    window.AIP_WO_DESIRED_TAB='ledger';
    try{if(typeof window.renderWorkOrderIntelligence==='function')window.renderWorkOrderIntelligence()}catch(_){}
    const root=document.getElementById('view-workorderintelligence');
    if(!root||!root.classList.contains('active'))return false;
    const ledger=root.querySelector('.ops-tab[data-wo12-tab="ledger"]');
    if(ledger&&!ledger.classList.contains('active'))ledger.click();
    const input=document.getElementById('wo12-search');
    if(input){
      input.value=wo;
      input.dispatchEvent(new Event('input',{bubbles:true}));
      input.dispatchEvent(new Event('change',{bubbles:true}));
    }
    root.querySelectorAll('tr.corr773-context-row').forEach(r=>r.classList.remove('corr773-context-row'));
    const esc=(window.CSS&&CSS.escape)?CSS.escape(wo):wo.replace(/["\\]/g,'\\$&');
    const row=root.querySelector(`tr[data-wo12-id="${esc}"]`);
    if(!row)return false;
    row.classList.add('corr773-context-row');
    row.scrollIntoView({block:'center',behavior:'auto'});
    return true;
  };
  window.AIP_WO_DESIRED_TAB='ledger';
  activate('workorderintelligence');
  requestAnimationFrame(()=>requestAnimationFrame(focus));
  [0,40,100,180,320,500].forEach(ms=>setTimeout(focus,ms));
}
