function predictiveDataModeV752(){
  if(window.AIP_SYNTHETIC_ACTIVE===true) return 'Synthetic';
  const t=String(window.APM_DATA_MODE||window.DATA_SOURCE_MODE||window.dataMode||window.currentDataSource||'Excel').toLowerCase();
  return /synthetic|demo data/.test(t)?'Synthetic':'Excel';
}
function predictiveSourceV752(sheet){
  const syn=predictiveDataModeV752()==='Synthetic';
  if(syn){
    const d=window.AIP_INDEPENDENT_SYNTHETIC_DATA||{};
    if(Array.isArray(d[sheet])&&d[sheet].length)return d[sheet];
    return sheet==='Predictive Model Registry'?(window.AIP_PREDICTIVE_SYNTH_MODELS||[]):(window.AIP_PREDICTIVE_SYNTH_VALIDATION||[]);
  }
  try{if(typeof EMBEDDED_EXCEL_DATA!=='undefined'&&Array.isArray(EMBEDDED_EXCEL_DATA[sheet])&&EMBEDDED_EXCEL_DATA[sheet].length)return EMBEDDED_EXCEL_DATA[sheet];}catch(_e){}
  return sheet==='Predictive Model Registry'?(window.AIP_PREDICTIVE_EXCEL_MODELS||[]):(window.AIP_PREDICTIVE_EXCEL_VALIDATION||[]);
}
function predictiveKpisV752(){
  const models=predictiveSourceV752('Predictive Model Registry');
  const rows=predictiveSourceV752('Predictive Validation').filter(r=>String(r.Validation_Status||'Validated').toLowerCase()==='validated');
  const prod=models.filter(r=>String(r.Deployment_Status||r.Status||'').toLowerCase()==='production').length;
  const leads=rows.filter(r=>String(r.Outcome_Class||'').toLowerCase()==='true positive'&&r.First_Detection_Timestamp&&r.Failure_Impact_Timestamp).map(r=>(new Date(r.Failure_Impact_Timestamp)-new Date(r.First_Detection_Timestamp))/86400000).filter(Number.isFinite);
  const lead=leads.length?leads.reduce((a,b)=>a+b,0)/leads.length:null;
  const fp=rows.filter(r=>String(r.Outcome_Class||'').toLowerCase()==='false positive').length;
  const tn=rows.filter(r=>String(r.Outcome_Class||'').toLowerCase()==='true negative').length;
  const fpr=(fp+tn)?100*fp/(fp+tn):null;
  const due=rows.filter(r=>String(r.Actionable_Incident||'').toLowerCase()==='yes'&&String(r.Due_For_Resolution||'').toLowerCase()==='yes');
  const resolved=due.filter(r=>String(r.Resolution_Status||'').toLowerCase()==='resolved').length;
  const resolution=due.length?100*resolved/due.length:null;
  return {prod,lead,fpr,resolution,validated:rows.length,leadN:leads.length,fp,tn,due:due.length,resolved,mode:predictiveDataModeV752()};
}


/* ========================= v87_754 PREDICTIVE WORKSPACE ========================= */
let P754_SELECTED_CLASS='All';
let P754_SELECTED_ALERT='';
let P766_PREDICTION_PINNED=false;
let P771_THRESHOLD_DAYS='All';
let P754_CONTEXT_ALERT='';
let P754_ALLOW_EMPTY_SELECTION=false;
function p754ActiveSheet(name){
  const syn=predictiveDataModeV752()==='Synthetic';
  if(syn){
    const d=window.AIP_INDEPENDENT_SYNTHETIC_DATA||{};
    const p=d.platformSyntheticData||{};
    if(Array.isArray(p[name]))return p[name];
    if(Array.isArray(d[name]))return d[name];
  }
  const imp=window.APM_IMPORTED_DATA||{};
  if(!syn&&Array.isArray(imp[name])&&imp[name].length)return imp[name];
  try{if(typeof EMBEDDED_EXCEL_DATA!=='undefined'&&Array.isArray(EMBEDDED_EXCEL_DATA[name]))return EMBEDDED_EXCEL_DATA[name];}catch(_e){}
  return [];
}
function p754Esc(v){return String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]||c))}
function p754Num(v){const n=Number(v);return Number.isFinite(n)?n:null}
function p754Date(v){const d=new Date(String(v||'').replace(' ','T'));return Number.isFinite(+d)?d:null}
function p754FmtDate(d){if(!d)return '—';return d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function p754Portfolio(){
  const alerts=p754ActiveSheet('AI Alerts & RUL'), assets=p754ActiveSheet('Asset Master'), sites=p754ActiveSheet('Sites'), recs=p754ActiveSheet('Prescriptive Actions'), wos=p754ActiveSheet('Work Orders');
  const am=new Map(assets.map(a=>[String(a.Asset_ID||''),a])), sm=new Map(sites.map(s=>[String(s.Plant_ID||''),s])), rm=new Map(recs.map(r=>[String(r.Alert_ID||''),r]));
  const woByAlert=new Map(); wos.forEach(w=>{const s=String(w.Source||'');if(s)woByAlert.set(s,w)});
  const rows=alerts.map(a=>{
    const asset=am.get(String(a.Asset_ID||''))||{}, site=sm.get(String(a.Plant_ID||''))||{}, rec=rm.get(String(a.Alert_ID||''))||{}, wo=woByAlert.get(String(a.Alert_ID||''))||null;
    const risk=p754Num(a.Risk_Score),rul=p754Num(a.RUL_Days),conf=p754Num(a.Confidence_Pct),dt=p754Date(a.Alert_Timestamp);
    const threshold=(dt&&rul!=null)?new Date(+dt+rul*86400000):null;
    return {id:String(a.Alert_ID||''),assetId:String(a.Asset_ID||''),tag:String(a.Asset_Tag||asset.Asset_Tag||a.Asset_ID||''),assetClass:String(asset.Asset_Class||'Unclassified'),description:String(asset.Description||a.Component||''),component:String(a.Component||asset.Description||''),plantId:String(a.Plant_ID||''),plant:String(site.Plant_Name||a.Plant_ID||''),model:String(a.Model||''),risk:risk,rul:rul,confidence:conf,tier:String(a.Risk_Tier||''),status:String(a.Alert_Status||''),evidence:String(a.Evidence_Summary||''),alertDate:dt,thresholdDate:threshold,action:String(rec.Recommended_Action||''),rationale:String(rec.Rationale||''),wo:wo};
  }).filter(r=>r.id&&r.assetId&&r.risk!=null&&r.rul!=null);
  const maxDate=rows.map(r=>r.alertDate).filter(Boolean).sort((a,b)=>b-a)[0]||null;
  return {rows,assets,sites,recs,wos,asOf:maxDate};
}
function p754RiskColor(r){return r>=.8?'#b84036':r>=.65?'#d38420':r>=.5?'#d8aa28':'#2f8b62'}
function p754TierClass(t,r){const s=String(t||'').toLowerCase();return s.includes('critical')||r>=.8?'high':s.includes('high')||r>=.65?'high':s.includes('medium')||r>=.45?'medium':'low'}
function p754SetClass(c){
  P754_SELECTED_CLASS=c||'All';
  P754_SELECTED_ALERT='';
  P766_PREDICTION_PINNED=false;
  renderPredictive();
}
function p771SetThreshold(days){
  P771_THRESHOLD_DAYS=days==='All'?'All':Number(days);
  P754_SELECTED_ALERT='';
  P766_PREDICTION_PINNED=false;
  renderPredictive();
}
function p754SelectAlert(id){
  P754_CONTEXT_ALERT='';
  P754_ALLOW_EMPTY_SELECTION=false;
  P754_SELECTED_ALERT=String(id||'');
  P766_PREDICTION_PINNED=!!P754_SELECTED_ALERT;
  renderPredictive();
  requestAnimationFrame(()=>document.querySelector('.p754-intel')?.scrollIntoView({block:'nearest',behavior:'smooth'}));
}
function p754ClearEvidenceContext(e){
  try{e?.preventDefault?.();e?.stopPropagation?.()}catch(_){}
  P754_CONTEXT_ALERT='';
  P754_ALLOW_EMPTY_SELECTION=true;
  P754_SELECTED_ALERT='';
  P766_PREDICTION_PINNED=false;
  try{
    if(window.AIP_DI_EVIDENCE_CONTEXT?.target==='predictive')window.AIP_DI_EVIDENCE_CONTEXT=null;
    if(window.AIP_ATV_TARGET_CONTEXT?.target==='predictive')window.AIP_ATV_TARGET_CONTEXT=null;
    if(window.AIP_CONTEXT_NAV?.target==='predictive')window.AIP_CONTEXT_NAV=null;
  }catch(_){}
  renderPredictive();
  return false;
}
function p766ClearPredictionSelection(){
  P754_SELECTED_ALERT='';
  P766_PREDICTION_PINNED=false;
  renderPredictive();
  requestAnimationFrame(()=>document.querySelector('#view-predictive .p754-horizon')?.scrollIntoView({block:'nearest',behavior:'smooth'}));
}
let P758_PREDICTION_SEARCH='';
function p758FilterPredictionRegister(value){
  P758_PREDICTION_SEARCH=String(value||'');
  const q=P758_PREDICTION_SEARCH.trim().toLowerCase();
  const table=document.querySelector('#view-predictive .p754-table table');
  if(!table)return;
  table.querySelectorAll('tbody tr[data-p754-alert]').forEach(tr=>{
    tr.hidden=!!q&&!String(tr.textContent||'').toLowerCase().includes(q);
  });
  const clear=document.getElementById('p758-pred-clear');
  if(clear)clear.hidden=!q;
}
function p758ClearPredictionRegister(){
  P758_PREDICTION_SEARCH='';
  const input=document.getElementById('p758-pred-search');
  if(input)input.value='';
  p758FilterPredictionRegister('');
  input?.focus();
}
function p761OpenLinkedWorkOrder(woId,alertId,assetTag,plantName){
  const id=String(woId||'').trim();
  if(!id){window.toast?.('No linked work order for this prediction');return}

  window.AIP_PREDICTIVE_WO_CONTEXT={
    workOrderId:id,
    alertId:String(alertId||''),
    assetTag:String(assetTag||''),
    plant:String(plantName||''),
    returnView:'predictive',
    predictiveClass:P754_SELECTED_CLASS,
    predictiveAlert:P754_SELECTED_ALERT,
    predictiveSearch:P758_PREDICTION_SEARCH,
    predictivePinned:P766_PREDICTION_PINNED,
    predictiveThreshold:P771_THRESHOLD_DAYS,
    active:true
  };

  const renderLedger=()=>{
    window.AIP_WO_DESIRED_TAB='ledger';
    try{if(typeof window.renderWorkOrderIntelligence==='function')window.renderWorkOrderIntelligence()}catch(_){}
    const root=document.getElementById('view-workorderintelligence');
    if(!root||!root.classList.contains('active'))return false;

    const ledgerTab=root.querySelector('.ops-tab[data-wo12-tab="ledger"]');
    if(ledgerTab&&!ledgerTab.classList.contains('active')){
      ledgerTab.click();
      try{if(typeof window.renderWorkOrderIntelligence==='function')window.renderWorkOrderIntelligence()}catch(_){}
    }

    const input=document.getElementById('wo12-search');
    if(input){
      input.value=id;
      input.dispatchEvent(new Event('input',{bubbles:true}));
      input.dispatchEvent(new Event('change',{bubbles:true}));
    }

    root.querySelectorAll('tr.p761-predictive-wo-match,tr.p758-wo-context-row').forEach(r=>{
      r.classList.remove('p761-predictive-wo-match','p758-wo-context-row');
    });
    const escId=(window.CSS&&CSS.escape)?CSS.escape(id):id.replace(/["\\]/g,'\\$&');
    const row=root.querySelector(`tr[data-wo12-id="${escId}"]`);
    if(!row)return false;
    row.classList.add('p761-predictive-wo-match');
    row.scrollIntoView({block:'center',behavior:'auto'});
    return true;
  };

  window.AIP_WO_DESIRED_TAB='ledger';
  activate('workorderintelligence');
  requestAnimationFrame(()=>requestAnimationFrame(renderLedger));
  [0,30,80,150,260,420].forEach(ms=>setTimeout(renderLedger,ms));
}function p754ModelCategory(name){const s=String(name||'').toLowerCase();if(/dga|survival|rul|risk/.test(s))return 'Prognosis / RUL';if(/drift|string|current|thermal|trip|fusion/.test(s))return 'Condition / degradation';return 'Predictive model'}
function p754CoverageHtml(p){
  const unique=(arr,k)=>new Set(arr.map(x=>x[k]).filter(Boolean)).size, rows=p.rows;
  const active=rows.filter(r=>/^(open|acknowledged|active|investigating)$/i.test(String(r.status||'').trim()));
  const converted=rows.filter(r=>/converted\s+to\s+wo/i.test(String(r.status||'')));
  const models=new Set(rows.map(r=>String(r.model||'').trim()).filter(Boolean));
  const vals=[
    [p.assets.length,'Asset population'],
    [unique(rows,'assetId'),'Predictive evidence'],
    [models.size,'Models used'],
    [unique(active,'assetId'),'Active conditions'],
    [unique(converted,'assetId'),'Converted to WO'],
    [unique(active.filter(r=>r.rul!=null&&r.rul<=30),'assetId'),'≤30d horizon']
  ];
  return `<div class="p754-coverage">${vals.map(x=>`<div class="p754-cov"><b>${Number(x[0]).toLocaleString('en-IN')}</b><span>${x[1]}</span></div>`).join('')}</div>`;
}
function p754ClassHtml(p,filtered){
  const classes=[...new Set(p.rows.map(r=>r.assetClass))].sort();
  const accents={'All':'#315c72','Inverter':'#2e86ab','SCB':'#8a5a9f','Tracker':'#c9821f','Transformer':'#7a5b35','Switchgear':'#b84036','Weather Station':'#2f8b62'};
  const cards=['All',...classes].map(c=>{
    const rr=c==='All'?p.rows:p.rows.filter(r=>r.assetClass===c);
    const min=rr.length?Math.min(...rr.map(r=>r.rul)):null;
    const accent=accents[c]||'#607d8b';
    return `<button class="p754-class ${P754_SELECTED_CLASS===c?'active':''}" style="--p755-accent:${accent}" onclick="p754SetClass('${p754Esc(c)}')" title="Filter Emerging Predictive Conditions by ${p754Esc(c==='All'?'all asset classes':c)}"><div class="n">${rr.length}</div><div class="nm">${p754Esc(c==='All'?'All asset classes':c)}</div><div class="meta">${min==null?'No RUL':`nearest threshold ${min}d`}</div></button>`;
  }).join('');
  const filterIcon=`<span class="p755-filter-icon" title="Filter by asset class" aria-label="Filter by asset class"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h18l-7 8v5l-4 2v-7L3 5z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></svg></span>`;
  return `<div class="p754-card"><div class="p754-head"><div><h3>Emerging Predictive Conditions</h3></div><div class="p755-condition-tools"><span class="p755-condition-count">${filtered.length} <small>conditions</small></span>${filterIcon}</div></div><div class="p754-class-grid">${cards}</div></div>`;
}
function p754HorizonHtml(rows,selectedId){
  const top=rows.slice().sort((a,b)=>(a.rul-b.rul)||(b.risk-a.risk)).slice(0,10), maxDays=180;
  const axis=[0,15,30,60,120,180].map(v=>`<span style="left:${v/maxDays*100}%">${v}d</span>`).join('');
  const filters=['All',15,30,60,120].map(v=>{
    const active=String(P771_THRESHOLD_DAYS)===String(v);
    const label=v==='All'?'All':`≤${v}d`;
    return `<button type="button" class="p771-threshold-chip ${active?'active':''}" onclick="p771SetThreshold('${v}')" title="${v==='All'?'Show all qualified predictions':'Show predictions with source RUL at or below '+v+' days'}">${label}</button>`;
  }).join('');
  const body=top.map(r=>{
    const pos=Math.min(100,Math.max(1,r.rul/maxDays*100)),bar=p754RiskColor(r.risk);
    const locked=P766_PREDICTION_PINNED&&r.id===selectedId;
    return `<div class="p754-hrow ${r.id===selectedId?'selected':''} ${locked?'p771-locked':''}" onclick="p754SelectAlert('${p754Esc(r.id)}')">
      <div class="p754-hasset"><b>${p754Esc(r.tag)} · ${p754Esc(r.assetClass)}</b><span>${p754Esc(r.plant)} · ${p754Esc(r.component)}</span></div>
      <div class="p771-horizon-middle">
        <div class="p754-track" title="Forecast origin ${p754FmtDate(r.alertDate)} · predicted threshold ${p754FmtDate(r.thresholdDate)}">
          <i class="p754-rulbar" style="width:${pos}%;background:${bar}"></i>
          <i class="p771-origin-marker" style="left:0%"></i>
          <i class="p754-marker p771-threshold-marker" style="left:${pos}%"></i>
        </div>
        <div class="p771-date-row"><span class="p771-origin-date"><i></i>${p754FmtDate(r.alertDate)}</span><span class="p771-threshold-date">${p754FmtDate(r.thresholdDate)}<i></i></span></div>
      </div>
      <div class="p754-rulval">${r.rul.toFixed(0)} days<small>${Math.round(r.risk*100)}% risk</small>${locked?'<em>LOCKED</em>':''}</div>
    </div>`;
  }).join('');
  return `<div class="p754-card p754-horizon">
    <div class="p754-head">
      <div><h3>Predictive Intervention Horizon</h3><div class="sub">Shortest remaining source RUL first · threshold = forecast origin + source RUL</div></div>
      <div class="p766-horizon-actions">
        <div class="p771-threshold-filter" aria-label="Threshold horizon filter"><span>Threshold</span>${filters}</div>
        <div class="p771-legend"><span class="origin"><i></i>Forecast Origin</span><span class="threshold"><i></i>Predicted Threshold</span></div>
        ${P766_PREDICTION_PINNED?'<button type="button" class="p766-clear-selection" onclick="p766ClearPredictionSelection()" title="Release the locked prediction and return to the first qualified record in the current filters">Clear Selection ×</button>':''}
      </div>
    </div>
    <div class="p754-scale"><div></div><div class="p754-scale-axis">${axis}</div><div></div></div>
    ${body||'<div class="sub p771-no-records">No qualified predictive records in the selected asset-class and threshold scope.</div>'}
  </div>`;
}
function p754IntelHtml(sel){
  if(!sel)return `<div class="p754-card"><div class="p754-head"><div><h3>Selected Prediction Intelligence</h3><div class="sub">Select a horizon row or register record to inspect its evidence chain.</div></div></div></div>`;
  const nodes=[
    ['signal','Signal',sel.evidence||sel.status],
    ['condition','Condition',`${sel.assetClass} · ${sel.component}`],
    ['model','Prediction Model',sel.model||'Model not identified'],
    ['action','Recommended Action',sel.action||'Review prediction and maintenance response']
  ];
  const woId=sel.wo?String(sel.wo.Work_Order_ID||sel.wo.id||'').trim():'';
  const woAction=woId
    ? `<button class="primary" onclick="p761OpenLinkedWorkOrder('${p754Esc(woId)}','${p754Esc(sel.id)}','${p754Esc(sel.tag)}','${p754Esc(sel.plant)}')">Open ${p754Esc(woId)} ↗</button>`
    : `<button class="secondary p758-no-wo" type="button" disabled>No linked work order</button>`;
  return `<div class="p754-card"><div class="p754-head"><div><h3>Selected Prediction Intelligence</h3><div class="sub p757-selected-context">${p754Esc(sel.plant)} · ${p754Esc(sel.tag)} · ${p754Esc(sel.id)}</div></div><span class="p754-pill ${p754TierClass(sel.tier,sel.risk)}">${p754Esc(sel.status||sel.tier||'Active')}</span></div><div class="p754-chain p760-chain">${nodes.map(n=>`<div class="p754-node ${n[0]}"><div class="k">${n[1]}</div><div class="v">${p754Esc(n[2])}</div></div>`).join('')}</div><div class="p754-btns">${woAction}</div></div>`;
}
function p754AssuranceHtml(rows){
  const by={};rows.forEach(r=>{if(!r.model)return;(by[r.model]||(by[r.model]={n:0,c:0,r:0}));by[r.model].n++;by[r.model].c+=r.confidence||0;by[r.model].r+=r.risk||0});
  const mods=Object.entries(by).map(([name,x])=>({name,n:x.n,conf:x.n?x.c/x.n:0,risk:x.n?x.r/x.n:0})).sort((a,b)=>b.n-a.n);
  const modelRows=mods.map(m=>`<div class="p754-modelrow"><div class="name" title="${p754Esc(m.name)}">${p754Esc(m.name)}</div><div class="p754-modelbar" title="Average confidence ${m.conf.toFixed(1)}%"><i style="width:${Math.max(2,Math.min(100,m.conf))}%"></i></div><div class="cnt">${m.n} · ${m.conf.toFixed(0)}%</div></div>`).join('');
  const buckets=[[0,15],[16,30],[31,60],[61,Infinity]].map(([a,b])=>rows.filter(r=>r.rul>=a&&r.rul<=b).length);
  return `<div class="p754-card"><div class="p754-head"><div><h3>Model Assurance & RUL Distribution</h3><div class="sub">Model usage and mean prediction confidence in the selected scope</div></div></div><div class="p754-assurance">${modelRows}</div><div class="p754-dist"><div class="p754-bucket"><b>${buckets[0]}</b><span>0–15d</span></div><div class="p754-bucket"><b>${buckets[1]}</b><span>16–30d</span></div><div class="p754-bucket"><b>${buckets[2]}</b><span>31–60d</span></div><div class="p754-bucket"><b>${buckets[3]}</b><span>&gt;60d</span></div></div></div>`;
}
function p754TableHtml(rows,selectedId){
  const sorted=rows.slice().sort((a,b)=>(a.rul-b.rul)||(b.risk-a.risk));
  const selected=sorted.find(r=>r.id===selectedId);
  const rr=selected?[selected,...sorted.filter(r=>r.id!==selectedId)]:sorted;
  const ctx=String(P754_CONTEXT_ALERT||'');
  const contextBanner=ctx?`<div class="p754-native-context"><span><b>Selected prediction context</b> · ${p754Esc(ctx)}</span><button type="button" aria-label="Clear selected prediction context" title="Clear selected prediction context" onclick="return p754ClearEvidenceContext(event)">×</button></div>`:'';
  return `<div class="card p754-table" data-aip-v288-skip-top="1">
    <div class="p758-pred-register-head"><div class="panel-title"><div><h3>Qualified Prediction Register</h3></div></div><div class="p758-pred-search-wrap"><input id="p758-pred-search" type="search" autocomplete="off" spellcheck="false" placeholder="Search all columns…" value="${p754Esc(P758_PREDICTION_SEARCH)}" oninput="p758FilterPredictionRegister(this.value)"><button id="p758-pred-clear" type="button" onclick="p758ClearPredictionRegister()" ${P758_PREDICTION_SEARCH?'':'hidden'} aria-label="Clear search">×</button></div></div>
    ${contextBanner}
    <div class="p754-native-topscroll" role="scrollbar" aria-label="Horizontal table scroll"><div class="p754-native-topscroll-spacer"></div></div>
    <div class="table-scroll p754-native-bottomscroll"><table><thead><tr><th>Alert</th><th>Site</th><th>Asset</th><th>Class</th><th>Condition / Component</th><th>Model</th><th>Risk</th><th>RUL</th><th>Predicted Threshold</th><th>Confidence</th><th>Status</th></tr></thead><tbody>${rr.map(r=>`<tr data-p754-alert="${p754Esc(r.id)}" class="${r.id===selectedId?'p754-selected ':''}${ctx&&r.id===ctx?'p754-context-row':''}" onclick="p754SelectAlert('${p754Esc(r.id)}')"><td class="mono">${r.id===selectedId?'<span class="p757-row-mark">●</span> ':''}${p754Esc(r.id)}</td><td>${p754Esc(r.plant)}</td><td class="mono">${p754Esc(r.tag)}</td><td>${p754Esc(r.assetClass)}</td><td>${p754Esc(r.component)}</td><td>${p754Esc(r.model)}</td><td><span class="p754-pill ${p754TierClass(r.tier,r.risk)}">${Math.round(r.risk*100)}%</span></td><td class="mono">${r.rul.toFixed(0)}d</td><td class="mono p771-threshold-cell">${p754FmtDate(r.thresholdDate)}</td><td class="mono">${r.confidence==null?'—':r.confidence.toFixed(0)+'%'}</td><td>${p754Esc(r.status)}</td></tr>`).join('')}</tbody></table></div>
  </div>`;
}
function p754BindRegisterScroll(){
  const host=document.querySelector('#view-predictive .p754-table');
  if(!host)return false;
  const top=host.querySelector('.p754-native-topscroll');
  const spacer=host.querySelector('.p754-native-topscroll-spacer');
  const bottom=host.querySelector('.p754-native-bottomscroll');
  const table=bottom?.querySelector('table');
  if(!top||!spacer||!bottom||!table)return false;
  const width=Math.max(table.scrollWidth,bottom.scrollWidth,bottom.clientWidth);
  spacer.style.width=Math.ceil(width)+'px';
  top.style.display=width>bottom.clientWidth+2?'block':'none';
  let lock=false;
  top.onscroll=()=>{if(lock)return;lock=true;bottom.scrollLeft=top.scrollLeft;lock=false};
  bottom.onscroll=()=>{if(lock)return;lock=true;top.scrollLeft=bottom.scrollLeft;lock=false};
  top.scrollLeft=bottom.scrollLeft;
  return true;
}
function renderPredictive(){
  const pk=predictiveKpisV752(),p=p754Portfolio();
  let classFiltered=P754_SELECTED_CLASS==='All'?p.rows:p.rows.filter(r=>r.assetClass===P754_SELECTED_CLASS);
  if(!classFiltered.length&&P754_SELECTED_CLASS!=='All'){P754_SELECTED_CLASS='All';classFiltered=p.rows}
  let filtered=P771_THRESHOLD_DAYS==='All'?classFiltered:classFiltered.filter(r=>r.rul!=null&&r.rul<=Number(P771_THRESHOLD_DAYS));
  if(P754_SELECTED_ALERT&&!filtered.some(r=>r.id===P754_SELECTED_ALERT)){
    P766_PREDICTION_PINNED=false;
    P754_SELECTED_ALERT='';
  }
  if(!P754_SELECTED_ALERT&&!P754_ALLOW_EMPTY_SELECTION){
    P754_SELECTED_ALERT=(filtered.slice().sort((a,b)=>(a.rul-b.rul)||(b.risk-a.risk))[0]||{}).id||'';
  }
  const sel=filtered.find(r=>r.id===P754_SELECTED_ALERT)||null;
  document.getElementById('view-predictive').innerHTML=`
    <div class="view-head predictive-view-head"><div class="predictive-title-block"><div class="eyebrow" style="color:var(--teal)">CONDITION → PROGNOSIS → INTERVENTION</div><h1>Predictive</h1></div><div class="predictive-head-actions"></div></div>
    ${aipMaintenanceMasterKpis([
      ['Predictive Models in Production', String(pk.prod)],
      ['Avg. Detection Lead Time', `${pk.lead==null?'N/A':pk.lead.toFixed(2)}<span class="aip-kpi-unit">days</span>`],
      ['False Positive Rate', `${pk.fpr==null?'N/A':pk.fpr.toFixed(2)}<span class="aip-kpi-unit">%</span>`],
      ['Predictive Incident Resolution Rate', `${pk.resolution==null?'N/A':pk.resolution.toFixed(2)}<span class="aip-kpi-unit">%</span>`]
    ])}
    <div class="card aip-predictive-kpi-basis" style="margin:-4px 0 12px;padding:0;border:1px solid #e6a6b8;border-left:3px solid #d96f8f;background:#fff3f7;"><button type="button" class="aip-predictive-kpi-basis-toggle" aria-expanded="false" onclick="(function(b){const d=b.nextElementSibling;const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));d.style.display=open?'none':'block';b.querySelector('.aip-predictive-kpi-basis-sign').textContent=open?'+':'−';})(this)" style="width:100%;border:0;background:transparent;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;cursor:pointer;text-align:left;font:700 10px Arial;color:#34576a;"><span>Predictive KPI Calculation Basis</span><span class="aip-predictive-kpi-basis-sign" aria-hidden="true" style="font:700 16px/1 Arial;color:#244f73;">+</span></button><div class="aip-predictive-kpi-basis-detail" style="display:none;padding:0 12px 9px;"><div style="font:9px/1.45 Arial;color:#5e737e;"><b style="color:#173f5f;">Production Models</b> = Production-status records in Predictive Model Registry · <b style="color:#173f5f;">Detection Lead Time</b> = average(Failure/Impact time − first valid detection) across ${pk.leadN} validated true positives · <b style="color:#173f5f;">False Positive Rate</b> = ${pk.fp} FP ÷ (${pk.fp} FP + ${pk.tn} TN) · <b style="color:#173f5f;">Incident Resolution Rate</b> = ${pk.resolved} resolved ÷ ${pk.due} actionable incidents due for resolution.</div><div style="font:8.8px/1.4 Arial;color:#5e737e;margin-top:4px;"><b style="color:#173f5f;">Production Models:</b> ${predictiveSourceV752('Predictive Model Registry').filter(r=>String(r.Deployment_Status||r.Status||'').toLowerCase()==='production').map(r=>r.Model_Name||r.Model||'').join(' · ')}</div></div></div>
    <div class="section-note" style="margin-bottom:10px"><b>Predictive scope.</b> AIP displays assets only where the active dataset contains an exact Asset_ID-linked predictive record with model risk and RUL evidence. The workspace does not manufacture predictions for unmonitored assets. Forecast threshold = alert timestamp + source RUL; recommended action is taken from the linked Prescriptive Actions record where available.</div>
    ${p754CoverageHtml(p)}
    <div class="p754-main">${p754ClassHtml(p,filtered)}${p754HorizonHtml(filtered,P754_SELECTED_ALERT)}</div>
    <div class="p754-intel">${p754IntelHtml(sel)}${p754AssuranceHtml(filtered)}</div>
    ${p754TableHtml(filtered,P754_SELECTED_ALERT)}
  `;
  try{window.AIPKPIMaster?.scan?.(document.getElementById('view-predictive'))}catch(_e){}
  requestAnimationFrame(()=>p754BindRegisterScroll());
  if(P758_PREDICTION_SEARCH)requestAnimationFrame(()=>p758FilterPredictionRegister(P758_PREDICTION_SEARCH));
}

/* =============================== PRESCRIPTIVE =============================== */
function renderPrescriptive(){
  const repairNow = PRESCRIPTIVE_RECS.filter(r=>r.action==="Repair now").length;
  const accepted = PRESCRIPTIVE_RECS.filter(r=>r.accepted).length;
  const acceptRate = Math.round(accepted/PRESCRIPTIVE_RECS.length*100);
  const totalCostAvoided = PRESCRIPTIVE_RECS.reduce((s,r)=>s+r.costAvoided,0);
  const avgConfidence = Math.round(PRESCRIPTIVE_RECS.reduce((s,r)=>s+r.confidence,0)/PRESCRIPTIVE_RECS.length);
  const actionCounts = RX_ACTIONS.map(a=> PRESCRIPTIVE_RECS.filter(r=>r.action===a).length);

  document.getElementById("view-prescriptive").innerHTML = `
    <div class="view-head">
      <div>
        <div class="eyebrow" style="color:var(--violet)">AI DECISION OPTIMIZATION</div>
        <h1>Prescriptive Maintenance</h1>
        
      
      
    </div>
    </div>

    <div class="section-note"><b>Definition.</b> Where Predictive maintenance answers "what will fail and when," Prescriptive maintenance answers "what should we do about it, and when." Each recommendation below is generated by the Maintenance Planning Agent (Section 9) from the same RUL/risk scores in the Predictive tab, then costed against deferring the action to the next scheduled visit or outage window.</div>

    <div class="grid g4" style="margin-bottom:14px;">
      <div class="card">
        <div class="kpi-label">Repair-Now Recommendations</div>
        <div class="kpi-value">${repairNow}</div>
        <div class="kpi-delta down">SLA-critical risk window</div>
      </div>
      <div class="card">
        <div class="kpi-label">Agent Accept Rate</div>
        <div class="kpi-value">${acceptRate}<span class="kpi-unit">%</span></div>
        <div class="kpi-delta up">Accepted without human override</div>
      </div>
      <div class="card">
        <div class="kpi-label">Est. Cost Avoided</div>
        <div class="kpi-value">${fmtINR(totalCostAvoided)}</div>
        <div class="kpi-delta up">vs. deferred-action cost</div>
      </div>
      <div class="card">
        <div class="kpi-label">Avg. Recommendation Confidence</div>
        <div class="kpi-value">${avgConfidence}<span class="kpi-unit">%</span></div>
        <div class="kpi-delta flat">Model + agent blended score</div>
      </div>
    </div>

    <div class="card" style="margin-bottom:14px;">
      <div class="panel-title"><div><h3>Recommendations by Action Type</h3><div class="sub">Ranked queue, current cycle</div></div></div>
      <div class="chart-wrap h220"><canvas id="chartRxActions"></canvas></div>
    </div>

    <div class="card">
      <div class="panel-title"><div><h3>Ranked Action Queue</h3><div class="sub">${PRESCRIPTIVE_RECS.length} recommendations · sorted by risk score</div></div></div>
      <div class="table-scroll">
        <table>
          <thead><tr><th>Asset</th><th>Site</th><th>Recommended Action</th><th>Rationale</th><th>Cost Avoided</th><th>Confidence</th><th>Agent</th><th>Decision</th></tr></thead>
          <tbody>
            ${PRESCRIPTIVE_RECS.map(r=>`
              <tr>
                <td>${r.asset}</td>
                <td>${r.plant}</td>
                <td><span class="tag ${r.action==='Repair now'?'open':r.action==='Bundle with next visit'?'scheduled':r.action==='Defer to outage window'?'adaptive':'ghost'}">${r.action}</span></td>
                <td class="wrap" style="min-width:260px;font-size:11.75px;color:var(--ink-soft);">${r.rationale}</td>
                <td class="mono">${fmtINR(r.costAvoided)}</td>
                <td class="mono">${r.confidence}%</td>
                <td>${r.accepted?'<span class="tag agent-accepted">Accepted</span>':'<span class="tag agent-pending">Pending review</span>'}</td>
                <td><button class="woi-btn" onclick="openWOIntelligence('${r.id}','prescriptive')">Review &amp; Raise WO</button></td>
              </tr>`).join("")}
          </tbody>
        </table>
      </div>
    </div>
  `;
}


/* ===== AI-guided Work Order Intelligence ===== */

const OPS_WO={tab:'command',filter:'All',search:'',audit:[]};
window.OPS_WO = OPS_WO;
const OPS_CREW={tab:'optimizer',selected:null,optimized:false,ledger:[]};
function opsEsc(v){return String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));}
function opsWorkOrderDataMode(){
 const text=String(window.APM_DATA_MODE||window.DATA_SOURCE_MODE||window.dataMode||window.currentDataSource||'').toLowerCase();
 return /excel|upload|bundled/.test(text)?'excel':'synthetic';
}
function opsPrimaryConstraint(w){
 const closed=new Set(['Closed','Completed','ERP Closed','Cancelled','Verified']);
 const status=String(w?.status||w?.Status||'').trim();
 if(closed.has(status))return 'No Constraint';

 const mode=opsWorkOrderDataMode();

 /* Synthetic logic: "Open" is an active lifecycle state, not a blocker.
    It must not be counted in Active Constraints simply because synthetic
    fallback fields such as crew/parts are blank or generated. */
 if(mode==='synthetic' && /^Open$/i.test(status))return 'No Constraint';

 /* Excel mode preserves the explicit workbook-derived primary constraint. */
 const supplied=String(w?.Primary_Work_Order_Constraint||w?.primaryConstraint||'').trim();
 if(mode==='excel' && supplied){
   return supplied==='Parts Pending'?'Parts Constraint':supplied;
 }

 /* Both modes then use measurable blocking conditions. */
 const parts=String(w?.parts||w?.Parts_Status||'').trim();
 if(/Awaiting Part|Parts Pending|Parts Constraint|Part Shortage/i.test(status+' '+parts))return 'Parts Constraint';

 const permitRaw=String(w?.Editable_Permit_Status||w?.Permit_Status||w?.permit||'').trim();
 if(permitRaw==='Required'||/Awaiting Permit|Permit Pending|Access Pending/i.test(permitRaw))return 'Permit / Access Pending';

 const approval=String(w?.Approval_Status||w?.approval||'').trim();
 if(/Pending/i.test(approval)||status==='Awaiting Approval')return 'Approval Pending';

 const crew=String(w?.crew||w?.Assigned_Crew||w?.Crew_ID||'').trim();
 const crewState=String(w?.Crew_Selection_Status||'').trim();
 const crewRelevant=/Ready to Schedule|Scheduled|Dispatched|In Progress/i.test(status);
 if(crewRelevant && (!crew||(crewState&&crewState!=='Populated')))return 'Crew / Scheduling Constraint';

 const erp=String(w?.erp||w?.ERP_Sync_Status||'').toLowerCase();
 if(/error|failed|rejected/.test(erp))return 'Other Blockers';

 return 'No Constraint';
}
function opsWOs(){const mode=opsWorkOrderDataMode();return (ALL_WOS||[]).map((w,i)=>{w.id=w.id||w.Work_Order_ID||('WO-'+(4000+i));w.asset=w.asset||w.Asset_ID||'Asset';w.plant=w.plantName||w.plant||w.Plant_Name||w.Plant_ID||'Site';w.type=w.type||w.Work_Type||w.Maintenance_Type||'Corrective';w.priority=w.priority||w.Priority||['Critical','High','Medium','Low'][i%4];w.status=w.status||w.Status||['Draft','Awaiting Approval','Approved','Ready to Schedule','Scheduled','In Progress'][i%6];w.desc=w.desc||w.Description||'Maintenance intervention';w.parts=w.parts||w.Parts_Status||(mode==='synthetic'?(i%4?'Ready':'Awaiting Parts'):'Ready');w.permit=w.permit||w.Permit_Status||(mode==='synthetic'?(i%5?'Ready':'Awaiting Permit'):'Ready');w.crew=w.crew||w.Assigned_Crew||w.Crew_ID||'';w.erp=w.erp||w.ERP_Sync_Status||(mode==='synthetic'?(i%7?'Synced':'Pending'):'Synced');w.slaResult=w.slaResult||w.SLA_Result||'';w.slaDue=w.slaDue||w.SLA_Due||'';w.energyAtRisk=Number(w.energyAtRisk??w.Energy_At_Risk_MWh??w.Generation_Loss_MWh??w.loss??0)||0;w.overdue=w.overdue??(mode==='excel'?/breached/i.test(String(w.slaResult)):i%8===0);w.slaRisk=w.slaRisk??(mode==='excel'?(/breached|open/i.test(String(w.slaResult))):w.priority==='Critical'||i%7===0);w.loss=Math.round(Number(w.loss??w.Generation_Loss_MWh??w.Energy_At_Risk_MWh??(mode==='synthetic'?5+i*2.3:0))||0);w.cost=Math.round(Number(w.cost??w.Estimated_Cost??w.Estimated_Cost_INR??(mode==='synthetic'?18000+i*1700:0))||0);w.primaryConstraint=opsPrimaryConstraint(w);w.Primary_Work_Order_Constraint=w.primaryConstraint;return w})}
function opsKpis(items){
  const nums=items.map(x=>Math.max(0,Number(x[1])||0)),max=Math.max(0,...nums);
  return `<div class="ops-kpis">${items.map((x,i)=>{const pct=x[4]!=null?Math.max(0,Math.min(100,Number(x[4])||0)):(max?Math.round(nums[i]/max*100):0),note=x[5]||(max?'Relative to the highest Work Order KPI':'No comparable numeric value available');return `<div class="card enhanced-kpi ops-kpi aip-ring-enabled aip-kpi-container" style="--kc:${x[3]};--qa-accent:${x[3]};--kpi-accent:${x[3]};--kpi-accent-2:${x[3]}"><div class="aip-universal-kpi-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="kpi-label lbl">${x[0]}</div><div class="kpi-value val">${x[1]}<span class="kpi-unit unit">${x[2]}</span></div><div class="kpi-delta flat ctx">${i%2?'Current operational state':'Calculated from active dataset'}</div><div class="aip-kpi-ring-wrap"><div class="aip-kpi-ring" style="--aip-ring:${pct};--aip-ring-accent:${x[3]}"><span class="aip-kpi-ring-value ${pct>=100?'triple-digit':''}">${Math.round(pct)}%</span></div><div class="aip-kpi-ring-note"><b>${Math.round(pct)}%:</b> ${note}</div></div></div>`}).join('')}</div>`;
}
function opsWOTab(t){window.AIP_WO_DESIRED_TAB=t;OPS_WO.tab=t;renderWorkOrderIntelligence()}
function opsCrewTab(t){OPS_CREW.tab=t;renderCrewScheduling()}
function opsPriority(p){return p==='Critical'?'critical':p==='High'?'high':p==='Low'?'good':'info'}
function opsWOCommand(rows){
 const closedStatuses=new Set(['Closed','Completed','ERP Closed','Cancelled']);
 const openRows=rows.filter(w=>!closedStatuses.has(String(w.status||'').trim()));
 const critical=openRows.filter(w=>w.priority==='Critical').slice(0,6);
 const preferredOrder=['Recommended','Draft','Awaiting Approval','Approved','Ready to Schedule','Scheduled','Dispatched','In Progress','Verified'];
 const statusCounts={};
 openRows.forEach(w=>{const st=String(w.status||'Unspecified').trim()||'Unspecified';statusCounts[st]=(statusCounts[st]||0)+1});
 const statuses=Object.keys(statusCounts).sort((a,b)=>{
   const ai=preferredOrder.indexOf(a),bi=preferredOrder.indexOf(b);
   return (ai<0?999:ai)-(bi<0?999:bi)||a.localeCompare(b);
 });
 const palette=['#1976d2','#7b1fa2','#00838f','#ef8f00','#d32f2f','#198754','#5d6d7e','#c2185b','#6a8e2f'];
 let cursor=0;
 const gradientParts=statuses.map((st,i)=>{const start=cursor;cursor+=openRows.length?(statusCounts[st]/openRows.length*100):0;return `${palette[i%palette.length]} ${start.toFixed(2)}% ${cursor.toFixed(2)}%`});
 const donutBg=gradientParts.length?`conic-gradient(${gradientParts.join(',')})`:'#e4edf1';
 const statusLegend=statuses.map((st,i)=>`<div class="ops-exception"><span class="dot" style="background:${palette[i%palette.length]}"></span><div><b>${opsEsc(st)}</b></div><b>${statusCounts[st]}</b></div>`).join('')||'<div class="ops-exception good"><span class="dot"></span><div><b>No open work orders</b></div><b>0</b></div>';
 return `<div class="ops-workspace"><div class="ops-panel"><h3>Action Required</h3><div class="ops-muted">AI-prioritized work requiring a decision today</div>${critical.map(w=>`<div class="ops-exception"><span class="dot"></span><div><b>${opsEsc(w.id)} · ${opsEsc(w.asset)}</b><div class="ops-muted">${opsEsc(w.plant)} · ${opsEsc(w.desc)} · ${w.loss} MWh exposure</div></div><button class="ops-action primary" onclick="opsOpenWO('${w.id}')">Review</button></div>`).join('')||'<div class="ops-exception good"><span class="dot"></span><div><b>No critical action pending</b></div></div>'}</div><div class="ops-panel"><h3>Work Order Status Mix</h3><div class="ops-muted"></div><div class="ops-donut" style="background:${donutBg}" data-label="${openRows.length} Active"></div>${statusLegend}<div class="ops-muted" style="text-align:center;margin-top:8px">Legend total: ${openRows.length} open work orders</div></div></div>`
}
function opsWOLedger(rows){return `<div class="ops-panel"><div class="ops-toolbar"><input placeholder="Search WO, asset or site" value="${opsEsc(OPS_WO.search)}" oninput="OPS_WO.search=this.value;renderWorkOrderIntelligence()"><select onchange="OPS_WO.filter=this.value;renderWorkOrderIntelligence()"><option>All</option>${['Draft','Awaiting Approval','Approved','Ready to Schedule','Scheduled','In Progress','Completed','Closed'].map(x=>`<option ${OPS_WO.filter===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn primary" onclick="opsCreateWO()">Create Work Order</button></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>WO ID</th><th>Site / Asset</th><th>Type</th><th>Priority</th><th>Status</th><th>Crew</th><th>Parts</th><th>Permit</th><th>Loss</th><th>Cost</th><th>ERP</th><th>Action</th></tr></thead><tbody>${rows.map(w=>`<tr><td class="ops-link" onclick="opsOpenWO('${w.id}')">${opsEsc(w.id)}</td><td>${opsEsc(w.plant)}<br><b>${opsEsc(w.asset)}</b></td><td>${opsEsc(w.type)}</td><td><span class="ops-status ${opsPriority(w.priority)}">${w.priority}</span></td><td><span class="ops-status info">${w.status}</span></td><td>${opsEsc(w.crew||'Unassigned')}</td><td>${opsEsc(w.parts)}</td><td>${opsEsc(w.permit)}</td><td>${w.loss} MWh</td><td>₹${w.cost.toLocaleString('en-IN')}</td><td>${opsEsc(w.erp)}</td><td><button class="ops-action primary" onclick="opsOpenWO('${w.id}')">Update</button></td></tr>`).join('')}</tbody></table></div></div>`}
function opsWOLifecycle(rows){
 const steps=['Recommended','Draft','Awaiting Approval','Approved','Ready to Schedule','Scheduled','Dispatched','In Progress','Completed','Verified','ERP Closed'];
 const closed=new Set(['Closed','Completed','ERP Closed','Cancelled']);
 const w=rows.find(x=>x.id===opsSelectedWorkOrderId())||rows.find(x=>!closed.has(String(x.status||'').trim()))||rows[0];
 const idx=Math.max(0,steps.indexOf(w?.status));
 const counts={};rows.forEach(x=>{const st=String(x.status||'Unspecified').trim()||'Unspecified';counts[st]=(counts[st]||0)+1});
 const active=rows.filter(x=>!closed.has(String(x.status||'').trim())).length, completed=rows.length-active;
 const maxCount=Math.max(1,...Object.values(counts));
 const statusCards=steps.filter(st=>counts[st]).map((st,i)=>`<div class="ops-life-status"><div class="ops-life-status-head"><span>${opsEsc(st)}</span><b>${counts[st]}</b></div><div class="ops-life-track"><i style="width:${Math.max(8,Math.round(counts[st]/maxCount*100))}%"></i></div></div>`).join('')||'<div class="ops-exception good"><span class="dot"></span><div><b>No lifecycle records available</b></div></div>';
 const readiness=[
  ['Parts',w?.parts||'—',/ready/i.test(String(w?.parts||''))?'good':'warn'],
  ['Permit / Access',w?.permit||'—',/ready|approved/i.test(String(w?.permit||''))?'good':'warn'],
  ['Crew',w?.crew||'Unassigned',w?.crew?'good':'warn'],
  ['SLA',w?.overdue?'Breached':w?.slaRisk?'At risk':'Within SLA',w?.overdue?'bad':w?.slaRisk?'warn':'good'],
  ['ERP / EAM',w?.erp||'—',/synced|acknowledged/i.test(String(w?.erp||''))?'good':/failed|reject/i.test(String(w?.erp||''))?'bad':'info']
 ];
 return `<div class="ops-life-grid"><div class="ops-panel"><div class="ops-life-title"><div><h3>Lifecycle & Status</h3><div class="ops-muted">Selected work order: ${opsEsc(w?.id||'—')} · ${opsEsc(w?.asset||'—')} · ${opsEsc(w?.plant||'—')}</div></div><div class="ops-life-totals"><span><b>${active}</b> Active</span><span><b>${completed}</b> Completed / closed</span></div></div><div class="ops-stepper">${steps.map((x,i)=>`<div class="ops-step ${i<idx?'done':i===idx?'current':''}"><i>${i+1}</i><b>${x}</b></div>`).join('')}</div><div class="ops-life-readiness">${readiness.map(r=>`<div class="ops-life-read ${r[2]}"><span>${r[0]}</span><b>${opsEsc(String(r[1]))}</b></div>`).join('')}</div><div class="ops-toolbar" style="margin-top:12px"><button class="btn primary" onclick="opsAdvanceWO('${w?.id}')">Advance to Next Status</button><button class="btn" onclick="opsOpenWO('${w?.id}')">Open Details</button></div></div><div class="ops-panel"><h3>Portfolio Lifecycle Distribution</h3><div class="ops-muted">Current work-order population by lifecycle stage</div><div class="ops-life-dist">${statusCards}</div></div></div>`
}
const OPS_CONSTRAINT_PRIORITY_DEFAULT={priorityWeight:45,slaWeight:30,impactWeight:25,redThreshold:70,priorityScores:{Critical:100,High:75,Medium:50,Low:25},slaScores:{breached:100,atRisk:70,normal:20},impactBands:{highThreshold:50,highScore:100,mediumThreshold:25,mediumScore:75,lowThreshold:10,lowScore:50,minThreshold:0,minScore:25,zeroScore:0}};
function opsConstraintPriorityMerge(raw){raw=raw||{};return {...OPS_CONSTRAINT_PRIORITY_DEFAULT,...raw,priorityScores:{...OPS_CONSTRAINT_PRIORITY_DEFAULT.priorityScores,...(raw.priorityScores||{})},slaScores:{...OPS_CONSTRAINT_PRIORITY_DEFAULT.slaScores,...(raw.slaScores||{})},impactBands:{...OPS_CONSTRAINT_PRIORITY_DEFAULT.impactBands,...(raw.impactBands||{})}}}
window.OPS_CONSTRAINT_PRIORITY=window.OPS_CONSTRAINT_PRIORITY||(()=>{try{return opsConstraintPriorityMerge(JSON.parse(localStorage.getItem('aipConstraintPrioritization')||'{}'))}catch(e){return opsConstraintPriorityMerge({})}})();
function opsConstraintPriorityConfig(){return opsConstraintPriorityMerge(window.OPS_CONSTRAINT_PRIORITY)}
function opsConstraintPriorityScore(w){const c=opsConstraintPriorityConfig(),p=c.priorityScores[String(w.priority||w.Priority||'Medium')]??c.priorityScores.Medium,sr=String(w.slaResult||w.SLA_Result||'').toLowerCase(),sla=/breached/.test(sr)||w.overdue?c.slaScores.breached:(w.slaRisk||/open/.test(sr)?c.slaScores.atRisk:c.slaScores.normal),m=Number(w.energyAtRisk??w.Energy_At_Risk_MWh??w.loss??w.Generation_Loss_MWh??0)||0,b=c.impactBands,impact=m>=b.highThreshold?b.highScore:m>=b.mediumThreshold?b.mediumScore:m>=b.lowThreshold?b.lowScore:m>b.minThreshold?b.minScore:b.zeroScore,total=Math.round((p*c.priorityWeight+sla*c.slaWeight+impact*c.impactWeight)/Math.max(1,c.priorityWeight+c.slaWeight+c.impactWeight));return{score:total,band:total>=c.redThreshold?'Red':'Amber',priority:p,sla,impact,impactMWh:m}}
function opsConstraintPrioritySave(){const g=id=>Number(document.getElementById(id)?.value||0),n={priorityWeight:g('opsCpPriorityWeight'),slaWeight:g('opsCpSlaWeight'),impactWeight:g('opsCpImpactWeight'),redThreshold:g('opsCpRedThreshold'),priorityScores:{Critical:g('opsCpPriCritical'),High:g('opsCpPriHigh'),Medium:g('opsCpPriMedium'),Low:g('opsCpPriLow')},slaScores:{breached:g('opsCpSlaBreached'),atRisk:g('opsCpSlaAtRisk'),normal:g('opsCpSlaNormal')},impactBands:{highThreshold:g('opsCpImpactHighT'),highScore:g('opsCpImpactHighS'),mediumThreshold:g('opsCpImpactMedT'),mediumScore:g('opsCpImpactMedS'),lowThreshold:g('opsCpImpactLowT'),lowScore:g('opsCpImpactLowS'),minThreshold:g('opsCpImpactMinT'),minScore:g('opsCpImpactMinS'),zeroScore:g('opsCpImpactZeroS')}};if(n.priorityWeight+n.slaWeight+n.impactWeight!==100){toast?.('Constraint Prioritization weights must total 100%');return}if(n.redThreshold<1||n.redThreshold>100){toast?.('Red threshold must be between 1 and 100');return}const scores=[...Object.values(n.priorityScores),...Object.values(n.slaScores),n.impactBands.highScore,n.impactBands.mediumScore,n.impactBands.lowScore,n.impactBands.minScore,n.impactBands.zeroScore];if(scores.some(x=>x<0||x>100)){toast?.('All component scores must be between 0 and 100');return}const b=n.impactBands;if(!(b.highThreshold>b.mediumThreshold&&b.mediumThreshold>b.lowThreshold&&b.lowThreshold>=b.minThreshold&&b.minThreshold>=0)){toast?.('Operational impact thresholds must descend from High to Minimum');return}window.OPS_CONSTRAINT_PRIORITY=opsConstraintPriorityMerge(n);try{localStorage.setItem('aipConstraintPrioritization',JSON.stringify(window.OPS_CONSTRAINT_PRIORITY))}catch(e){}window.OPS_CP_VIEW_OPEN=true;renderWorkOrderIntelligence();toast?.('Constraint Prioritization configuration saved')}
function opsConstraintPriorityReset(){window.OPS_CONSTRAINT_PRIORITY=opsConstraintPriorityMerge({});try{localStorage.removeItem('aipConstraintPrioritization')}catch(e){}window.OPS_CP_VIEW_OPEN=true;renderWorkOrderIntelligence();toast?.('Constraint Prioritization reset to default')}
window.OPS_CP_VIEW_OPEN=window.OPS_CP_VIEW_OPEN||false;
