window.AIP_RCM_V650=__AIP_DS("43c8cbf4c85086cb");
function rcm650Rows(name){
  try{
    const imported=(window.APM_IMPORTED_DATA||{})[name];
    if(Array.isArray(imported)&&imported.length)return imported;
  }catch(_){}
  const governed=window.AIP_RCM_V650?.[name];
  if(Array.isArray(governed)&&governed.length)return governed;
  try{
    if(typeof currentDataSource==='function'&&currentDataSource()==='synthetic'){
      const rows=AIP_INDEPENDENT_SYNTHETIC_DATA?.platformSyntheticData?.[name];if(Array.isArray(rows))return aipVision666NormalizeReplayFrames(rows);
    }
  }catch(_){}
  const ex=(typeof EMBEDDED_EXCEL_DATA!=='undefined'&&EMBEDDED_EXCEL_DATA?.[name])||[];
  return Array.isArray(ex)?ex:[];
}
window.RCM650_SELECTED=window.RCM650_SELECTED||'';
function rcm650Esc(v){return String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function rcm654Gate(v){v=String(v||'').trim().toLowerCase();return v==='yes'?'yes':v==='no'?'no':'na'}
function rcm654Sources(id){return [...new Set(rcm650Rows('RCM Source Linkage').filter(r=>String(r.RCM_ID)===String(id)).map(r=>r.Authoritative_Module).filter(Boolean))]}
function rcm654SelectOffset(delta){
 const a=rcm650Rows('RCM Strategy');if(!a.length)return;
 let i=a.findIndex(r=>String(r.RCM_ID)===String(window.RCM650_SELECTED));if(i<0)i=0;
 i=(i+delta+a.length)%a.length;window.RCM650_SELECTED=String(a[i].RCM_ID);renderRCM();
}
