 const idx=strategy.findIndex(r=>String(r.RCM_ID)===id)+1,hiddenCount=logic.filter(r=>String(r.Hidden_Or_Protective_Function)==='Yes').length;
 const primary=l.Primary_RCM_Policy||l.Selected_Failure_Management_Policy||s.Maintenance_Strategy,sources=rcm654Sources(id);
