window.AIP_V331_SYNC_MODEL_SCROLL=function(){
  /* v333: matrix is width-fitted; synchronized horizontal scrolling is intentionally retired. */
};
window.AIP_V328_MODEL_NAV=function(view,id){
  window.AIP_MODEL_RETURN={view:"models",model:id};
  try{
    if(typeof window.activate==="function") window.activate(view);
    else document.querySelector(`#sidebar .nav-item[data-view="${view}"]`)?.click();

    /* v334: deep-link only to current user-facing architecture, never legacy standalone renderers. */
    if(id==="AIP-CRW-013"){
      setTimeout(()=>{
        try{window.planSetTab?.("resources")}catch(_){}
        setTimeout(()=>{
          const root=document.getElementById("view-resourceplanning");
          const h=[...(root?.querySelectorAll("h3")||[])].find(x=>/Crew\s*&\s*Skills/i.test(x.textContent||""));
          h?.closest(".po-card")?.scrollIntoView({block:"center",behavior:"smooth"});
        },80);
      },40);
      return;
    }
    if(id==="AIP-ATT-014"){
      setTimeout(()=>{
        try{window.planSetTab?.("overview")}catch(_){}
        setTimeout(()=>document.querySelector('#view-resourceplanning .po-attention-register')?.scrollIntoView({block:"center",behavior:"smooth"}),100);
      },50);
      return;
    }
    if(id==="AIP-CLI-015" || id==="EXT-WX-021" || id==="EXT-GEO-022"){
      setTimeout(()=>document.querySelector('#view-sustainabilityintelligence [data-sus8-tab="climate"]')?.click(),120);
      return;
    }
    if(id==="AIP-EOL-020"){
      setTimeout(()=>document.querySelector('#view-sustainabilityintelligence [data-sus8-tab="eol"]')?.click(),120);
      return;
    }
    if(id==="AIP-WAR-016" || id==="EXT-OEM-023"){
      setTimeout(()=>document.querySelector('#view-maintenancelearning [data-tab="oem"]')?.click(),120);
      return;
    }
    if(id==="EXT-LLM-019") return;

    const custom=window.AIP_V21&&window.AIP_V21.renderers&&window.AIP_V21.renderers[view];
    if(typeof custom==="function"){ custom(); return; }
    const target=document.getElementById("view-"+view);
    if(target && target.innerHTML.trim()) return;
    const n=document.querySelector(`#sidebar .nav-item[data-view="${view}"]`);
    if(n){n.click();return}
    if(typeof window.AIP_V21?.open==="function") window.AIP_V21.open(view);
  }catch(e){console.error("Model tile navigation failed",view,e)}
};
/* =============================== INTEGRATIONS =============================== */
function fmtLatency(ms){ return ms>=1000 ? (ms/1000).toFixed(1)+" s" : Math.round(ms)+" ms"; }
function fmtSyncAgo(sec){
  if(sec<10) return "just now";
  if(sec<60) return Math.round(sec)+" sec ago";
  if(sec<3600) return Math.round(sec/60)+" min ago";
  if(sec<86400) return Math.round(sec/3600)+" hr ago";
  return Math.round(sec/86400)+" day ago";
}
function fmtThroughput(i){
  if(i.throughputVal==null) return "—";
  const v = i.throughputVal>=1000 ? i.throughputVal.toLocaleString("en-IN",{maximumFractionDigits:0}) : round1(i.throughputVal);
  return v + " " + i.throughputUnit;
}


