function esgSum(field){return ESG_MONTHLY.reduce((a,r)=>a+(Number(r[field])||0),0)}
function renderESGOverview(){if(typeof window.renderSustainabilityIntelligence==="function")return window.renderSustainabilityIntelligence();const generation=esgSum("generation"),net=esgSum("netCarbon"),water=esgSum("water"),waste=esgSum("waste"),diverted=esgSum("diverted"),lti=esgSum("lti"),overdue=ESG_COMPLIANCE.filter(x=>x.status==="Action Required").length,highSup=ESG_SUPPLIERS.filter(x=>x.risk==="High").length;const plantRows=PLANTS.map(p=>{const rows=ESG_MONTHLY.filter(x=>x.plant===p.id),gen=rows.reduce((a,x)=>a+x.generation,0),carbon=rows.reduce((a,x)=>a+x.netCarbon,0),wi=rows.reduce((a,x)=>a+x.water,0)/(gen||1),div=rows.reduce((a,x)=>a+x.diverted,0)/(rows.reduce((a,x)=>a+x.waste,0)||1),risk=ESG_CLIMATE.find(x=>x.plant===p.id)?.score||0;return{p,gen,carbon,wi,div,risk}}).sort((a,b)=>b.risk-a.risk);document.getElementById("view-esgoverview").innerHTML=`<div class="view-head aip-esg-view-head"><div><div class="eyebrow" style="color:var(--teal)">OPERATIONAL ESG INTELLIGENCE</div><h1>ESG Executive Overview</h1></div></div><div class="grid g6 aip-esg-executive-kpis" style="margin-bottom:16px"><div class="card" data-kpi-card><div class="kpi-label">Renewable generation</div><div class="kpi-value">${Math.round(generation/1000).toLocaleString()}<span class="kpi-unit">GWh</span></div></div><div class="card" data-kpi-card><div class="kpi-label">Carbon emissions avoided</div><div class="kpi-value">${Math.round(esgSum("avoided")).toLocaleString()}<span class="kpi-unit">tCO₂e</span></div><div class="kpi-delta up">Higher is better</div></div><div class="card" data-kpi-card><div class="kpi-label">Water consumption intensity</div><div class="kpi-value">${round2((water/generation)*1000)}<span class="kpi-unit">L/MWh</span></div><div class="kpi-delta down">Lower is better</div></div><div class="card" data-kpi-card><div class="kpi-label">Waste diversion</div><div class="kpi-value">${Math.round(diverted/waste*100)}<span class="kpi-unit">%</span></div></div><div class="card" data-kpi-card><div class="kpi-label">Lost-time injuries</div><div class="kpi-value">${lti}</div></div><div class="card" data-kpi-card><div class="kpi-label">ESG exceptions</div><div class="kpi-value">${overdue+highSup}</div><div class="kpi-delta down">${overdue} compliance · ${highSup} suppliers</div></div></div><div class="grid g2" style="margin-bottom:16px"><div class="card"><div class="panel-title"><div><h3>Monthly Carbon Emissions Avoided</h3><div class="sub">Tonnes of CO₂-equivalent avoided through renewable electricity generation · higher is better</div></div></div><div class="chart-wrap h260"><canvas id="chartESGCarbon"></canvas></div></div><div class="card"><div class="panel-title"><div><h3>Water Consumption Intensity</h3><div class="sub">Litres of water used for module cleaning and plant operations per MWh generated · lower is better</div></div></div><div class="chart-wrap h260"><canvas id="chartESGIntensity"></canvas></div></div></div><div class="card"><div class="panel-title"><div><h3>Plant ESG exception ranking</h3><div class="sub">Climate exposure combined with operational environmental indicators</div></div></div><table><thead><tr><th>Plant</th><th>Generation</th><th>Net carbon benefit</th><th>Water intensity</th><th>Waste diversion</th><th>Climate risk</th></tr></thead><tbody>${plantRows.map(x=>`<tr><td><b>${x.p.id}</b> · ${x.p.name}</td><td>${Math.round(x.gen).toLocaleString()} MWh</td><td>${Math.round(x.carbon).toLocaleString()} tCO₂e</td><td>${round2(x.wi)} kL/MWh</td><td>${Math.round(x.div*100)}%</td><td><span class="tag ${x.risk>.7?"corrective":x.risk>.5?"adaptive":"predictive"}">${Math.round(x.risk*100)}</span></td></tr>`).join("")}</tbody></table></div>${ESG_TARGETS.length?`<div class="card aip-esg-target-panel" style="margin-top:16px"><div class="panel-title"><div><h3>ESG Targets — FY2026</h3><div class="sub">Target values only · actual portfolio performance is shown in the executive KPIs above</div></div></div><div class="aip-esg-target-list">${ESG_TARGETS.map(t=>{
      const metric=String(t.metric||"").trim(), unit=String(t.unit||"").trim(), raw=Number(t.target)||0;
      const targetText=unit==="%"?`${round2(raw)}%`:unit==="Count"?`${Math.round(raw)}`:unit==="MWh"?`${round2(raw/1000).toLocaleString()} GWh`:unit==="GWh"?`${round2(raw).toLocaleString()} GWh`:unit==="tCO2e"?`${Math.round(raw).toLocaleString()} tCO₂e`:unit==="kL/MWh"?`${round4(raw)} kL/MWh`:`${round2(raw)}${unit?` ${unit}`:""}`;
      return `<div class="aip-esg-target-row"><span class="aip-esg-target-metric">${metric}</span><strong class="aip-esg-target-value">${targetText}</strong><span class="aip-esg-target-direction ${t.direction==="Lower"?"lower":"higher"}">${t.direction==="Lower"?"Lower is better":"Higher is better"}</span></div>`;
    }).join("")}</div></div>`:""}`;
  /* First-navigation fix: normalize both ESG KPI groups immediately. */
  const esgView=document.getElementById("view-esgoverview");
  if(window.AIPKPIMaster?.scan) window.AIPKPIMaster.scan(esgView);
  requestAnimationFrame(()=>window.AIPKPIMaster?.scan?.(esgView));

  /* The first drill-down can occur before the right pane finishes its final width/layout pass.
     Re-measure and redraw the ESG canvases after activation/layout settles. */
  const settleESGCharts=()=>{
    if(!esgView?.classList.contains("active"))return;
    try{
      if(!(CH.esgoverview||[]).length) initESGOverviewCharts();
      resizeView("esgoverview",true);
    }catch(e){console.error("ESG first-load chart settle failed",e)}
  };
  requestAnimationFrame(()=>requestAnimationFrame(settleESGCharts));
  setTimeout(settleESGCharts,80);
  setTimeout(settleESGCharts,220);
}

