function initCircularityCharts(){const cats=[...new Set(ESG_WASTE.map(x=>x.category))],catVals=cats.map(c=>round1(ESG_WASTE.filter(x=>x.category===c).reduce((a,x)=>a+x.qty,0)));reg("circularity",()=>chBarV("chartWasteCat",{labels:cats,series:[{label:"Generated",data:catVals,color:"#C9821F"}],ySuffix:" t"}));const routes=[...new Set(ESG_WASTE.map(x=>x.route))],vals=routes.map(c=>round1(ESG_WASTE.filter(x=>x.route===c).reduce((a,x)=>a+x.qty,0)));reg("circularity",()=>chBarH("chartWasteRoute",{labels:routes,data:vals,colors:routes.map(x=>x==="Authorized disposal"?"#B84A2E":"#1E8E5A"),xSuffix:" t"}))}
function initHSEClimateCharts(){const sorted=ESG_CLIMATE.slice().sort((a,b)=>b.score-a.score);reg("hseclimate",()=>chBarH("chartClimateRisk",{labels:sorted.map(x=>x.plant),data:sorted.map(x=>Math.round(x.score*100)),colors:sorted.map(x=>x.score>.7?"#C0392B":x.score>.5?"#C9821F":"#1E8E5A"),showValues:true,xSuffix:"/100"}));const hazardOrder=["Electrical","Working at Height","Vehicle Movement","Heat Stress","Manual Handling","Fire & Emergency"],cats=hazardOrder.filter(c=>ESG_HSE.some(x=>x.risk===c)),vals=cats.map(c=>ESG_HSE.filter(x=>x.risk===c).length);reg("hseclimate",()=>chBarH("chartHSECat",{labels:cats,data:vals,colors:cats.map(()=>"#8B3A3A"),showValues:true,xSuffix:""}));reg("hseclimate",()=>{if(!ASSET_REGISTRY.length)return;const car=ESG_CLIMATE.slice().map(c=>{const assets=ASSET_REGISTRY.filter(a=>a.plant===c.plant);const highRiskPct=assets.length?Math.round(assets.filter(a=>a.riskBand==="High").length/assets.length*100):0;return{plant:c.plantName,combined:Math.round(c.score*100*0.6+highRiskPct*0.4)};}).sort((a,b)=>b.combined-a.combined);chBarH("chartClimateAssetRisk",{labels:car.map(x=>x.plant),data:car.map(x=>x.combined),colors:car.map(x=>x.combined>60?"#C0392B":x.combined>40?"#C9821F":"#1E8E5A"),showValues:true,xSuffix:"/100"});})}

