/* -------------------- CORRECTIVE -------------------- */
function chBarHCorrectiveFaults(canvasId,{labels,data,colors}){
  const canvas=document.getElementById(canvasId); if(!canvas)return;
  const {ctx,w,h}=chMeasure(canvas);
  const padL=Math.min(Math.max(138,Math.floor(w*.38)),210),padR=34,padT=8,padB=30;
  const x0=padL,x1=w-padR,y0=padT,y1=h-padB;
  const maxRaw=Math.max(...data)||1,XMAX=chNiceMax(maxRaw*1.15);
  const xScale=v=>x0+(v/XMAX)*(x1-x0);
  ctx.strokeStyle=GRID;ctx.fillStyle=INK_SOFT;ctx.font="9.5px Arial, sans-serif";ctx.textAlign="center";ctx.textBaseline="alphabetic";
  for(let i=0;i<=4;i++){const v=XMAX*i/4,x=xScale(v);ctx.beginPath();ctx.moveTo(x,y0);ctx.lineTo(x,y1);ctx.stroke();ctx.fillText(chAxisNum(v,XMAX),x,y1+12)}
  const n=labels.length,rowH=(y1-y0)/n,barH=Math.min(20,rowH*.58);
  labels.forEach((lab,i)=>{
    const cy=y0+i*rowH+rowH/2,v=data[i],bx=xScale(v);
    ctx.fillStyle=Array.isArray(colors)?colors[i]:colors;chRoundRect(ctx,x0,cy-barH/2,Math.max(2,bx-x0),barH,3);ctx.fill();
    ctx.fillStyle=INK_SOFT;ctx.font="9px Arial, sans-serif";ctx.textAlign="right";ctx.textBaseline="middle";
    const words=String(lab).split(/\s+/),lines=[];let line='';
    words.forEach(word=>{
      const test=(line?line+' ':'')+word;
      if(ctx.measureText(test).width>padL-16&&line){lines.push(line);line=word}else line=test;
    }); if(line)lines.push(line);
    const use=lines.slice(0,2),lh=10;
    use.forEach((ln,j)=>ctx.fillText(ln,x0-7,cy+(j-(use.length-1)/2)*lh));
    ctx.fillStyle=INK;ctx.font="9.5px Arial, sans-serif";ctx.textAlign="left";
    const val=String(v),vw=ctx.measureText(val).width;
    if(bx+6+vw<x1+padR-2)ctx.fillText(val,bx+6,cy);else{ctx.fillStyle="#fff";ctx.textAlign="right";ctx.fillText(val,bx-5,cy)}
  });
  ctx.strokeStyle="#D7DEE2";ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x0,y1);ctx.stroke();
}
