/* -------------------- PREVENTIVE -------------------- */
function initPreventiveCharts(){
  // The registry is cleared on dataset refresh. Re-register only when needed.
  if((CH.preventive||[]).length>=2) return;

  CH.preventive=[];

  reg("preventive", ()=>{
    const canonical=pmComplianceCanonical();
    const siteCompliance = canonical.sites
      .filter(s=>s.due>0 && s.rate!=null)
      .sort((a,b)=>a.rate-b.rate || String(a.id).localeCompare(String(b.id)));

    if(!siteCompliance.length){
      const c=document.getElementById("chartPMCompliance");
      const ctx=c?.getContext?.("2d");
      if(ctx){
        const dpr=window.devicePixelRatio||1, rect=c.getBoundingClientRect();
        c.width=Math.max(1,Math.round(rect.width*dpr)); c.height=Math.max(1,Math.round(rect.height*dpr));
        ctx.setTransform(dpr,0,0,dpr,0,0); ctx.clearRect(0,0,rect.width,rect.height);
        ctx.fillStyle="#7b1f35"; ctx.font="600 12px Arial, sans-serif"; ctx.textAlign="center";
        const msg=canonical.overall.due>0
          ? "PM site mapping unavailable — portfolio evidence exists"
          : "Insufficient PM due/completion evidence for site compliance";
        ctx.fillText(msg,rect.width/2,rect.height/2);
      }
      return;
    }
    chBarH("chartPMCompliance", {
      labels: siteCompliance.map(s=>`${s.id} — ${s.name}`), data: siteCompliance.map(s=>s.rate),
      colors: siteCompliance.map(s=>s.rate<70?"#C0392B":s.rate<85?"#C9821F":"#1E8E5A"),
      xSuffix:"%", showValues:true, refLine:85, refLabel:"Target (85%)",
      refLabelYOffset:2, refLabelFont:8,
      leftLabelWidth:220, labelFont:9
    });
  });

  const bands = [30,60,90,180,270,365];
  reg("preventive", ()=> {
    const counts = bands.map(b=> PREVENTIVE_WOS.filter(w=>Number(w.frequencyDays)===b).length);
    chBarV("chartPMFrequency", {
      labels: bands.map(b=>aipFrequencyLabel(b)),
      series:[{ data: counts, color:"#5B7083" }],
      legend:false,
      labelFont:9
    });
  });
}

let __preventiveInitialPaintGeneration=0;
let __preventiveInitialPaintTimer=0;

function drawPreventiveChartsStable(){
  const root=document.getElementById("view-preventive");
  if(!root?.classList.contains("active")) return false;

  const compliance=document.getElementById("chartPMCompliance");
  const frequency=document.getElementById("chartPMFrequency");
  if(!compliance || !frequency) return false;

  const ready=[compliance,frequency].every(c=>{
    const p=c.parentElement;
    const r=p?.getBoundingClientRect?.();
    return !!(r && r.width>=180 && r.height>=160);
  });
  if(!ready) return false;

  try{
    if((CH.preventive||[]).length<2) initPreventiveCharts();

    // Always paint against the final, visible canvases. This is essential on
    // first login because later Maintenance Strategy setup can recreate them.
    delete CH_LAYOUT_SIG.preventive;
    (CH.preventive||[]).forEach(fn=>fn());
    CH_LAYOUT_SIG.preventive=chartLayoutSignature("preventive");
    try{ chartsBooted.preventive=true; }catch(_){}
    return true;
  }catch(e){
    console.error("Preventive stable first paint failed",e);
    return false;
  }
}

function schedulePreventiveInitialPaint(){
  const generation=++__preventiveInitialPaintGeneration;
  clearTimeout(__preventiveInitialPaintTimer);
  let attempts=0;

  const run=()=>{
    if(generation!==__preventiveInitialPaintGeneration) return;
    requestAnimationFrame(()=>requestAnimationFrame(()=>{
      if(generation!==__preventiveInitialPaintGeneration) return;
      if(drawPreventiveChartsStable()) return;

      if(attempts++<36){
        __preventiveInitialPaintTimer=setTimeout(run,70);
      }
    }));
  };
  run();
}

