/* -------------------- PREDICTIVE -------------------- */
let TELEMETRY_LIVE_PLANT = null;
let TELEMETRY_LIVE_ROWS = [];
function telemetryTsToDate(value){
  if(value instanceof Date && !isNaN(value)) return value;
  if(typeof value === "number" && isFinite(value)){
    // Excel serial date/time (1900 date system)
    return new Date(Math.round((value - 25569) * 86400 * 1000));
  }
  const raw = String(value ?? "").trim();
  if(!raw) return null;
  // Time-only values such as 07:17 or 07:17:30
  if(/^\d{1,2}:\d{2}(?::\d{2})?$/.test(raw)){
    const parts = raw.split(":").map(Number);
    const d = new Date(2000,0,1,parts[0],parts[1],parts[2]||0);
    return d;
  }
  const parsed = new Date(raw);
  return isNaN(parsed) ? null : parsed;
}
function telemetrySortValue(value){
  const d = telemetryTsToDate(value);
  return d ? d.getTime() : String(value ?? "");
}
function formatTelemetryAxisLabel(value, rows){
  const d = telemetryTsToDate(value);
  if(!d) return String(value ?? "").replace(/^.*[T ](?=\d{1,2}:\d{2})/, "");
  const raw = String(value ?? "").trim();
  const hasDate = typeof value === "number" || /[-\/]/.test(raw) || /T/.test(raw);
  const spansDates = (rows || []).some(r=>{
    const rd=telemetryTsToDate(r.ts);
    return rd && (rd.getFullYear()!==d.getFullYear() || rd.getMonth()!==d.getMonth() || rd.getDate()!==d.getDate());
  });
  const hh=String(d.getHours()).padStart(2,"0");
  const mm=String(d.getMinutes()).padStart(2,"0");
  if(hasDate && spansDates){
    const dd=String(d.getDate()).padStart(2,"0");
    const mon=d.toLocaleString("en-US",{month:"short"});
    return `${dd} ${mon} ${hh}:${mm}`;
  }
  return `${hh}:${mm}`;
}
function renderTelemetryChart(plantId){
  const available=[...new Set(TELEMETRY_LOG.map(t=>t.plant).filter(Boolean))];
  const resolved=available.includes(plantId)?plantId:(available.includes(TELEMETRY_LIVE_PLANT)?TELEMETRY_LIVE_PLANT:available[0]);
  TELEMETRY_LIVE_PLANT = resolved || "";
  try{ if(TELEMETRY_LIVE_PLANT) localStorage.setItem("aip_telemetry_plant",TELEMETRY_LIVE_PLANT); }catch(e){}
  const select=document.getElementById("telemetryPlantSelect");
  if(select && TELEMETRY_LIVE_PLANT) select.value=TELEMETRY_LIVE_PLANT;
  const rows = TELEMETRY_LOG.filter(t=>t.plant===TELEMETRY_LIVE_PLANT).slice().sort((a,b)=>{
    const av=telemetrySortValue(a.ts), bv=telemetrySortValue(b.ts);
    return typeof av === "number" && typeof bv === "number" ? av-bv : String(av).localeCompare(String(bv));
  });
  TELEMETRY_LIVE_ROWS = rows.slice(-40);
  drawTelemetryChart();
}
window.renderTelemetryChart = renderTelemetryChart;
function drawTelemetryChart(){
  const rows = TELEMETRY_LIVE_ROWS;
  const statsEl = document.getElementById("telemetryStats");
  if(!rows.length){
    if(statsEl) statsEl.textContent = "No telemetry samples loaded for this plant.";
    return;
  }
  chLine("chartTelemetry", {
    labels: rows.map(r=> formatTelemetryAxisLabel(r.ts, rows)),
    series:[
      { label:"Efficiency (%)", data: rows.map(r=>r.efficiency), color:"#0E7C7B", points:true },
      { label:"Irradiance (% of STC)", data: rows.map(r=>round1(r.irradiance/10)), color:"#C9821F", dash:[4,3] }
    ]
  });
  const avgEff = round1(rows.reduce((a,r)=>a+r.efficiency,0)/rows.length);
  const degraded = rows.filter(r=>r.signal!=="OK").length;
  const liveDot = `<span style="display:inline-flex;align-items:center;gap:5px;color:var(--success);font-weight:700;"><span style="width:6px;height:6px;border-radius:50%;background:var(--success);display:inline-block;animation:pulse 1.6s infinite;"></span>LIVE</span>`;
  if(statsEl) statsEl.innerHTML = `${liveDot} · ${rows.length} samples for ${TELEMETRY_LIVE_PLANT} · avg efficiency <b>${avgEff}%</b> · ${degraded ? `<span style="color:var(--critical)">${degraded} degraded-signal reading(s)</span>` : "all signals nominal"}`;
}
function tickTelemetryLive(){
  if(!TELEMETRY_LIVE_ROWS.length) return;
  const last = TELEMETRY_LIVE_ROWS[TELEMETRY_LIVE_ROWS.length-1];
  const now = new Date();
  const ts = String(now.getHours()).padStart(2,"0")+":"+String(now.getMinutes()).padStart(2,"0")+":"+String(now.getSeconds()).padStart(2,"0");
  const nextIrr = Math.max(0, Math.min(1000, last.irradiance + rnd(-35,35)));
  const nextEff = Math.max(90, Math.min(100, last.efficiency + rnd(-0.35,0.35)));
  TELEMETRY_LIVE_ROWS.push({
    ts, plant: last.plant, asset: last.asset,
    irradiance: Math.round(nextIrr), acPower: round1(nextIrr*3.1),
    heatSinkTemp: round1(Math.max(30, last.heatSinkTemp + rnd(-1.5,1.5))),
    ambientTemp: last.ambientTemp,
    efficiency: round1(nextEff), signal: rng()<0.97 ? "OK" : "Degraded"
  });
  if(TELEMETRY_LIVE_ROWS.length>40) TELEMETRY_LIVE_ROWS.shift();
  drawTelemetryChart();
}
function startTelemetrySim(){
  setInterval(()=>{
    const visible = document.getElementById("view-predictive")?.classList.contains("active");
    if(visible && TELEMETRY_LIVE_ROWS.length) tickTelemetryLive();
  }, 3000);
}
let __predictiveChartTimer=0;
let __predictiveChartGeneration=0;
function drawPredictiveChartsStable(){
  const view=document.getElementById("view-predictive");
  if(!view?.classList.contains("active")) return false;
  const canvases=[...view.querySelectorAll("canvas")];
  if(!canvases.length) return false;

  if(!__predictiveChartsRegistered){
    try{initPredictiveCharts();chartsBooted.predictive=true}
    catch(e){console.error("Predictive chart bootstrap failed",e);return false}
  }

  const ready=canvases.every(c=>{
    const w=c.parentElement;
    return (w?.clientWidth||0)>=120 && (w?.clientHeight||0)>=120;
  });
  if(!ready)return false;

  // One complete redraw against the final DOM only.
  (CH.predictive||[]).forEach(fn=>{
    try{fn()}catch(e){console.error("Predictive chart redraw failed",e)}
  });
  CH_LAYOUT_SIG.predictive=chartLayoutSignature("predictive");
  return true;
}

const AIP_MAINT_STRATEGY_VIEWS=new Set(['preventive','conditionbased','predictive','corrective','riskbased','adaptive']);
function scheduleMaintenanceStrategyRedraw(view){
  if(!AIP_MAINT_STRATEGY_VIEWS.has(view))return;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    const root=document.getElementById('view-'+view);
    if(!root?.classList.contains('active'))return;
    try{
      if(view==='predictive') schedulePredictiveChartDraw();
      else if(view==='preventive') schedulePreventiveInitialPaint();
      else resizeView(view,true);
    }catch(e){console.error('Maintenance Strategy redraw failed',view,e)}
  }));

}
function schedulePredictiveChartDraw(){
  const generation=++__predictiveChartGeneration;
  clearTimeout(__predictiveChartTimer);
  __predictiveChartTimer=setTimeout(()=>{
    if(generation!==__predictiveChartGeneration)return;
    if(drawPredictiveChartsStable())return;
    // Only one bounded retry if the pane had not received dimensions yet.
    __predictiveChartTimer=setTimeout(()=>{
      if(generation===__predictiveChartGeneration)drawPredictiveChartsStable();
    },90);
  },70);
}
let __predictiveChartsRegistered=false;
function initPredictiveCharts(){
  if(__predictiveChartsRegistered)return;
  __predictiveChartsRegistered=true;
  reg("predictive", ()=>{
    const bucketOf = d => d<=15?0 : d<=30?1 : d<=60?2 : d<=90?3 : d<=150?4 : 5;
    const counts = [0,0,0,0,0,0];
    RISK_ASSETS.forEach(r=> counts[bucketOf(r.rulDays)]++);
    chBarV("chartRulHistogram", {
      labels: RUL_HISTOGRAM_BUCKETS,
      series:[{ data: counts, color: RUL_HISTOGRAM_BUCKETS.map((_,i)=> i<2?"#C0392B": i<4?"#C9821F":"#0E7C7B") }],
      legend:false
    });
  });

  const driftLabels = Array.from({length:12},(_,i)=>"D-"+((12-i)*2.5|0));
  const driftData = driftLabels.map((_,i)=> round1(96.5 - Math.max(0,(i-6))*0.9 + rnd(-0.6,0.6)));
  reg("predictive", ()=> chLine("chartDrift", {
    labels: driftLabels,
    series:[
      { label:"Model accuracy", data: driftData, color:"#0E7C7B", fill:true, points:true },
      { label:"Retrain threshold", data: driftLabels.map(()=>92), color:"#C0392B", dash:[5,4], width:1.4 }
    ],
    yMin:88, yMax:99, ySuffix:"%"
  }));

  reg("predictive", ()=>{
    const available=[...new Set(TELEMETRY_LOG.map(t=>t.plant).filter(Boolean))];
    let preferred=TELEMETRY_LIVE_PLANT;
    try{ preferred=localStorage.getItem("aip_telemetry_plant")||preferred; }catch(e){}
    renderTelemetryChart(available.includes(preferred)?preferred:available[0]);
  });

  reg("predictive", ()=>{
    if(!ASSET_REGISTRY.length) return;
    const byOem = {};
    ASSET_REGISTRY.forEach(a=>{
      if(!byOem[a.oem]) byOem[a.oem] = {count:0, healthSum:0, highRisk:0};
      byOem[a.oem].count++; byOem[a.oem].healthSum += a.healthScore;
      if(a.riskBand==="High") byOem[a.oem].highRisk++;
    });
    const oems = Object.keys(byOem).map(o=>({oem:o, avgHealth: Math.round(byOem[o].healthSum/byOem[o].count), count: byOem[o].count, highRisk: byOem[o].highRisk}))
      .sort((a,b)=>a.avgHealth-b.avgHealth);
    chBarH("chartOemReliability", {
      labels: oems.map(o=>`${o.oem} (${o.count})`), data: oems.map(o=>o.avgHealth),
      colors: oems.map(o=>o.avgHealth<70?"#C0392B":o.avgHealth<85?"#C9821F":"#1E8E5A"),
      showValues:true, xSuffix:"/100"
    });
  });
}

