const ALL_SCREEN_HELP_CATALOG={"overview":{"title":"Portfolio Overview","domain":"Portfolio","purpose":"Provides an executive view of fleet health, availability, performance ratio, maintenance exposure, revenue risk and proactive maintenance mix across the solar portfolio.","use":"Use it to identify underperforming sites, material risks and the areas requiring drill-down before reviewing detailed maintenance screens.","related":["Portfolio Overview","Site Performance","Loss Intelligence","Management Actions"]},"executiveperformance":{"title":"Executive Performance","domain":"Portfolio","purpose":"Connects operational performance with financial, reliability and sustainability outcomes for management review.","use":"Use it to compare actual performance against targets, understand value at risk and prioritise management intervention.","related":["Portfolio Overview","Site Performance","Loss Intelligence","Management Actions"]},"siteperformance":{"title":"Site Performance","domain":"Portfolio","purpose":"Examines plant-level performance, availability, yield, losses and operational exceptions for each solar site.","use":"Use filters to compare sites, isolate weak assets and move from portfolio variance to plant-level causes.","related":["Portfolio Overview","Site Performance","Loss Intelligence","Management Actions"]},"lossintelligence":{"title":"Loss Intelligence","domain":"Portfolio","purpose":"Classifies and quantifies generation losses by cause, site, asset and time period.","use":"Use it to distinguish recoverable operational losses from weather, grid and contractual constraints and to rank recovery opportunities.","related":["Portfolio Overview","Site Performance","Loss Intelligence","Management Actions"]},"commercialppa":{"title":"Commercial & PPA Intelligence","domain":"Portfolio","purpose":"Relates generation, availability and curtailment performance to PPA obligations, revenue exposure and commercial recovery.","use":"Use it to identify SLA breaches, settlement risks, curtailment impact and commercial actions requiring evidence.","related":["Portfolio Overview","Site Performance","Loss Intelligence","Management Actions"]},"managementactions":{"title":"Management Actions","domain":"Portfolio","purpose":"Consolidates priority actions, owners, due dates, value at stake and escalation status across the platform.","use":"Use it as the decision and follow-through layer after investigating operational, commercial, maintenance and ESG insights.","related":["Portfolio Overview","Site Performance","Loss Intelligence","Management Actions"]},"workorderintelligence":{"title":"Work Order Intelligence","domain":"Maintenance Intelligence","purpose":"Transforms condition evidence, failure risk, business impact and prior maintenance outcomes into prioritised, explainable work-order recommendations.","use":"Use it to review recommended actions, urgency, evidence and approval requirements before transferring approved work into ERP or EAM.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"corrective":{"title":"Corrective Maintenance","domain":"Maintenance Intelligence","purpose":"Tracks reactive work required after faults, failures or performance degradation have occurred.","use":"Use it to control backlog, restoration time, repeat failures, cost and safety exposure while preventing corrective work from becoming the dominant maintenance mode.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"preventive":{"title":"Preventive Maintenance","domain":"Maintenance Intelligence","purpose":"Plans time- or usage-based maintenance intended to prevent known degradation and statutory non-compliance.","use":"Use it to review schedule adherence, overdue activities, maintenance effectiveness and opportunities to optimise fixed intervals.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"adaptive":{"title":"Adaptive Maintenance","domain":"Maintenance Intelligence","purpose":"Adjusts maintenance timing and content dynamically using operating context, asset condition, weather and recent outcomes.","use":"Use it to increase or reduce maintenance intensity when actual risk differs from the fixed preventive plan.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"predictive":{"title":"Predictive Maintenance","domain":"Maintenance Intelligence","purpose":"Forecasts impending equipment degradation and remaining useful life from telemetry, inspection and historical failure patterns.","use":"Use it to intervene before functional failure while balancing model confidence, lead time and business consequence.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"prescriptive":{"title":"Prescriptive Maintenance","domain":"Maintenance Intelligence","purpose":"Recommends the preferred maintenance action by comparing risk reduction, production impact, cost, spares, crew and warranty implications.","use":"Use it to choose among repair, replacement, inspection, monitoring or deferral options and understand the rationale behind the recommendation.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"riskbased":{"title":"Risk-Based Maintenance","domain":"Maintenance Intelligence","purpose":"Prioritises maintenance by probability of failure and consequence across safety, generation, cost, environment and compliance.","use":"Use it to focus limited resources on the assets and failure modes with the highest combined risk.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"rcm":{"title":"Reliability-Centred Maintenance","domain":"Maintenance Intelligence","purpose":"Structures maintenance strategy around asset functions, functional failures, failure modes, consequences and technically appropriate tasks.","use":"Use it to validate whether preventive, predictive, detective, redesign or run-to-failure strategies are justified for each failure mode.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"opportunistic":{"title":"Opportunistic Maintenance","domain":"Maintenance Intelligence","purpose":"Identifies additional maintenance that can be economically combined with planned shutdowns, site visits or nearby work.","use":"Use it to reduce repeat mobilisations, outage hours and travel cost without creating unnecessary scope.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"spares":{"title":"Spares Planning","domain":"Maintenance Intelligence","purpose":"Forecasts spare-part requirements from asset population, failure risk, work plans, lead times and criticality.","use":"Use it to balance service continuity against excess inventory and to identify parts requiring procurement or redistribution.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"inventory":{"title":"Inventory Intelligence","domain":"Maintenance Intelligence","purpose":"Shows stock availability, days of cover, consumption, obsolescence, reservation and stockout exposure.","use":"Use it to identify shortage, excess and slow-moving inventory and to support replenishment or transfer decisions.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"crewscheduling":{"title":"Crew Scheduling","domain":"Maintenance Intelligence","purpose":"Matches maintenance demand with technician skills, availability, location, cost and response time.","use":"Use it to create feasible assignments, expose skill bottlenecks and reduce restoration time and travel inefficiency.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"aivision":{"title":"AI Vision","domain":"Maintenance Intelligence","purpose":"Uses visual and thermal inspection evidence to detect module, string, inverter, tracker and site-condition abnormalities.","use":"Use it to review detections, severity, confidence, business impact and recommended follow-up before creating maintenance action.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"rootcause":{"title":"Event & Root Cause Intelligence","domain":"Maintenance Intelligence","purpose":"Reconstructs incidents from alarms, telemetry, weather, asset states and work history and ranks likely root causes with evidence.","use":"Use it to understand event chronology, validate causal hypotheses and reduce manual investigation time.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"assetrelationships":{"title":"Asset Relationship Intelligence","domain":"Maintenance Intelligence","purpose":"Uses a governed knowledge graph to connect plants, assets, alarms, failures, work orders, spares, technicians, warranties, climate hazards and outcomes.","use":"Use it to explore dependencies, retrieve similar cases, simulate propagation and establish evidence-backed relationships.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"maintenancelearning":{"title":"Maintenance Learning","domain":"Maintenance Intelligence","purpose":"Learns from completed work orders, repair outcomes, recurrence, cost and restoration performance to improve future recommendations.","use":"Use it to identify successful practices, ineffective actions and failure modes requiring revised maintenance strategy.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"warrantyrecovery":{"title":"Warranty Recovery Intelligence","domain":"Maintenance Intelligence","purpose":"Identifies warranty-eligible failures and assembles operational evidence needed to pursue OEM claims and recover value.","use":"Use it to prioritise claim opportunities, monitor ageing, verify coverage and track OEM exposure and recovery status.","related":["Event & Root Cause Intelligence","Work Order Intelligence","Maintenance Learning","Spares Planning"]},"esgoverview":{"title":"ESG Overview","domain":"Sustainability Intelligence","purpose":"Consolidates environmental, social and governance performance relevant to solar operations.","use":"Use it to identify material ESG exceptions, compare sites and trace operational drivers behind reported indicators.","related":["ESG Overview","Climate Intelligence","Management Actions","Data Explorer"]},"carbonwater":{"title":"Carbon & Water","domain":"Sustainability Intelligence","purpose":"Quantifies avoided emissions, operational emissions, water withdrawal, consumption and intensity.","use":"Use it to track performance against targets, validate calculation boundaries and identify operational reduction opportunities.","related":["ESG Overview","Climate Intelligence","Management Actions","Data Explorer"]},"circularity":{"title":"Circularity","domain":"Sustainability Intelligence","purpose":"Tracks material recovery, waste diversion, module and equipment end-of-life pathways and circular procurement.","use":"Use it to identify disposal risk, recovery opportunities and compliance requirements across assets and spares.","related":["ESG Overview","Climate Intelligence","Management Actions","Data Explorer"]},"hseclimate":{"title":"HSE & Climate","domain":"Sustainability Intelligence","purpose":"Combines health, safety, environment and climate-related operating exposure.","use":"Use it to review incidents, leading indicators, hazard controls and site resilience priorities.","related":["ESG Overview","Climate Intelligence","Management Actions","Data Explorer"]},"climateintelligence":{"title":"Climate Intelligence","domain":"Sustainability Intelligence","purpose":"Assesses physical climate hazards and their implications for plant availability, equipment degradation and maintenance demand.","use":"Use it to compare hazard scenarios, identify vulnerable assets and plan adaptation measures.","related":["ESG Overview","Climate Intelligence","Management Actions","Data Explorer"]},"dataexplorer":{"title":"Data Explorer","domain":"Technology Foundation","purpose":"Provides controlled exploration of the active dataset across sheets, fields and records.","use":"Use it to inspect source data, verify values behind dashboards and identify data-quality issues before interpretation.","related":["Data Management","Enterprise Integration","AI Model Registry","Data Explorer"]},"datamanagement":{"title":"Data Management","domain":"Technology Foundation","purpose":"Controls synthetic data, bundled Excel data, workbook upload, validation, reset and data-source status.","use":"Use it to load the correct dataset, review validation results and understand which screens are supported by the uploaded workbook.","related":["Data Management","Enterprise Integration","AI Model Registry","Data Explorer"]},"integrations":{"title":"Enterprise Integration","domain":"Enterprise Integration","purpose":"Shows connectivity with SCADA, historian, weather, ERP/EAM, API and other enterprise sources, including the External Twin Platform connector.","use":"Use it to understand source ownership, interface status, data freshness, event flow and integration exceptions.","related":["Data Management","Data Explorer","AI Model Registry","Portfolio Overview"]},"models":{"title":"AI Model Registry","domain":"AI Governance","purpose":"Maintains the inventory, purpose, deployment state, owner and performance of AI and analytical models used by the platform.","use":"Use it to identify which models support each capability, review their status and trace operational decisions to governed models.","related":["Work Order Intelligence","Asset Relationship Intelligence","Data Management","Management Actions"]},"approval":{"title":"AI Approval & Governance","domain":"AI Governance","purpose":"Controls review, approval, rejection, override and audit of AI-generated recommendations and inferred relationships.","use":"Use it to ensure human accountability, segregation of duties and traceable decision-making before operational execution.","related":["Work Order Intelligence","Asset Relationship Intelligence","Data Management","Management Actions"]}};
(function standardiseAllScreenHelp(){
  const genericMetrics=[
    {name:"Headline KPIs",desc:"Summary measures for the current screen. Read the value together with its unit, period, filter context and active data source."},
    {name:"Status and priority",desc:"Operational classification used to separate normal conditions from exceptions requiring monitoring, investigation, approval or action."},
    {name:"Trend or distribution",desc:"Charts show how performance changes over time or how exposure is distributed by site, asset, cause, category or status."},
    {name:"Business impact",desc:"Where shown, energy, revenue, cost, risk, carbon, water or safety impact translates the technical condition into a decision consequence."},
    {name:"Confidence and evidence",desc:"AI-derived values should be interpreted with their confidence, evidence count, data completeness and engineering validation status."}
  ];
  const standardSections=(c)=>[
    {title:"Business value",html:`<p>${c.purpose}</p><ul><li>Concentrates attention on material exceptions rather than undifferentiated records.</li><li>Connects technical evidence to operational, financial, safety or sustainability consequences.</li><li>Creates a consistent basis for prioritisation, action ownership and management review.</li></ul>`},
    {title:"KPIs, units and interpretation",html:`<p>Read every KPI with its displayed unit and data scope. Percentages show ratios or confidence; counts show records or events; days show age, lead time or cover; MWh shows energy; currency shows estimated or realised financial impact.</p><ul><li>Do not compare values calculated on different periods or filters.</li><li>A high confidence score indicates stronger evidence, not certainty.</li><li>Red or high-priority status signals required review; it does not automatically authorise action.</li></ul>`},
    {title:"Screen controls and interaction",html:`<p>${c.use}</p><ul><li>Apply filters before interpreting charts and tables.</li><li>Select a chart element or record to expose supporting detail where available.</li><li>Use the active data-source indicator to distinguish synthetic, bundled Excel and uploaded workbook data.</li><li>Use related screens to validate the cause, operational impact and proposed action.</li></ul>`},
    {title:"How to read charts and tables",html:`<ul><li>Charts provide prioritisation and pattern recognition; tables provide record-level evidence.</li><li>Legends, axes and labels define the population, measure and unit represented.</li><li>Totals may change after filtering and should reconcile to the visible records, not necessarily the unfiltered portfolio.</li><li>Hover, selection and drill-down states provide context but do not alter source data unless an explicit action is saved.</li></ul>`},
    {title:"AI and analytical logic",html:`<p>AI features combine available telemetry, events, inspection evidence, work history, operating context and configured business rules. Outputs may include classification, prediction, similarity, ranking, anomaly detection or recommended action.</p><ul><li>Model output must be reviewed in the context of confidence, data quality and consequence.</li><li>Inferred relationships and recommendations remain advisory until approved under the applicable workflow.</li><li>ERP or EAM remains the system of record for approved transactional execution.</li></ul>`},
    {title:"Data sources and Excel mapping",html:`<p>The screen can use the embedded synthetic dataset, the bundled Excel dataset or a validated uploaded workbook. Relevant worksheets contain master data, events, measures, relationships and action records required by the view.</p><ul><li>Uploaded headers must match the supported schema or recognised aliases.</li><li>Blank, invalid or missing fields can reduce coverage or confidence.</li><li>Source-system ownership should be preserved for auditability and refresh design.</li></ul>`},
    {title:"Decisions supported",html:`<ul><li>What requires immediate action, further investigation or continued monitoring?</li><li>Which site, asset, cause or constraint contributes most to the observed outcome?</li><li>What evidence supports the recommendation, and what evidence is missing?</li><li>Who should own the next action, by when, and what value or risk is affected?</li></ul>`},
    {title:"Recommended operating practice",html:`<ul><li>Start with exceptions and material business impact, then inspect the supporting records.</li><li>Validate AI-derived conclusions with engineering and source-system evidence.</li><li>Record overrides, approvals and reasons so maintenance learning and governance remain reliable.</li><li>Review stale, unresolved and repeatedly recurring items as management exceptions.</li></ul>`},
    {title:"Limitations and cautions",html:`<ul><li>Demo and synthetic results illustrate platform behaviour and are not actual plant performance.</li><li>Predictions, simulations and inferred causes are estimates, not guaranteed outcomes.</li><li>Data latency, missing telemetry, inconsistent asset identifiers and incomplete work-order closure can affect results.</li><li>Safety-critical or high-consequence decisions require authorised human review and applicable procedures.</li></ul>`},
    {title:"Related screens",html:`<p>${(c.related||[]).join(" · ")}</p>`}
  ];
  Object.entries(ALL_SCREEN_HELP_CATALOG).forEach(([key,c])=>{
    const prior=(typeof V2_HELP!=="undefined"&&V2_HELP[key])||(typeof HELP_CONTENT!=="undefined"&&HELP_CONTENT[key])||{};
    const existing=Array.isArray(prior.sections)?prior.sections:[];
    const existingTitles=new Set(existing.map(s=>String(s.title||"").toLowerCase()));
    const additions=standardSections(c).filter(s=>!existingTitles.has(String(s.title).toLowerCase()));
    const enriched={
      ...prior,
      title:prior.title||c.title,
      what:prior.what||prior.purpose||c.purpose,
      metrics:(prior.metrics&&prior.metrics.length>=4)?prior.metrics:genericMetrics,
      interact:prior.interact||c.use,
      sections:existing.concat(additions),
      tip:prior.tip||"Use this contextual help together with the underlying evidence and related screens before taking or approving action.",
      spec:prior.spec||`${c.domain} · KPI interpretation · analytical logic · Excel mapping · governance`
    };
    if(typeof V2_HELP!=="undefined") V2_HELP[key]=enriched;
    if(typeof HELP_CONTENT!=="undefined" && !HELP_CONTENT[key]) HELP_CONTENT[key]=enriched;
  });
})();


/* Thorough, screen-specific F1 content. This layer preserves the existing green F1 button and single help box. */
const SCREEN_CONTEXTUAL_F1=__AIP_DS("a28024940d6ba6f4");
const V3_HELP={};
(function buildThoroughContextualHelp(){
  const esc=s=>String(s??"").replace(/[&<>]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[m]));
  const para=s=>`<p>${esc(s)}</p>`;
  Object.entries(SCREEN_CONTEXTUAL_F1).forEach(([key,c])=>{
    const prior=(typeof V2_HELP!=="undefined"&&V2_HELP[key])||(typeof HELP_CONTENT!=="undefined"&&HELP_CONTENT[key])||{title:key};
    const retained=(Array.isArray(prior.sections)?prior.sections:[]).filter(s=>{
      const x=String(s.title||"").toLowerCase();
      return !["business value","kpis, units and interpretation","screen controls and interaction","how to read charts and tables","ai and analytical logic","data sources and excel mapping","decisions supported","recommended operating practice","limitations and cautions","related screens"].includes(x);
    });
    const bespoke=[
      {title:"Operational workflow on this screen",html:para(c.workflow)},
      {title:"How to interpret this screen's measures",html:para(c.interpret)},
      {title:"Screen-specific data and Excel context",html:para(c.data)},
      {title:"Business questions and decisions supported",html:para(c.decisions)},
      {title:"Screen-specific limitations and controls",html:para(c.cautions)},
      {title:"Where to go next",html:para(c.related)}
    ];
    V3_HELP[key]={...prior,sections:retained.concat(bespoke),tip:prior.tip||"Use the screen-specific evidence, data scope and related views before approving operational action."};
  });
})();


/* Screen-specific KPI calculation guidance added in v1.17. */
const KPI_FORMULA_HELP=__AIP_DS("ff538c4e9889cd63");


const SUPPLEMENTAL_HELP = {
  decisionintelligence:{title:"Decision Intelligence",what:"Ranks cross-functional decisions by financial exposure, urgency, confidence and execution readiness so leaders can focus on the interventions that protect the most value.",metrics:[{name:"Decision priority",desc:"Composite rank combining value at stake, operational urgency, confidence and governance status."},{name:"Value at stake",desc:"Estimated financial consequence if the decision is delayed or not executed."},{name:"Confidence",desc:"Model-supported confidence in the recommended action, expressed as a percentage."},{name:"Decision status",desc:"Current governance stage such as recommended, approval required, approved, executing or closed."}],interact:"Review the ranked decision queue, compare financial and operational impact, open the evidence trace, then route the decision to approval or execution.",tip:"High value does not automatically mean immediate execution; review confidence, safety constraints and approval requirements together.",spec:"Executive decision prioritisation · governed AI recommendations · value-at-stake ranking"},
  financialimpact:{title:"Financial Impact",what:"Translates operational underperformance, maintenance risk and proposed interventions into revenue, cost, cash-flow and avoided-loss measures.",metrics:[{name:"Revenue protected",desc:"Expected revenue preserved by completing the recommended intervention within the decision window."},{name:"Avoided generation loss",desc:"Forecast energy loss prevented by the intervention, usually shown in MWh or GWh."},{name:"Intervention cost",desc:"Expected labour, parts, logistics and outage cost required to execute the action."},{name:"Net benefit",desc:"Revenue protected plus avoided cost minus intervention cost."},{name:"Payback",desc:"Time required for expected benefits to recover intervention cost."}],interact:"Use the financial bridge and supporting tables to understand how technical actions create economic value. Drill into assumptions before presenting the business case.",tip:"Always distinguish gross revenue protected from net benefit after execution cost.",spec:"Maintenance economics · revenue-at-risk conversion · intervention business case"},
  scenariosimulator:{title:"Scenario Simulator",what:"Compares alternative operating and maintenance choices under different timing, budget, resource and risk assumptions before a decision is committed.",metrics:[{name:"Baseline",desc:"Expected outcome if no additional intervention is taken."},{name:"Selected scenario",desc:"Outcome under the currently chosen intervention assumptions."},{name:"Incremental benefit",desc:"Difference between the selected scenario and baseline."},{name:"Risk reduction",desc:"Change in expected failure or loss exposure created by the scenario."}],interact:"Adjust the available assumptions, compare scenarios, review sensitivity and select the option with the best risk-adjusted value.",tip:"Use scenarios to expose trade-offs, not to manufacture precision; assumptions should remain visible and challengeable.",spec:"What-if analysis · risk-adjusted planning · intervention sensitivity"},
  decisiontraceability:{title:"Decision Traceability",what:"Provides the auditable chain from source evidence and model output through human review, approval, execution and realised outcome.",metrics:[{name:"Decision ID",desc:"Unique identifier linking evidence, recommendation, approval and execution records."},{name:"Evidence sources",desc:"Telemetry, inspection, work-order, weather, commercial or historical records used in the decision."},{name:"Model version",desc:"Exact model release that produced the recommendation."},{name:"Human action",desc:"Reviewer, approver or operator decision applied to the recommendation."}],interact:"Select a decision to inspect its evidence, model rationale, approvals, overrides and downstream execution record.",tip:"Traceability is essential whenever an AI recommendation changes maintenance priority, cost or operational risk.",spec:"AI audit trail · model lineage · human-in-the-loop governance"},
  closedloopexecution:{title:"Closed-Loop Execution",what:"Tracks whether approved recommendations are converted into work, completed, verified and fed back into the intelligence layer.",metrics:[{name:"Approved actions",desc:"Recommendations that have passed required governance checks."},{name:"Execution rate",desc:"Percentage of approved actions that reached completion."},{name:"Verification rate",desc:"Percentage of completed actions whose operational outcome was validated."},{name:"Loop closure time",desc:"Elapsed time from recommendation approval to verified outcome."}],interact:"Follow each action from recommendation through work-order execution and outcome verification; investigate items stalled between stages.",tip:"A recommendation creates no value until execution is completed and the result is verified.",spec:"Recommendation-to-execution lifecycle · outcome verification · ERP/EAM closure"},
  benefitsrealization:{title:"Benefits Realization",what:"Measures whether completed interventions delivered the generation, reliability, cost and sustainability benefits originally forecast.",metrics:[{name:"Forecast benefit",desc:"Expected value recorded when the decision was approved."},{name:"Realised benefit",desc:"Measured benefit after implementation and verification."},{name:"Realisation rate",desc:"Realised benefit divided by forecast benefit."},{name:"Benefit variance",desc:"Difference between forecast and realised outcome, with reasons where known."}],interact:"Compare forecast and realised results by site, action type and time period, then examine variance reasons and lessons learned.",tip:"Use verified baseline and post-action periods; otherwise realised benefit can be overstated by weather or seasonal effects.",spec:"Value assurance · post-implementation verification · benefit variance analysis"},
  reliabilityengineering:{title:"Reliability Engineering",what:"Converts failure history, condition evidence and asset criticality into reliability measures and engineered improvement priorities.",metrics:[{name:"MTBF",desc:"Mean Time Between Failures: operating time divided by number of functional failures."},{name:"MTTR",desc:"Mean Time To Repair: total corrective repair duration divided by completed repairs."},{name:"Failure rate",desc:"Observed failures per unit of operating time or asset population."},{name:"Criticality",desc:"Relative consequence of asset failure across safety, generation, revenue and recoverability."}],interact:"Use failure-mode trends, reliability indicators and asset comparisons to identify where engineering changes or maintenance-strategy changes are justified.",tip:"MTBF and MTTR should be compared within comparable asset classes and operating contexts.",spec:"Reliability engineering · failure analysis · maintainability and criticality"},
  portfoliobenchmarking:{title:"Portfolio Benchmarking",what:"Compares sites and asset populations on normalised performance, reliability, cost and execution measures to identify repeatable best practices and outliers.",metrics:[{name:"Benchmark percentile",desc:"Relative position of a site or asset against the comparison population."},{name:"Normalised performance",desc:"Performance adjusted for capacity, irradiance, age or other relevant operating context."},{name:"Gap to leader",desc:"Difference between the selected entity and the best comparable performer."},{name:"Improvement opportunity",desc:"Estimated value available if the entity reaches the chosen benchmark."}],interact:"Choose a peer group, compare ranked performance and open the underlying drivers before transferring a practice between sites.",tip:"Benchmark only comparable plants; technology, age, weather and contractual boundaries can distort rankings.",spec:"Peer benchmarking · normalised comparison · best-practice transfer"},
  aigovernance:{title:"AI Governance",what:"Shows how AI models and consequential recommendations are controlled through policies, autonomy levels, approvals, monitoring and audit records.",metrics:[{name:"Governed models",desc:"AI models registered with an owner, version, purpose, risk class and monitoring status."},{name:"Approval required",desc:"Actions that cannot proceed autonomously under the applicable policy."},{name:"Policy exceptions",desc:"Recommendations or actions that breached or required deviation from a guardrail."},{name:"Override rate",desc:"Share of AI recommendations changed or rejected by authorised users."}],interact:"Review model status, guardrails, autonomy permissions, approvals and decision outcomes. Open exceptions to understand why a recommendation was blocked or escalated.",tip:"Governance should scale with consequence: higher-cost, safety-sensitive or irreversible actions need stronger human control.",spec:"Model registry · guardrails · autonomy matrix · approval and override audit"},
  assetexplorer:{title:"Asset Explorer",what:"Provides a searchable, filterable view of the complete asset hierarchy and its current operational, maintenance and risk context.",metrics:[{name:"Asset health",desc:"Current condition score or status derived from available operating and maintenance evidence."},{name:"Open risk",desc:"Active alerts, work orders or condition exceptions linked to the asset."},{name:"Criticality",desc:"Business consequence assigned to loss or degradation of the asset."},{name:"Lifecycle status",desc:"Commissioning, operating, maintenance, retired or other master-data state."}],interact:"Filter by site, asset class, health, risk or status; select an asset to inspect its master data and connected operational records.",tip:"Use Asset Explorer as the starting point when investigating one physical asset rather than a portfolio-wide issue.",spec:"Asset hierarchy · master data · asset-centric operational context"},
  climateintelligence:{title:"Climate Intelligence APIs",what:"Configures and monitors external weather and climate-risk data used in forecasting, maintenance planning, resilience and site-risk assessment.",metrics:[{name:"API status",desc:"Current connectivity and authentication state for each climate or weather provider."},{name:"Freshness",desc:"Elapsed time since the most recent successful data refresh."},{name:"Coverage",desc:"Sites, variables, forecast horizons or climate hazards supplied by the provider."},{name:"Vendor site risk",desc:"Provider-reported physical climate exposure for each site and hazard."}],interact:"Review provider configuration, refresh status, site coverage and risk outputs. Use the test or refresh controls before relying on a forecast in operational planning.",tip:"Forecast weather and long-horizon climate risk serve different decisions and should not be interpreted interchangeably.",spec:"Weather and climate APIs · physical-risk data · source freshness and coverage"}
};
