const F1_TERM_DICTIONARY = {
 "PR":"Performance Ratio: actual AC energy output divided by the energy expected from measured irradiance and installed capacity, after the selected normalisation rules.",
 "Performance Ratio":"A weather-normalised indicator of how effectively a PV plant converts available solar resource into electrical energy.",
 "Availability":"Share of the reporting period in which the plant or asset was technically capable of operating, using the screen's stated weighting basis.",
 "Fleet Health Index":"Composite portfolio score combining condition, availability, performance, open critical work and remaining-life exposure.",
 "RUL":"Remaining Useful Life: estimated operating time until an asset reaches a defined failure or intervention threshold.",
 "MTBF":"Mean Time Between Failures: total operating time divided by functional-failure count.",
 "MTTR":"Mean Time To Repair: total corrective repair duration divided by completed corrective repairs.",
 "SLA":"Service Level Agreement: contractual or internally governed response, restoration or completion target.",
 "PPA":"Power Purchase Agreement: commercial contract defining energy sale, tariff, availability or delivery obligations.",
 "POA":"Plane of Array irradiance: solar irradiance incident on the module plane.",
 "GHI":"Global Horizontal Irradiance: total solar irradiance received by a horizontal surface.",
 "Revenue at Risk":"Estimated revenue exposure associated with forecast generation loss, availability loss, contractual penalty or delayed intervention.",
 "Value at Stake":"Financial consequence potentially created, protected or lost by a decision.",
 "Confidence":"Model-supported certainty in a classification, prediction or recommendation; not the same as guaranteed accuracy.",
 "Criticality":"Relative consequence of asset failure across safety, generation, revenue, compliance and recoverability.",
 "Risk Score":"Combined measure of likelihood and consequence, sometimes adjusted for detectability, exposure or urgency.",
 "Proactive Share":"Percentage of maintenance activity classified as preventive, predictive or adaptive rather than reactive corrective work.",
 "Corrective":"Maintenance performed after a confirmed fault or functional failure.",
 "Preventive":"Time- or usage-based maintenance scheduled before failure, independent of current condition.",
 "Predictive":"Condition- or model-based maintenance triggered by forecast deterioration or failure probability.",
 "Prescriptive":"Decision support that recommends the preferred action after considering risk, cost, constraints and expected outcome.",
 "Adaptive":"Maintenance timing or scope dynamically adjusted using current operating context, risk and resource conditions.",
 "Risk-Based":"Maintenance prioritised according to likelihood and business consequence rather than calendar alone.",
 "RCM":"Reliability-Centred Maintenance: structured selection of maintenance tasks based on functions, failure modes, consequences and applicable interventions.",
 "FMEA":"Failure Modes and Effects Analysis: systematic assessment of how components can fail and the effects of those failures.",
 "Work Order":"Controlled record authorising and tracking maintenance scope, priority, labour, parts, permits, status, cost and closure evidence.",
 "ERP/EAM":"Enterprise Resource Planning / Enterprise Asset Management system used as the transactional system of record.",
 "Warranty Recovery":"Identification, submission and realisation of supplier or OEM warranty claims that offset repair or replacement cost.",
 "Detection Confidence":"Probability-like model score associated with a visual or analytical finding; it should be interpreted with validation thresholds.",
 "Generation Loss":"Energy not produced compared with an expected or counterfactual baseline.",
 "Curtailment":"Intentional reduction of generation due to grid, contractual, market or operational constraints.",
 "Soiling Loss":"Generation reduction caused by dust, dirt or other material on module surfaces.",
 "Degradation":"Long-term decline in asset or module performance relative to an initial or warranted baseline.",
 "Carbon Avoided":"Estimated emissions avoided by renewable generation relative to an applicable grid or displaced-generation emission factor.",
 "Water Intensity":"Water consumed or withdrawn per unit of electricity generated or another stated denominator.",
 "Circularity":"Extent to which materials, components and waste are reused, refurbished, recycled or kept in productive circulation.",
 "Scope 1":"Direct greenhouse-gas emissions from sources owned or controlled by the reporting entity.",
 "Scope 2":"Indirect greenhouse-gas emissions from purchased electricity, steam, heat or cooling.",
 "Scope 3":"Other indirect greenhouse-gas emissions across the value chain.",
 "HSE":"Health, Safety and Environment.",
 "Climate Risk":"Potential financial or operational impact from physical climate hazards or transition-related changes.",
 "Guardrail":"Policy rule that permits, blocks, limits or escalates an AI-generated recommendation or action.",
 "Autonomy":"Degree to which an AI-enabled action can proceed without human approval.",
 "Model Drift":"Change in data patterns or model performance that may reduce reliability after deployment.",
 "Data Freshness":"Elapsed time since the latest successful data update.",
 "Data Quality":"Fitness of data for use, commonly assessed through completeness, validity, consistency, timeliness and uniqueness.",
 "Root Cause":"Underlying condition or mechanism that produced an event, rather than the immediate symptom alone.",
 "Event Reconstruction":"Chronological linking of signals, alarms, work history and operating context to explain how an incident developed.",
 "Benefit Realisation":"Verified comparison of actual post-action value against the benefit forecast at approval.",
 "Benchmark Percentile":"Relative rank of an entity within a defined comparable peer population."
};

function f1CleanText(v){return String(v||"").replace(/\s+/g," ").trim();}
function f1Unique(arr){return [...new Set(arr.map(f1CleanText).filter(Boolean))];}
function f1NearestTitle(el,root){
  let n=el;
  for(let i=0;i<4 && n && n!==root;i++,n=n.parentElement){
    const h=n.querySelector(':scope > h2,:scope > h3,:scope > h4,:scope > .chart-title,:scope > .card-title,:scope > .panel-title');
    if(h && !h.contains(el)) return f1CleanText(h.textContent);
  }
  let p=el.previousElementSibling;
  while(p){if(/^H[2-4]$/.test(p.tagName)) return f1CleanText(p.textContent);p=p.previousElementSibling;}
  return "Chart or visual";
}
function collectRenderedHelp(view){
  const root=document.getElementById('view-'+view);
  if(!root) return {kpis:[],charts:[],tables:[],controls:[],terms:[]};
  const visible=el=>!!(el.offsetWidth||el.offsetHeight||el.getClientRects().length);
  const kpiSelectors=['.kpi-card','.metric-card','.stat-card','.summary-card','.vision-kpi','.exec-kpi','.portfolio-kpi','.guardrail-kpi'];
  const kpis=[];
  root.querySelectorAll(kpiSelectors.join(',')).forEach(card=>{
    if(!visible(card)) return;
    const label=card.querySelector('.kpi-label,.metric-label,.stat-label,.label,h3,h4,strong,b');
    const value=card.querySelector('.kpi-value,.metric-value,.stat-value,.value,.big-number');
    const name=f1CleanText(label&&label.textContent);
    const val=f1CleanText(value&&value.textContent);
    if(name && name.length<100) kpis.push(val?`${name} — currently ${val}`:name);
  });
  const charts=[];
  root.querySelectorAll('canvas,svg.chart,svg[data-chart],.chart-wrap,.chart-container').forEach(el=>{if(visible(el)) charts.push(f1NearestTitle(el,root));});
  const tables=[];
  root.querySelectorAll('table').forEach((tbl,idx)=>{
    if(!visible(tbl)) return;
    const title=f1NearestTitle(tbl,root);
    const heads=f1Unique([...tbl.querySelectorAll('thead th')].map(x=>x.textContent)).slice(0,18);
    tables.push(`${title}${heads.length?` — columns: ${heads.join(', ')}`:''}`);
  });
  const controls=[];
  root.querySelectorAll('button,select,input:not([type="hidden"]),textarea').forEach(el=>{
    if(!visible(el) || el.classList.contains('f1-btn')) return;
    let t=el.tagName==='SELECT'?(el.getAttribute('aria-label')||el.previousElementSibling?.textContent||el.id):
      (el.getAttribute('aria-label')||el.placeholder||el.textContent||el.value||el.id);
    t=f1CleanText(t); if(t && t.length<90 && !/^×|✕$/.test(t)) controls.push(t);
  });
  const screenText=f1CleanText(root.innerText).toLowerCase();
  const terms=Object.keys(F1_TERM_DICTIONARY).filter(term=>screenText.includes(term.toLowerCase()));
  return {kpis:f1Unique(kpis).slice(0,24),charts:f1Unique(charts).slice(0,20),tables:f1Unique(tables).slice(0,16),controls:f1Unique(controls).slice(0,24),terms};
}
function f1InventoryHtml(inv){
  const list=(title,items)=>`<div class="help-inventory"><h5>${title}</h5>${items.length?`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`:'<div class="help-empty">None displayed on this screen.</div>'}</div>`;
  return `<div class="help-section"><h4>Exact content currently displayed</h4><p>This section is generated from the rendered screen, so it stays aligned with the selected data mode, filters and current view.</p><div class="help-grid">${list('KPIs and summary measures',inv.kpis)}${list('Charts and visual analyses',inv.charts)}${list('Tables and visible columns',inv.tables)}${list('Filters, actions and controls',inv.controls)}</div></div>`;
}
function f1GlossaryHtml(inv){
  if(!inv.terms.length) return '';
  return `<div class="help-section"><h4>Terminology used on this screen</h4>${inv.terms.map(t=>`<div class="help-term"><b>${t}</b><span>${F1_TERM_DICTIONARY[t]}</span></div>`).join('')}</div>`;
}

function openHelp(view){
  const h = V3_HELP[view] || V2_HELP[view] || HELP_CONTENT[view];
  if(!h) return;
  const what = h.what || h.purpose || "";
  const interact = h.interact || "";
  const tip = h.tip || "Use the screen together with its related drill-down views and verify source-system ownership before taking action.";
  const spec = h.spec || "Contextual application guidance";
  document.getElementById("helpTag").textContent = "Contextual F1 Help · "+view.toUpperCase();
  document.getElementById("helpTitle").textContent = h.title;
  const inv = collectRenderedHelp(view);
  let body = `<div class="help-search-wrap"><input id="helpSearch" class="help-search" type="search" placeholder="Search this screen's help, KPI, chart, table or term" aria-label="Search contextual help"><div class="help-live-note">Screen-matched help for the content currently rendered in ${APM_DATA_MODE||'the active'} data mode.</div></div>`;
  body += `<div class="help-section"><h4>Purpose and scope</h4><p>${what}</p></div>`;
  const formulaItems = KPI_FORMULA_HELP[view] || [];
  if(formulaItems.length){
    body += `<div class="help-section"><h4>KPI definitions and calculation formulas</h4><p>Each calculation below states the governing formula, unit, reporting boundary and treatment rules. Where the screen displays a composite score, the component weights shown here are the demo calculation logic and should be governed as configurable model parameters in production.</p><div class="help-metrics">${formulaItems.map(m=>`<div class="help-metric"><b>${m.name}</b><span><strong>Formula:</strong> ${m.formula}<br><strong>Unit:</strong> ${m.unit}<br><strong>Scope / period:</strong> ${m.scope}<br><strong>Inclusion, exclusion and aggregation rules:</strong> ${m.rules}<br><strong>How to interpret:</strong> ${m.meaning}</span></div>`).join("")}</div></div>`;
  } else if(h.metrics&&h.metrics.length){
    body += `<div class="help-section"><h4>Key measures and fields</h4><div class="help-metrics">${h.metrics.map(m=>`<div class="help-metric"><b>${m.name}</b><span>${m.desc}</span></div>`).join("")}</div></div>`;
  }
  body += f1InventoryHtml(inv);
  body += `<div class="help-section"><h4>How to use this screen</h4><p>${interact}</p></div>`;
  if(h.sections&&h.sections.length){
    body += h.sections.map(s=>`<div class="help-section"><h4>${s.title}</h4>${s.html}</div>`).join("");
  }
  body += f1GlossaryHtml(inv);
  body += `<div class="help-tip">💡 ${tip}</div>`;
  body += `<div class="help-spec"><b>Functional reference:</b> ${spec}</div>`;
  document.getElementById("helpBody").innerHTML = body;
  const search=document.getElementById('helpSearch');
  if(search) search.addEventListener('input',()=>{
    const q=search.value.trim().toLowerCase();
    document.querySelectorAll('#helpBody .help-section').forEach(sec=>sec.dataset.helpSearchHidden=(q && !sec.innerText.toLowerCase().includes(q))?'true':'false');
  });
  document.getElementById("helpOverlay").classList.add("open");
  setTimeout(()=>{if(search) search.focus();},50);
  document.querySelectorAll(".f1-btn").forEach(b=>b.classList.remove("active"));
  const activeBtn = document.querySelector(`.view.active .f1-btn`);
  if(activeBtn) activeBtn.classList.add("active");
}
window.openHelp = openHelp;

