const EVENT_TEMPLATES = {
  scada:    ()=> `Inverter telemetry batch received — ${rndInt(38,44)},${rndInt(100,999)} tags/min`,
  historian:()=> `Time-series write-back complete — ${round1(rnd(6.2,7.4))}M rows`,
  weather:  ()=> `Forecast refresh — POA ${rndInt(520,780)} W/m² (${pick(PLANTS).id})`,
  erp:      ()=> `Batch job queued — cost-center sync (${pick(PLANTS).id})`,
  cmms:     ()=> `Work order ${pick(["COR","ADP","PRE"])}-${rndInt(4000,4400)} acknowledged by O&M crew`,
  gis:      ()=> `Tile cache refresh attempted — latency above threshold`,
  docmgmt:  ()=> `Warranty document requested — INV-${rndInt(2022,2025)}-${rndInt(100,199)}`,
  apm:      ()=> `Bi-directional sync — work order MAX-${rndInt(88000,88999)} updated`,
};

let integrationSimTimer = null;
let lastStreamSeedMode = "";
let streamInitQueue = [];

function streamModeLabel(){
  if(APM_DATA_MODE === "Uploaded data") return "EXCEL";
  if(APM_DATA_MODE === "Excel demo data") return "EXCEL DEMO";
  return "SYNTHETIC";
}

function pushEvent(key, message){
  const el = document.getElementById("eventStream");
  if(!el) return false;
  const i = INTEGRATIONS.find(x=>x.key===key) || {name:key || "AIP"};
  const now = new Date();
  const hh = String(now.getHours()).padStart(2,"0"), mm = String(now.getMinutes()).padStart(2,"0"), ss = String(now.getSeconds()).padStart(2,"0");
  const line = document.createElement("div");
  line.className = "ev-line";
  const safeTemplate = EVENT_TEMPLATES[key];
  const text = message || (typeof safeTemplate === "function" ? safeTemplate() : "Operational event received");
  line.innerHTML = `<span class="ev-time">${hh}:${mm}:${ss}</span><span class="ev-sys">${i.name.toUpperCase()}</span>${text}`;
  el.appendChild(line);
  while(el.children.length > 40) el.removeChild(el.firstChild);
  el.scrollTop = el.scrollHeight;
  return true;
}

function seedIntegrationStream(force=false){
  const el = document.getElementById("eventStream");
  if(!el) return;
  const mode = streamModeLabel();
  if(!force && lastStreamSeedMode===mode) return;
  el.innerHTML = "";
  lastStreamSeedMode = mode;
  streamInitQueue = [
    ["scada", `${mode} dataset activated — telemetry stream initialised`],
    ["historian", `Historical operating records indexed for ${mode.toLowerCase()} analysis`],
    ["apm", `Asset intelligence models connected to ${mode.toLowerCase()} data context`],
    ["cmms", `Decision and work-order enrichment channel ready`]
  ];
}

function runIntegrationStreamTick(){
  const view = document.getElementById("view-integrations");
  const visible = !!view && view.classList.contains("active");

  INTEGRATIONS.forEach(i=>{
    i.syncAgoSec += 2;
    i.latencyMs = Math.max(20, i.latencyMs * (1 + rnd(-0.07,0.07)));
    if(i.resyncPeriod && i.syncAgoSec >= i.resyncPeriod){
      i.syncAgoSec = rnd(0,2);
      if(i.throughputVal!=null) i.throughputVal = Math.max(0.1, i.throughputVal * (1 + rnd(-0.05,0.06)));
    }
    if(visible){
      const lat = document.getElementById("lat-"+i.key);
      const sync = document.getElementById("sync-"+i.key);
      const thr = document.getElementById("thr-"+i.key);
      if(lat) lat.textContent = fmtLatency(i.latencyMs);
      if(sync) sync.textContent = fmtSyncAgo(i.syncAgoSec);
      if(thr) thr.textContent = fmtThroughput(i);
    }
  });

  if(!visible) return;
  seedIntegrationStream(false);
  if(streamInitQueue.length){
    const [key, message] = streamInitQueue.shift();
    pushEvent(key, message);
  }else{
    const source = INTEGRATIONS[Math.floor(Math.random()*INTEGRATIONS.length)] || INTEGRATIONS[0];
    if(source) pushEvent(source.key);
  }
}

function startIntegrationSim(forceRestart=false){
  if(forceRestart && integrationSimTimer){
    clearInterval(integrationSimTimer);
    integrationSimTimer = null;
  }
  if(integrationSimTimer) return;
  integrationSimTimer = setInterval(runIntegrationStreamTick, 2000);
}

