const n=v=>v===null||v===""||v===undefined?null:Number(v), s=v=>v===null||v===undefined?"":String(v), d=v=>{if(v instanceof Date)return v.toISOString().slice(0,10);if(typeof v==="number"&&window.XLSX){const z=XLSX.SSF.parse_date_code(v);return z?`${z.y}-${String(z.m).padStart(2,"0")}-${String(z.d).padStart(2,"0")}`:s(v)}return s(v).slice(0,10)};
function rowKey(row,fields){return fields.map(f=>s(row[f]).trim()).join("¦")}
function replaceArray(target,rows){target.splice(0,target.length,...rows)}
function mergeRows(existing,incoming,rule,mode){if(mode==="replace")return incoming.slice();const map=new Map(existing.map(r=>[rowKey(r,rule.key),r]));incoming.forEach(r=>{const k=rowKey(r,rule.key);if(mode==="add"&&!map.has(k))map.set(k,r);if(mode==="update")map.set(k,{...(map.get(k)||{}),...r})});return [...map.values()]}
function openEamDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open("APM_App",1);q.onupgradeneeded=()=>q.result.createObjectStore("state");q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function saveEamState(){if(window.__AIP_PERSISTENCE__)return window.__AIP_PERSISTENCE__.save({data:APM_IMPORTED_DATA,lastImport:APM_LAST_IMPORT,mode:APM_DATA_MODE});const db=await openEamDb();return new Promise((resolve,reject)=>{const tx=db.transaction("state","readwrite");tx.objectStore("state").put({data:APM_IMPORTED_DATA,lastImport:APM_LAST_IMPORT,mode:APM_DATA_MODE},"current");tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function loadEamState(){if(window.__AIP_PERSISTENCE__)return window.__AIP_PERSISTENCE__.load();const db=await openEamDb();return new Promise((resolve,reject)=>{const q=db.transaction("state").objectStore("state").get("current");q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function clearEamState(){if(window.__AIP_PERSISTENCE__)return window.__AIP_PERSISTENCE__.clear();const db=await openEamDb();return new Promise((resolve,reject)=>{const tx=db.transaction("state","readwrite");tx.objectStore("state").clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function parseEamWorkbook(wb){const data={};Object.keys(APM_SHEET_RULES).forEach(name=>{if(!wb.SheetNames.includes(name))return;const matrix=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:null,raw:true});const rule=APM_SHEET_RULES[name];let hi=matrix.findIndex(row=>rule.required.every(f=>row.includes(f)));if(hi<0)hi=matrix.findIndex(row=>rule.required.some(f=>row.includes(f)));if(hi<0)return;const headers=matrix[hi].map(s);data[name]=matrix.slice(hi+1).filter(row=>row.some(v=>v!==null&&v!=="")).map(row=>Object.fromEntries(headers.map((h,i)=>[h,row[i]??null]))) });return data}
function validateEamData(data){const errors=[],stats={};const sites=new Set((data["Sites"]||APM_IMPORTED_DATA["Sites"]||[]).map(r=>s(r.Plant_ID)));const assets=new Set((data["Asset Master"]||APM_IMPORTED_DATA["Asset Master"]||[]).map(r=>s(r.Asset_ID)));const techs=new Set((data["Crew & Skills"]||APM_IMPORTED_DATA["Crew & Skills"]||[]).map(r=>s(r.Technician_ID)));const parts=new Set((data["Spare Parts Master"]||APM_IMPORTED_DATA["Spare Parts Master"]||[]).map(r=>s(r.Part_ID)));const wos=new Set((data["Work Orders"]||APM_IMPORTED_DATA["Work Orders"]||[]).map(r=>s(r.Work_Order_ID)));
  Object.entries(data).forEach(([name,rows])=>{const rule=APM_SHEET_RULES[name];stats[name]=rows.length;const seen=new Set();rows.forEach((r,i)=>{rule.required.forEach(f=>{if(r[f]===null||r[f]===undefined||s(r[f]).trim()==="")errors.push({sheet:name,row:i+2,field:f,message:"Required value is blank"})});const k=rowKey(r,rule.key);if(seen.has(k))errors.push({sheet:name,row:i+2,field:rule.key.join(" + "),message:"Duplicate primary key"});seen.add(k);
    if(r.Plant_ID&&!sites.has(s(r.Plant_ID)))errors.push({sheet:name,row:i+2,field:"Plant_ID",message:"Plant_ID not found in Sites"});if(r.Asset_ID&&!assets.has(s(r.Asset_ID)))errors.push({sheet:name,row:i+2,field:"Asset_ID",message:"Asset_ID not found in Asset Master"});if(r.Technician_ID&&!techs.has(s(r.Technician_ID)))errors.push({sheet:name,row:i+2,field:"Technician_ID",message:"Technician_ID not found in Crew & Skills"});if(r.Part_ID&&!parts.has(s(r.Part_ID)))errors.push({sheet:name,row:i+2,field:"Part_ID",message:"Part_ID not found in Spare Parts Master"});if(r.Work_Order_ID&&!wos.has(s(r.Work_Order_ID)))errors.push({sheet:name,row:i+2,field:"Work_Order_ID",message:"Work_Order_ID not found in Work Orders"});if(name==="Inventory Balance"&&n(r.Opening_Qty)+n(r.Receipts_30D)-n(r.Issues_30D)!==n(r.Closing_Qty))errors.push({sheet:name,row:i+2,field:"Closing_Qty",message:"Opening + receipts − issues does not equal closing"});if(r.Risk_Score!==undefined&&(n(r.Risk_Score)<0||n(r.Risk_Score)>1))errors.push({sheet:name,row:i+2,field:"Risk_Score",message:"Risk score must be between 0 and 1"})})});return{valid:errors.length===0,errors,stats}}
