function dxCurrentSourceLabel(full){
  if(CONNECTED_ERPS.size){
    const names = [...CONNECTED_ERPS].map(k=>ERP_SYSTEMS[k].name);
    const shorts = [...CONNECTED_ERPS].map(k=>ERP_SYSTEMS[k].short);
    return full ? names.join(" + ") : shorts.join(" + ")+" data";
  }
  if(APM_DATA_MODE==="Uploaded data") return full ? "your uploaded workbook" : "Uploaded data";
  if(APM_DATA_MODE==="Excel demo data") return full ? "the bundled Excel workbook" : "Excel data";
  return full ? "the synthetic demo dataset" : "Synthetic data";
}
function buildDataContext(){
  const totalMW = PLANTS.reduce((a,p)=>a+p.mw,0);
  const woByType={}, woByStatus={}, woByPriority={};
  ALL_WOS.forEach(w=>{woByType[w.type]=(woByType[w.type]||0)+1; woByStatus[w.status]=(woByStatus[w.status]||0)+1; woByPriority[w.priority]=(woByPriority[w.priority]||0)+1;});
  const assetByClass={}, assetByRisk={};
  ASSET_REGISTRY.forEach(a=>{assetByClass[a.cls]=(assetByClass[a.cls]||0)+1; assetByRisk[a.riskBand]=(assetByRisk[a.riskBand]||0)+1;});
  const ctx = {
    dataSource: dxCurrentSourceLabel(true),
    portfolio: {
      totalSites: PLANTS.length, totalMW,
      avgPRpct: round1(PLANTS.reduce((a,p)=>a+p.pr,0)/PLANTS.length),
      avgAvailabilityPct: round1(PLANTS.reduce((a,p)=>a+p.availability,0)/PLANTS.length),
      sites: PLANTS.map(p=>({id:p.id,name:p.name,state:p.state,mw:p.mw,prPct:p.pr,availabilityPct:p.availability,healthScore:p.healthScore}))
    },
    workOrders: {
      total: ALL_WOS.length, byType: woByType, byStatus: woByStatus, byPriority: woByPriority,
      currentMTTRhrs: MTTR_TREND[MTTR_TREND.length-1], currentMTBFhrs: MTBF_TREND[MTBF_TREND.length-1],
      trailing24moPRpct: PR_TREND, trailing24moAvailabilityPct: AVAIL_TREND, monthLabels: MONTHS,
    },
    spareParts: SPARE_PARTS.map(p=>({part:p.part,category:p.cat,stock:p.stock,reorderPoint:p.reorder,maxStock:p.max,leadDays:p.lead,unitCostINR:p.cost,status:p.status})),
    purchaseOrders: PURCHASE_ORDERS.length ? PURCHASE_ORDERS.map(po=>({id:po.id,part:po.part,supplier:po.supplier,qty:po.qty,valueINR:po.value,status:po.status})) : "none currently loaded",
    esg: {
      totalGenerationMWh: Math.round(esgSum("generation")),
      netCarbonBenefitTCO2e: Math.round(esgSum("netCarbon")),
      waterIntensityKLperMWh: round2(esgSum("water")/esgSum("generation")),
      wasteDiversionPct: Math.round(esgSum("diverted")/esgSum("waste")*100),
      lostTimeInjuries: esgSum("lti"),
      complianceOverdueCount: ESG_COMPLIANCE.filter(c=>c.status==="Action Required").length,
      complianceTotal: ESG_COMPLIANCE.length,
      supplierCount: ESG_SUPPLIERS.length,
      highRiskSupplierCount: ESG_SUPPLIERS.filter(s=>s.risk==="High").length,
      climateRiskBySite: ESG_CLIMATE.map(c=>({plant:c.plantName,riskScore0to1:c.score,estAnnualLossINR:c.annualLoss})),
      targetsFY2026: ESG_TARGETS,
    },
    assets: ASSET_REGISTRY.length ? {
      total: ASSET_REGISTRY.length, byClass: assetByClass, byRiskBand: assetByRisk,
      avgHealthScore: Math.round(ASSET_REGISTRY.reduce((a,x)=>a+x.healthScore,0)/ASSET_REGISTRY.length),
    } : "none currently loaded",
    crew: CREW_ROSTER.length ? {
      totalTechnicians: CREW_ROSTER.length,
      avgHourlyCostINR: Math.round(CREW_ROSTER.reduce((a,c)=>a+c.hourlyCost,0)/CREW_ROSTER.length),
      activeAssignments: CREW_ASSIGNMENTS.length,
    } : "none currently loaded",
    riskQueue: RISK_QUEUE.slice(0,25).map(r=>({asset:r.asset,plant:r.plant,compositeRisk:r.composite,tier:r.tier})),
    aiModelRegistry: { total: MODEL_REGISTRY.length, inProduction: MODEL_REGISTRY.filter(m=>m.status==="Production").length, inShadow: MODEL_REGISTRY.filter(m=>m.status==="Shadow").length },
  };
  return JSON.stringify(ctx);
}
const DX_SYSTEM_PREFIX = `You are the embedded data analyst inside "Asset Intelligence Platform" — a solar O&M platform. Answer questions using ONLY the JSON data context below; never invent figures. Simple derived math (sums, averages, ratios, rankings) from the given numbers is fine — show it briefly if useful. If something isn't in the data, say so plainly rather than guessing.

Keep answers concise (2-6 sentences) unless the person asks for depth. Use ₹ for INR figures. You may use light markdown: **bold**, and "- " bullet lines.

If — and only if — a chart would genuinely clarify a numeric comparison across categories (sites, months, categories, etc.), append exactly ONE fenced block at the very end of your reply in this exact form:
\`\`\`chart
{"type":"bar","title":"short title","labels":["...","..."],"values":[0,0],"unit":"optional suffix like %, MW, hrs"}
\`\`\`
Use "type":"line" instead of "bar" for a time trend. Omit the chart block entirely for single-number answers or non-numeric questions.

LIVE DATA CONTEXT (source: reflects whichever system is currently connected in the app):
`;
async function callAssistantAPI(apiMessages){
  const endpoint = localStorage.getItem("eam_ai_assistant_endpoint") || "/api/assistant";
  if(!window.OA_CONNECTION||window.OA_CONNECTION.state!=="connected"||window.OA_CONNECTION.endpoint!==endpoint) throw new Error("Assistant endpoint has not been verified. Open Connection and run Save & Test.");
  const response = await fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      max_tokens: 1400,
      system: DX_SYSTEM_PREFIX + buildDataContext(),
      messages: apiMessages,
      attachments: (window.OA_FILES||[]).map(f=>({name:f.name,type:f.type,size:f.size}))
    })
  });
  if(!response.ok) throw new Error("Online service returned status "+response.status);
  const data = await response.json();
  const text = typeof data.reply==="string" ? data.reply : (data.content||[]).filter(b=>b.type==="text").map(b=>b.text).join("\n").trim();
  if(!text) throw new Error("The online service returned an empty response");
  return text;
}
function dxExtractChart(text){
  const m = text.match(/```chart\s*([\s\S]*?)```/);
  if(!m) return { text, chart:null };
  let chart = null;
  try{ chart = JSON.parse(m[1].trim()); }catch(e){ chart = null; }
  return { text: text.slice(0, m.index).trim() || text.replace(m[0],"").trim(), chart };
}
function dxMdToHtml(text){
  let h = text.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  h = h.replace(/\*\*(.+?)\*\*/g, "<b>$1</b>");
  h = h.split(/\n{2,}/).map(block=>{
    const lines = block.split("\n");
    if(lines.every(l=>/^\s*-\s+/.test(l)) && lines.length>1){
      return "<ul style='margin:6px 0 6px 18px;padding:0'>"+lines.map(l=>`<li>${l.replace(/^\s*-\s+/,"")}</li>`).join("")+"</ul>";
    }
    return "<p style='margin:0 0 8px'>"+lines.join("<br>")+"</p>";
  }).join("");
  return h;
}
function answerDataQuestion(qRaw){
  const q = qRaw.toLowerCase().trim();
  const src = dxCurrentSourceLabel(true);
  const tag = (n) => `<span class="dx-msg-source">Source: ${n} · ${src}</span>`;

  if(/^(hi|hello|hey)\b|^help$/.test(q)){
    return `Hi! Ask me things like "what's the average PR" or "how many critical work orders are open" — I compute answers live from whichever dataset is currently loaded (<b>${src}</b>).`;
  }

  // --- Portfolio ---
  if(/total.*(capacity|\bmw\b)|how much.*(capacity|\bmw\b)/.test(q)){
    const mw = PLANTS.reduce((a,p)=>a+p.mw,0);
    return `The portfolio totals <b>${mw.toLocaleString()} MW</b> across ${PLANTS.length} sites.${tag("Sites")}`;
  }
  if(/how many.*(sites|plants)\b/.test(q)){
    return `There are <b>${PLANTS.length} sites</b> in the portfolio, totaling ${PLANTS.reduce((a,p)=>a+p.mw,0).toLocaleString()} MW.${tag("Sites")}`;
  }
  if(/(lowest|worst) (pr|performance ratio)/.test(q)){
    const p = [...PLANTS].sort((a,b)=>a.pr-b.pr)[0];
    return `<b>${p.name}</b> (${p.id}) has the lowest PR at <b>${p.pr}%</b>.${tag("Sites")}`;
  }
  if(/(highest|best) (pr|performance ratio)/.test(q)){
    const p = [...PLANTS].sort((a,b)=>b.pr-a.pr)[0];
    return `<b>${p.name}</b> (${p.id}) has the highest PR at <b>${p.pr}%</b>.${tag("Sites")}`;
  }
  if(/average.*(pr\b|performance ratio)/.test(q)){
    const avg = round1(PLANTS.reduce((a,p)=>a+p.pr,0)/PLANTS.length);
    return `Portfolio average PR is <b>${avg}%</b>.${tag("Sites")}`;
  }
  if(/(lowest|worst) availability/.test(q)){
    const p = [...PLANTS].sort((a,b)=>a.availability-b.availability)[0];
    return `<b>${p.name}</b> (${p.id}) has the lowest availability at <b>${p.availability}%</b>.${tag("Sites")}`;
  }
  if(/(highest|best) availability/.test(q)){
    const p = [...PLANTS].sort((a,b)=>b.availability-a.availability)[0];
    return `<b>${p.name}</b> (${p.id}) has the highest availability at <b>${p.availability}%</b>.${tag("Sites")}`;
  }
  if(/average.*availability/.test(q)){
    const avg = round1(PLANTS.reduce((a,p)=>a+p.availability,0)/PLANTS.length);
    return `Portfolio average availability is <b>${avg}%</b>.${tag("Sites")}`;
  }
  if(/fleet health|health index/.test(q)){
    const avg = Math.round(PLANTS.reduce((a,p)=>a+p.healthScore,0)/PLANTS.length);
    return `Fleet Health Index is <b>${avg}/100</b> — the average across ${PLANTS.length} sites.${tag("Sites")}`;
  }
  if(/plants? in ([a-z ]+)/.test(q)){
    const state = q.match(/plants? in ([a-z ]+)/)[1].trim().replace(/\?$/,"");
    const matches = PLANTS.filter(p=>p.state.toLowerCase().includes(state));
    if(!matches.length) return `I couldn't find any sites in "${state}".${tag("Sites")}`;
    return `${matches.length} site(s) in ${state}: <b>${matches.map(p=>p.name+" ("+p.id+")").join(", ")}</b>.${tag("Sites")}`;
  }

  // --- Work orders / maintenance ---
  if(/how many (open|closed) work orders/.test(q)){
    const wantOpen = /open/.test(q);
    const n = ALL_WOS.filter(w=>wantOpen ? w.status!=="Closed" : w.status==="Closed").length;
    return `There are <b>${n} ${wantOpen?"open":"closed"} work orders</b> out of ${ALL_WOS.length} total.${tag("Work Orders")}`;
  }
  if(/how many (corrective|preventive|adaptive|predictive) work orders/.test(q)){
    const type = q.match(/corrective|preventive|adaptive|predictive/)[0];
    const n = ALL_WOS.filter(w=>w.type.toLowerCase()===type).length;
    return `There are <b>${n} ${type} work orders</b>.${tag("Work Orders")}`;
  }
  if(/critical work orders?/.test(q)){
    const n = ALL_WOS.filter(w=>w.priority==="Critical" && w.status!=="Closed").length;
    return `There are <b>${n} open Critical-priority work orders</b>.${tag("Work Orders")}`;
  }
  if(/\bmttr\b|mean time to repair/.test(q)){
    const v = MTTR_TREND[MTTR_TREND.length-1];
    return `Current MTTR (Mean Time To Repair) is <b>${v} hrs</b>.${tag("Corrective Maintenance")}`;
  }
  if(/\bmtbf\b|mean time between failures/.test(q)){
    const v = MTBF_TREND[MTBF_TREND.length-1];
    return `Current MTBF (Mean Time Between Failures) is <b>${v} hrs</b>.${tag("Corrective Maintenance")}`;
  }
  if(/overdue (preventive|pm) tasks?|how many overdue/.test(q)){
    const n = PREVENTIVE_WOS.filter(w=>w.overdueDays>0).length;
    return `There are <b>${n} overdue preventive tasks</b>.${tag("Preventive Maintenance")}`;
  }

  // --- Spares / inventory / procurement ---
  if(/total inventory value|inventory.*(value|worth)/.test(q)){
    const v = SPARE_PARTS.reduce((a,p)=>a+p.stock*p.cost,0);
    return `Total spares inventory value is <b>${fmtINR(v)}</b> across ${SPARE_PARTS.length} SKUs.${tag("Spare Parts")}`;
  }
  if(/(skus?|parts) (below|under) reorder|need(s)? (a )?reorder/.test(q)){
    const n = SPARE_PARTS.filter(p=>p.status!=="OK").length;
    return `<b>${n} of ${SPARE_PARTS.length} SKUs</b> are at or below their reorder point.${tag("Spare Parts")}`;
  }
  if(/(most expensive|highest cost).*(part|sku)/.test(q)){
    const p = [...SPARE_PARTS].sort((a,b)=>b.cost-a.cost)[0];
    return `<b>${p.part}</b> is the most expensive SKU at <b>${fmtINR(p.cost)}</b> per unit.${tag("Spare Parts")}`;
  }
  if(/lowest stock|least stock/.test(q)){
    const p = [...SPARE_PARTS].sort((a,b)=>a.stock-b.stock)[0];
    return `<b>${p.part}</b> has the lowest stock at <b>${p.stock} units</b> (reorder point ${p.reorder}).${tag("Spare Parts")}`;
  }
  if(/purchase orders?/.test(q)){
    if(!PURCHASE_ORDERS.length) return `No purchase order data is currently loaded from ${src}.${tag("Purchase Orders")}`;
    return `There are <b>${PURCHASE_ORDERS.length} purchase orders</b> on record, worth ${fmtINR(PURCHASE_ORDERS.reduce((a,p)=>a+p.value,0))}.${tag("Purchase Orders")}`;
  }

  // --- ESG ---
  if(/total (generation|renewable generation)/.test(q)){
    const g = esgSum("generation");
    return `Total renewable generation is <b>${Math.round(g/1000).toLocaleString()} GWh</b>.${tag("ESG Monthly")}`;
  }
  if(/net carbon benefit/.test(q)){
    const v = esgSum("netCarbon");
    return `Net carbon benefit is <b>${Math.round(v).toLocaleString()} tCO₂e</b>.${tag("ESG Monthly")}`;
  }
  if(/water intensity/.test(q)){
    const v = round2(esgSum("water")/esgSum("generation"));
    return `Portfolio water intensity is <b>${v} kL/MWh</b>.${tag("ESG Monthly")}`;
  }
  if(/waste diversion/.test(q)){
    const v = Math.round(esgSum("diverted")/esgSum("waste")*100);
    return `Waste diversion rate is <b>${v}%</b>.${tag("ESG Monthly")}`;
  }
  if(/lost.time injur/.test(q)){
    const v = esgSum("lti");
    return `There have been <b>${v} lost-time injuries</b> recorded.${tag("ESG Monthly")}`;
  }
  if(/high.risk suppliers?/.test(q)){
    const n = ESG_SUPPLIERS.filter(s=>s.risk==="High").length;
    return `<b>${n} of ${ESG_SUPPLIERS.length} suppliers</b> are flagged High ESG risk.${tag("Supplier ESG")}`;
  }
  if(/(highest|most) climate risk/.test(q)){
    const p = [...ESG_CLIMATE].sort((a,b)=>b.score-a.score)[0];
    return `<b>${p.plantName}</b> has the highest physical climate risk score at <b>${Math.round(p.score*100)}/100</b>.${tag("Climate Risk")}`;
  }
  if(/compliance (actions|obligations)?.*(overdue|due|action)/.test(q)){
    const n = ESG_COMPLIANCE.filter(c=>c.status==="Action Required").length;
    return `<b>${n} compliance obligations</b> currently require action.${tag("ESG Compliance")}`;
  }

  // --- Assets ---
  if(/how many assets/.test(q)){
    return `There are <b>${ASSET_REGISTRY.length.toLocaleString()} registered assets</b> across the fleet.${tag("Asset Register")}`;
  }
  if(/most common (oem|manufacturer)/.test(q)){
    if(!ASSET_REGISTRY.length) return `No asset data is currently loaded from ${src}.${tag("Asset Register")}`;
    const counts={}; ASSET_REGISTRY.forEach(a=>counts[a.oem]=(counts[a.oem]||0)+1);
    const top = Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];
    return `The most common OEM is <b>${top[0]}</b> (${top[1]} assets).${tag("Asset Register")}`;
  }
  if(/average (asset )?health/.test(q)){
    if(!ASSET_REGISTRY.length) return `No asset data is currently loaded from ${src}.${tag("Asset Register")}`;
    const avg = Math.round(ASSET_REGISTRY.reduce((a,x)=>a+x.healthScore,0)/ASSET_REGISTRY.length);
    return `Average asset health score is <b>${avg}/100</b>.${tag("Asset Register")}`;
  }
  if(/high.risk assets?/.test(q)){
    const n = ASSET_REGISTRY.filter(a=>a.riskBand==="High").length;
    return `<b>${n} assets</b> are flagged High risk band.${tag("Asset Register")}`;
  }

  // --- Crew ---
  if(/how many (technicians|crew)/.test(q)){
    return `There are <b>${CREW_ROSTER.length} technicians</b> on the roster.${tag("Crew & Skills")}`;
  }
  if(/average.*(hourly cost|crew cost)/.test(q)){
    if(!CREW_ROSTER.length) return `No crew data is currently loaded from ${src}.${tag("Crew & Skills")}`;
    const avg = Math.round(CREW_ROSTER.reduce((a,c)=>a+c.hourlyCost,0)/CREW_ROSTER.length);
    return `Average technician hourly cost is <b>${fmtINR(avg)}</b>.${tag("Crew & Skills")}`;
  }
  if(/crew assignments?/.test(q)){
    return `There are <b>${CREW_ASSIGNMENTS.length} active crew assignments</b>.${tag("Crew Assignments")}`;
  }

  // --- Risk / models ---
  if(/critical risk|critical.tier/.test(q)){
    const n = RISK_QUEUE.filter(r=>r.tier==="Critical").length;
    return `<b>${n} items</b> are in the Critical risk tier of the fleet-wide queue.${tag("Risk-Based Queue")}`;
  }
  if(/models? (are )?in production|production models?/.test(q)){
    const n = MODEL_REGISTRY.filter(m=>m.status==="Production").length;
    return `<b>${n} of ${MODEL_REGISTRY.length} models</b> are in production.${tag("AI Model Registry")}`;
  }

  return `I couldn't match that to a specific question yet. Try asking about portfolio capacity/PR/availability, work orders (open/critical/MTTR/MTBF), spares &amp; inventory value, ESG generation/carbon/water/waste, assets &amp; crew, or the risk queue and model registry — or tap a suggestion below.`;
}

let DX_CHART_SEQ = 0;
window.OA_MODE = localStorage.getItem("eam_assistant_mode") || "offline";

function oaSetMode(mode){
  window.OA_MODE = mode === "online" ? "online" : "offline";
  localStorage.setItem("eam_assistant_mode", window.OA_MODE);
  renderDataExplorer();
}
function offlineChartForQuery(qRaw){
  const q=qRaw.toLowerCase();
  if(/(compare|show|chart|rank).*(pr|performance ratio).*(site|plant)|pr.*(by|across).*(site|plant)/.test(q)){
    return {type:"bar",title:"PR by site",labels:PLANTS.map(p=>p.id),values:PLANTS.map(p=>p.pr),unit:"%"};
  }
  if(/(compare|show|chart|rank).*availability.*(site|plant)|availability.*(by|across).*(site|plant)/.test(q)){
    return {type:"bar",title:"Availability by site",labels:PLANTS.map(p=>p.id),values:PLANTS.map(p=>p.availability),unit:"%"};
  }
  if(/work orders?.*(priority|priorities)|priority.*work orders?/.test(q)){
    const labels=["Critical","High","Medium","Low"];
    return {type:"bar",title:"Work orders by priority",labels,values:labels.map(x=>ALL_WOS.filter(w=>w.priority===x).length),unit:""};
  }
  if(/inventory.*(status|reorder)|spares?.*(status|reorder)/.test(q)){
    const labels=["OK","Reorder","Critical"];
    return {type:"bar",title:"Inventory status",labels,values:labels.map(x=>SPARE_PARTS.filter(p=>p.status===x).length),unit:" SKUs"};
  }
  if(/(trend|monthly).*(pr|performance ratio)|pr.*trend/.test(q)){
    return {type:"line",title:"Portfolio PR trend",labels:MONTHS,values:PR_TREND,unit:"%"};
  }
  if(/(trend|monthly).*availability|availability.*trend/.test(q)){
    return {type:"line",title:"Portfolio availability trend",labels:MONTHS,values:AVAIL_TREND,unit:"%"};
  }
  if(/(trend|monthly).*(generation|renewable generation)|generation.*trend/.test(q)){
    const labels=[...new Set(ESG_MONTHLY.map(x=>x.month))];
    return {type:"line",title:"Monthly renewable generation",labels,values:labels.map(m=>Math.round(ESG_MONTHLY.filter(x=>x.month===m).reduce((a,x)=>a+x.generation,0))),unit:" MWh"};
  }
  return null;
}

/* ============================================================
   ASSET INTELLIGENCE ASSISTANT — GENERIC OFFLINE ANALYTICS ENGINE
   ============================================================ */
function aiEsc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function aiNum(v, integer=false){
  const n=Number(v);
  if(!Number.isFinite(n)) return "–";
  return integer ? Math.round(n).toLocaleString("en-IN") :
    n.toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2});
}
function aiTable(headers, rows, integerCols=[]){
  return `<div class="dx-table-wrap"><table class="decision-execution-queue dx-result-table"><thead><tr>${
    headers.map((h,i)=>`<th class="${i>0?'numeric-column':''}">${aiEsc(h)}</th>`).join("")
  }</tr></thead><tbody>${
    rows.map(r=>`<tr>${r.map((v,i)=>`<td class="${i>0?'numeric-cell':''}">${
      i===0?aiEsc(v):aiEsc(typeof v==="number"?aiNum(v,integerCols.includes(i)):v)
    }</td>`).join("")}</tr>`).join("")
  }</tbody></table></div>`;
}
function aiSourceTag(name){return `<div class="dx-source">Source: ${aiEsc(name)}</div>`;}
function aiNormalize(q){return String(q||"").toLowerCase().replace(/[^\w%₹.-]+/g," ").replace(/\s+/g," ").trim();}
function aiHas(q, words){return words.some(w=>q.includes(w));}
function aiTopN(q, fallback=5){
  const m=q.match(/\b(?:top|bottom|lowest|highest|best|worst)\s+(\d{1,2})\b/);
  return m?Math.max(1,Math.min(20,Number(m[1]))):fallback;
}
function aiDirection(q){
  if(/\b(lowest|bottom|least|worst|declining|underperform)/.test(q)) return "asc";
  return "desc";
}
function aiChartIntent(q){
  if(/\b(line|trend|over time|monthly|time series)\b/.test(q)) return "line";
  if(/\b(doughnut|donut|pie|share|mix|distribution)\b/.test(q)) return "doughnut";
  if(/\b(chart|graph|compare|rank|ranking|show)\b/.test(q)) return "bar";
  return null;
}
function aiApplyPlantFilter(records,q,plantField="plant"){
  let out=records.slice();
  const states=[...new Set((PLANTS||[]).map(p=>p.state).filter(Boolean))];
  const plants=PLANTS||[];
  states.forEach(s=>{if(q.includes(String(s).toLowerCase())) out=out.filter(r=>{
    const pid=r[plantField]||r.plantId||r.site||r.siteId;
    const p=plants.find(x=>x.id===pid||x.name===pid);
    return p&&String(p.state).toLowerCase()===String(s).toLowerCase();
  });});
  plants.forEach(p=>{
    const keys=[p.id,p.name].filter(Boolean).map(x=>String(x).toLowerCase());
    if(keys.some(k=>q.includes(k))) out=out.filter(r=>{
      const pid=String(r[plantField]||r.plantId||r.site||r.siteId||"").toLowerCase();
      return keys.includes(pid);
    });
  });
  return out;
}
function aiDetectDomain(q){
  if(aiHas(q,["work order","maintenance order","corrective","preventive","predictive","adaptive","mttr","mtbf","Overdue Actions"])) return "workorders";
  if(aiHas(q,["spare","inventory","sku","reorder","stock","part","lead time","supplier"])) return "spares";
  if(aiHas(q,["asset","oem","manufacturer","health score","risk band","inverter","transformer"])) return "assets";
  if(aiHas(q,["generation","pr ","performance ratio","availability","plant","site","capacity","revenue loss"])) return "plants";
  if(aiHas(q,["carbon","water","waste","esg","emission","climate","hse","sustainability"])) return "esg";
  if(aiHas(q,["crew","technician","skill","assignment","hourly cost"])) return "crew";
  return "portfolio";
}
function aiPlantRows(q){
  let rows=(PLANTS||[]).map(p=>({
    id:p.id,name:p.name,state:p.state,capacity:Number(p.mw||p.capacity||p.capacityMW||p.Capacity_MW||0),
    pr:Number(p.pr||0),availability:Number(p.availability||0),
    health:Number(p.healthScore||0)
  }));
  rows=aiApplyPlantFilter(rows,q,"id");
  let metric="pr", label="Performance Ratio", unit="%";
  if(q.includes("availability")){metric="availability";label="Availability";unit="%";}
  else if(q.includes("capacity")){metric="capacity";label="Capacity";unit=" MW";}
  else if(q.includes("health")){metric="health";label="Health Score";unit="/100";}
  const dir=aiDirection(q), n=aiTopN(q,rows.length);
  rows.sort((a,b)=>dir==="asc"?a[metric]-b[metric]:b[metric]-a[metric]);
  const selected=rows.slice(0,n);
  const avg=selected.reduce((s,r)=>s+r[metric],0)/(selected.length||1);
  const html=`<b>${label} analysis</b><br>Average across ${selected.length} selected site(s): <b>${aiNum(avg)}${unit}</b>.`+
    aiTable(["Site",label],selected.map(r=>[`${r.name||r.id} (${r.id})`,r[metric]]))+aiSourceTag("Plant Registry");
  return {html,chart:{type:"bar",title:`${label} by site`,labels:selected.map(r=>r.id),values:selected.map(r=>r[metric]),unit}};
}
function aiWorkOrderRows(q){
  let rows=(ALL_WOS||[]).slice();
  rows=aiApplyPlantFilter(rows,q,"plant");
  const statuses=["open","closed","in progress","planned","approved"];
  statuses.forEach(s=>{if(q.includes(s)) rows=rows.filter(w=>String(w.status||"").toLowerCase().includes(s));});
  ["critical","high","medium","low"].forEach(p=>{if(q.includes(p)) rows=rows.filter(w=>String(w.priority||"").toLowerCase()===p);});
  ["corrective","preventive","predictive","adaptive"].forEach(t=>{if(q.includes(t)) rows=rows.filter(w=>String(w.type||"").toLowerCase()===t);});
  if(q.includes("Overdue Actions")) rows=rows.filter(w=>Number(w.overdueDays||0)>0);
  const group = q.includes("priority")?"priority":q.includes("status")?"status":q.includes("type")?"type":q.includes("plant")||q.includes("site")?"plant":null;
  if(group){
    const map={}; rows.forEach(w=>{const k=w[group]||"Unknown";map[k]=(map[k]||0)+1;});
    const arr=Object.entries(map).sort((a,b)=>b[1]-a[1]);
    return {html:`<b>Work order distribution by ${group}</b>${aiTable([group[0].toUpperCase()+group.slice(1),"Count"],arr, [1])}${aiSourceTag("Work Orders")}`,
      chart:{type:"bar",title:`Work orders by ${group}`,labels:arr.map(x=>x[0]),values:arr.map(x=>x[1]),unit:""}};
  }
  const n=aiTopN(q,10);
  const list=rows.slice().sort((a,b)=>(Number(b.overdueDays||0)-Number(a.overdueDays||0))).slice(0,n);
  const table=list.map(w=>[w.id||w.wo||"–",w.plant||"–",w.type||"–",w.priority||"–",w.status||"–",Number(w.overdueDays||0)]);
  return {html:`Found <b>${rows.length.toLocaleString("en-IN")} matching work orders</b>.${aiTable(["Work Order","Plant","Type","Priority","Status","Overdue Days"],table,[5])}${aiSourceTag("Work Orders")}`,chart:null};
}
function aiSparesRows(q){
  let rows=(SPARE_PARTS||[]).slice();
  if(q.includes("below reorder")||q.includes("under reorder")||q.includes("reorder")) rows=rows.filter(p=>Number(p.stock||0)<=Number(p.reorder||0)||String(p.status||"")!=="OK");
  const lm=q.match(/lead time\s*(?:above|over|greater than|>)\s*(\d+)/);
  if(lm) rows=rows.filter(p=>Number(p.leadTime||p.leadDays||0)>Number(lm[1]));
  if(q.includes("critical")) rows=rows.filter(p=>String(p.status||"").toLowerCase()==="critical");
  if(q.includes("inventory value")||q.includes("stock value")||q.includes("value by")){
    const group=q.includes("category")?"cat":q.includes("supplier")?"supplier":null;
    if(group){
      const map={};rows.forEach(p=>{const k=p[group]||"Unknown";map[k]=(map[k]||0)+Number(p.stock||0)*Number(p.cost||0);});
      const arr=Object.entries(map).sort((a,b)=>b[1]-a[1]);
      return {html:`<b>Inventory value by ${group==="cat"?"category":"supplier"}</b>${aiTable([group==="cat"?"Category":"Supplier","Inventory Value"],arr)}${aiSourceTag("Spare Parts")}`,
        chart:{type:"bar",title:"Inventory value",labels:arr.map(x=>x[0]),values:arr.map(x=>x[1]),unit:" ₹"}};
    }
    const total=rows.reduce((s,p)=>s+Number(p.stock||0)*Number(p.cost||0),0);
    return {html:`Total inventory value for the selected records is <b>₹${aiNum(total)}</b> across <b>${rows.length}</b> SKUs.${aiSourceTag("Spare Parts")}`,chart:null};
  }
  const n=aiTopN(q,10);
  rows.sort((a,b)=>Number(a.stock||0)-Number(b.stock||0));
  return {html:`Found <b>${rows.length}</b> matching spare parts.${aiTable(["Part","Category","Stock","Reorder Point","Unit Cost","Lead Time"],rows.slice(0,n).map(p=>[p.part||p.id,p.cat||p.category||"–",Number(p.stock||0),Number(p.reorder||0),Number(p.cost||0),Number(p.leadTime||p.leadDays||0)]),[2,3,5])}${aiSourceTag("Spare Parts")}`,chart:null};
}
function aiAssetRows(q){
  let rows=(ASSET_REGISTRY||[]).slice();
  rows=aiApplyPlantFilter(rows,q,"plant");

  /* Count intent must answer the governed population, not convert the request
     into a top-N asset listing. */
  const isCountIntent=/\b(how many|number of|total|count of|asset count)\b/.test(q)
    && /\bassets?\b/.test(q)
    && !/\b(list|show|which|details?|lowest|highest|top|bottom|risk|health|oem|manufacturer)\b/.test(q);
  if(isCountIntent){
    const scoped=rows.length;
    const hasPlant=/\b(sp-\d{1,2}|plant|site)\b/.test(q);
    return {html:`AIP currently has <b>${scoped.toLocaleString("en-IN")} governed assets</b>${hasPlant?" in the requested scope":" across the active portfolio"}.${aiSourceTag("Asset Register")}`,chart:null};
  }

  if(q.includes("high risk")) rows=rows.filter(a=>String(a.riskBand||"").toLowerCase()==="high");
  if(q.includes("medium risk")) rows=rows.filter(a=>String(a.riskBand||"").toLowerCase()==="medium");
  ["inverter","transformer","module","tracker","scada"].forEach(t=>{if(q.includes(t)) rows=rows.filter(a=>String(a.type||a.assetType||"").toLowerCase().includes(t));});
  if(q.includes("oem")||q.includes("manufacturer")){
    const map={};rows.forEach(a=>{const k=a.oem||"Unknown";map[k]=(map[k]||0)+1;});
    const arr=Object.entries(map).sort((a,b)=>b[1]-a[1]);
    return {html:`<b>Assets by OEM</b>${aiTable(["OEM","Asset Count"],arr,[1])}${aiSourceTag("Asset Register")}`,
      chart:{type:"bar",title:"Assets by OEM",labels:arr.map(x=>x[0]),values:arr.map(x=>x[1]),unit:""}};
  }
  const n=aiTopN(q,10);
  rows.sort((a,b)=>Number(a.healthScore||0)-Number(b.healthScore||0));
  return {html:`Found <b>${rows.length.toLocaleString("en-IN")}</b> matching assets.${aiTable(["Asset","Plant","Type","OEM","Health Score","Risk Band"],rows.slice(0,n).map(a=>[a.id||a.assetId,a.plant||"–",a.type||a.assetType||"–",a.oem||"–",Number(a.healthScore||0),a.riskBand||"–"]))}${aiSourceTag("Asset Register")}`,chart:null};
}
function aiESGRows(q){
  const data=ESG_MONTHLY||[];
  const labels=[...new Set(data.map(x=>x.month))];
  let field="generation",label="Renewable Generation",unit=" MWh";
  if(q.includes("carbon")){field="netCarbon";label="Net Carbon Benefit";unit=" tCO₂e";}
  else if(q.includes("water")){field="water";label="Water Use";unit=" kL";}
  else if(q.includes("waste")){field="waste";label="Waste Generated";unit=" t";}
  const vals=labels.map(m=>data.filter(x=>x.month===m).reduce((s,x)=>s+Number(x[field]||0),0));
  const total=vals.reduce((a,b)=>a+b,0);
  const html=`<b>${label}</b><br>Total: <b>${aiNum(total)}${unit}</b>; monthly average: <b>${aiNum(total/(vals.length||1))}${unit}</b>.`+
    aiTable(["Month",label],labels.map((m,i)=>[m,vals[i]]))+aiSourceTag("ESG Monthly");
  return {html,chart:{type:"line",title:`Monthly ${label}`,labels,values:vals,unit}};
}
function aiExecutiveSummary(){
  const avgPR=(PLANTS||[]).reduce((s,p)=>s+Number(p.pr||0),0)/((PLANTS||[]).length||1);
  const avgAvail=(PLANTS||[]).reduce((s,p)=>s+Number(p.availability||0),0)/((PLANTS||[]).length||1);
  const critical=(ALL_WOS||[]).filter(w=>w.priority==="Critical"&&w.status!=="Closed").length;
  const reorder=(SPARE_PARTS||[]).filter(p=>Number(p.stock||0)<=Number(p.reorder||0)||p.status!=="OK").length;
  const highRisk=(ASSET_REGISTRY||[]).filter(a=>a.riskBand==="High").length;
  return {html:`<b>Portfolio intelligence summary</b><ul>
    <li>Average PR: <b>${aiNum(avgPR)}%</b></li>
    <li>Average availability: <b>${aiNum(avgAvail)}%</b></li>
    <li>Open critical work orders: <b>${critical}</b></li>
    <li>SKUs requiring attention: <b>${reorder}</b></li>
    <li>High-risk assets: <b>${highRisk}</b></li>
  </ul><b>Recommended focus:</b> resolve critical work orders at the lowest-performing sites, validate spares availability for those interventions, and prioritize high-risk assets with declining health.${aiSourceTag("Active Portfolio Dataset")}`,chart:null};
}

/* v427 — Governed multi-table local query engine.
   No external AI/API is required. It parses a bounded natural-language grammar,
   executes deterministic joins/filters/grouping locally, and exposes lineage. */
function gqEsc(v){return aiEsc(v)}
function gqValue(obj,...keys){
  for(const k of keys){
    if(obj && obj[k]!==undefined && obj[k]!==null && obj[k]!=="") return obj[k];
  }
  return null;
}
function gqDate(v){
  if(!v)return null;
  const d=new Date(String(v).length<=10?String(v)+"T00:00:00":String(v));
  return Number.isNaN(d.getTime())?null:d;
}
function gqLatestDate(rows,keys){
  let latest=null;
  (rows||[]).forEach(r=>{
    const d=gqDate(gqValue(r,...keys));
    if(d && (!latest||d>latest))latest=d;
  });
  return latest;
}
function gqAddMonths(d,n){
  const x=new Date(d.getTime());
  x.setMonth(x.getMonth()+n);
  return x;
}
function gqAddDays(d,n){
  const x=new Date(d.getTime());
  x.setDate(x.getDate()+n);
  return x;
}
function gqFmtDate(d){
  if(!d)return "—";
  return `${String(d.getDate()).padStart(2,"0")}-${String(d.getMonth()+1).padStart(2,"0")}-${d.getFullYear()}`;
}
function gqParseWindow(q,rows,dateKeys){
  const asOf=gqLatestDate(rows,dateKeys)||new Date();
  let start=null,label=null;
  let m=q.match(/\blast\s+(\d+)\s+months?\b/);
  if(m){start=gqAddMonths(asOf,-Number(m[1]));label=`last ${m[1]} month${Number(m[1])===1?"":"s"}`;}
  if(!start && (m=q.match(/\blast\s+(\d+)\s+weeks?\b/))){
    start=gqAddDays(asOf,-7*Number(m[1]));label=`last ${m[1]} week${Number(m[1])===1?"":"s"}`;
  }
  if(!start && (m=q.match(/\blast\s+(\d+)\s+days?\b/))){
    start=gqAddDays(asOf,-Number(m[1]));label=`last ${m[1]} day${Number(m[1])===1?"":"s"}`;
  }
  if(!start && /\blast three months\b/.test(q)){start=gqAddMonths(asOf,-3);label="last 3 months";}
  if(!start && /\blast six months\b/.test(q)){start=gqAddMonths(asOf,-6);label="last 6 months";}
  if(!start && /\blast year|last 12 months\b/.test(q)){start=gqAddMonths(asOf,-12);label="last 12 months";}
  return {asOf,start,label};
}
function gqPlanBox(stepsOrPlan,sources=[],note=""){
  const p=Array.isArray(stepsOrPlan)
    ? {intent:"Governed natural-language query",datasets:sources,joins:[],filters:[],grouping:[],calculations:stepsOrPlan,validation:note||"Executed against available governed data.",status:"Executed"}
    : (stepsOrPlan||{});
  const chips=(arr,cls="gq-source-chip")=>(arr||[]).map(x=>`<span class="${cls}">${gqEsc(x)}</span>`).join("");
  const rows=[];
  if(p.intent)rows.push(["Intent",p.intent]);
  if((p.datasets||[]).length)rows.push(["Datasets",chips(p.datasets)]);
  if((p.joins||[]).length)rows.push(["Joins",chips(p.joins,"gq-join-chip")]);
  if((p.filters||[]).length)rows.push(["Filters",`<ul>${p.filters.map(x=>`<li>${gqEsc(x)}</li>`).join("")}</ul>`]);
  if((p.grouping||[]).length)rows.push(["Grouping",`<ul>${p.grouping.map(x=>`<li>${gqEsc(x)}</li>`).join("")}</ul>`]);
  if((p.calculations||[]).length)rows.push(["Calculations",`<ol>${p.calculations.map(x=>`<li>${gqEsc(x)}</li>`).join("")}</ol>`]);
  if(p.validation)rows.push(["Validation",gqEsc(p.validation)]);
  if(p.status)rows.push(["Status",`<span class="gq-status ${String(p.status).toLowerCase().includes("limit")?"limited":"ok"}">${gqEsc(p.status)}</span>`]);
  return `<details class="gq-plan"><summary>Governed query plan & lineage</summary>
    <div class="gq-plan-body"><div class="gq-plan-grid">${
      rows.map(([k,v])=>`<div class="gq-plan-key">${gqEsc(k)}</div><div class="gq-plan-val">${v}</div>`).join("")
    }</div>${p.note?`<div class="gq-note">${gqEsc(p.note)}</div>`:""}</div></details>`;
}

function gqNoData(title,reason,steps,sources){
  return {html:`<b>${gqEsc(title)}</b><div class="gq-warning">${gqEsc(reason)}</div>${gqPlanBox(steps,sources,reason)}`,chart:null};
}
function gqFailureQuery(q){
  if(!/\b(fail|failed|failure|breakdown|broke down)\b/.test(q) || !/\bassets?\b/.test(q))return null;

  const rows=(typeof CORRECTIVE_WOS!=="undefined"&&Array.isArray(CORRECTIVE_WOS)?CORRECTIVE_WOS:
             (ALL_WOS||[]).filter(w=>String(gqValue(w,"type","Type","WO_Type")||"").toLowerCase()==="corrective")).slice();
  const dateKeys=["failureDate","Failure_Date","eventDate","Event_Date","created","Created_Date","createdDate"];
  const win=gqParseWindow(q,rows,dateKeys);
  let scoped=rows.filter(w=>{
    const d=gqDate(gqValue(w,...dateKeys));
    return !win.start || (d && d>=win.start && d<=win.asOf);
  });

  let minCount=1;
  let m=q.match(/\b(?:at least|minimum|more than|greater than)?\s*(\d+)\s*(?:times?|failures?)\b/);
  if(m){
    const n=Number(m[1]);
    minCount=/\bmore than|greater than\b/.test(m[0])?n+1:n;
  }else if(/\btwice\b/.test(q)) minCount=2;
  else if(/\bthree times\b/.test(q)) minCount=3;

  const groups=new Map();
  scoped.forEach(w=>{
    const asset=String(gqValue(w,"Asset_ID","assetId","asset","Asset","Asset_Tag","assetTag")||"").trim();
    if(!asset)return;
    const key=asset.toLowerCase();
    if(!groups.has(key))groups.set(key,{asset,count:0,plant:gqValue(w,"Plant_ID","plant","plantId","site","Site_ID")||"—",dates:[],orders:[]});
    const g=groups.get(key);g.count++;
    const d=gqDate(gqValue(w,...dateKeys));if(d)g.dates.push(d);
    g.orders.push(gqValue(w,"WO_ID","Work_Order_ID","id","wo")||"—");
  });
  const result=[...groups.values()].filter(g=>g.count>=minCount).sort((a,b)=>b.count-a.count||a.asset.localeCompare(b.asset));
  const period=win.start?`${gqFmtDate(win.start)} to ${gqFmtDate(win.asOf)}`:"all available history";
  const steps=[
    `Use corrective work orders as governed failure-event records`,
    win.start?`Filter failure dates to ${period}`:`Use all available failure dates`,
    `Group records by governed asset identifier / asset label`,
    `Count failure records per asset and retain count ≥ ${minCount}`
  ];
  const qualifier=`Failure is defined here by Corrective Work Orders because that is the available governed failure-event source in this demo.`;
  const table=result.length?aiTable(
    ["Asset","Site","Failure Count","Failure Dates","Work Orders"],
    result.map(g=>[g.asset,g.plant,g.count,g.dates.sort((a,b)=>a-b).map(gqFmtDate).join(", "),g.orders.join(", ")]),
    [2]
  ):"";
  return {html:`<b>${result.length.toLocaleString("en-IN")} asset${result.length===1?"":"s"} failed at least ${minCount} time${minCount===1?"":"s"}</b> during <b>${period}</b>.${table}${gqPlanBox({
    intent:"Identify assets with repeated governed failure events",
    datasets:["Corrective Work Orders","Asset identifier / label"],
    joins:[],
    filters:[win.start?`Failure date between ${period}`:"All available failure history",`Failure count ≥ ${minCount}`],
    grouping:["Asset identifier / governed asset label"],
    calculations:steps,
    validation:qualifier,
    status:"Executed"
  })}`,chart:null};
}
function gqSiteCapacityAssetCountQuery(q){
  if(!/\b(site|sites|plant|plants)\b/.test(q))return null;
  if(!/\bcapacity\b/.test(q) || !/\bassets?\b/.test(q))return null;

  let cap=null,assets=null,capOp=">",assetOp=">";
  let m=q.match(/capacity(?:\s+\w+){0,4}?\s*(?:greater than|more than|above|over|>)\s*(\d+(?:\.\d+)?)\s*(?:mw|megawatt)/);
  if(!m)m=q.match(/(?:greater than|more than|above|over|>)\s*(\d+(?:\.\d+)?)\s*(?:mw|megawatt)(?:\s+capacity)?/);
  if(m)cap=Number(m[1]);
  m=q.match(/(?:more than|greater than|above|over|>)\s*(\d+)\s*assets?/);
  if(m)assets=Number(m[1]);
  if(cap===null||assets===null)return null;

  const asksHistorical=/\b(any point|at any point|ever|historical|history|over time)\b/.test(q);
  const hasTemporalAssetHistory=Array.isArray(window.ASSET_COUNT_HISTORY)&&window.ASSET_COUNT_HISTORY.length>0;
  const counts={};
  (ASSET_REGISTRY||[]).forEach(a=>{
    const p=String(gqValue(a,"Plant_ID","plant","plantId","site","Site_ID")||"").trim();
    if(p)counts[p]=(counts[p]||0)+1;
  });
  const sites=(PLANTS||[]).map(p=>({
    id:p.id,name:p.name,
    capacity:Number(gqValue(p,"mw","capacity","capacityMW","Capacity_MW")||0),
    assetCount:Number(counts[p.id]||0)
  })).filter(x=>x.capacity>cap && x.assetCount>assets);

  const steps=[
    `Read site capacity from Plant Registry and filter capacity > ${cap} MW`,
    `Group current Asset Register by site and calculate governed asset count`,
    `Join site capacity to site asset count`,
    `Retain sites where asset count > ${assets}`
  ];
  if(asksHistorical && !hasTemporalAssetHistory){
    return {html:`<b>No historically provable result can be returned for “at any point in time”.</b>
      <div class="gq-warning">AIP currently has the present Asset Register, but no governed site-level asset-count history with effective-from/effective-to dates. The current snapshot can be evaluated, but it cannot prove whether a site exceeded ${assets} assets at some earlier date.</div>
      ${sites.length?`<div class="gq-current-snapshot"><b>Current snapshot:</b> ${sites.length} site${sites.length===1?"":"s"} meet both thresholds today.${aiTable(["Site","Capacity MW","Current Asset Count"],sites.map(s=>[`${s.name} (${s.id})`,s.capacity,s.assetCount]),[2])}</div>`:`<div class="gq-current-snapshot"><b>Current snapshot:</b> no site meets both thresholds.</div>`}
      ${gqPlanBox({
        intent:"Find sites meeting capacity and historical asset-count thresholds",
        datasets:["Plant Registry","Asset Register"],
        joins:["Plant Registry.Site_ID = Asset Register.Site_ID"],
        filters:[`Capacity > ${cap} MW`,`Asset count > ${assets}`,"Historical / at-any-point condition requested"],
        grouping:["Site"],
        calculations:steps,
        validation:"Current snapshot can be calculated; historical threshold cannot be proven without effective-dated asset history.",
        status:"Limited by governed data",
        note:"Historical test requires Asset_ID + Site_ID + Effective_From + Effective_To (or equivalent asset movement history)."
      })}`,chart:null};
  }

  return {html:`<b>${sites.length} site${sites.length===1?"":"s"} meet both conditions</b>: capacity &gt; ${cap} MW and asset count &gt; ${assets}.${sites.length?aiTable(["Site","Capacity MW","Asset Count"],sites.map(s=>[`${s.name} (${s.id})`,s.capacity,s.assetCount]),[2]):""}${gqPlanBox({
    intent:"Find sites meeting both capacity and asset-count thresholds",
    datasets:["Plant Registry","Asset Register"],
    joins:["Plant Registry.Site_ID = Asset Register.Site_ID"],
    filters:[`Capacity > ${cap} MW`,`Current asset count > ${assets}`],
    grouping:["Site"],
    calculations:steps,
    validation:"Both conditions are evaluated from the active governed snapshot.",
    status:"Executed"
  })}`,chart:null};
}

function gqDomainPlan(q,domain){
  const map={
    plants:{intent:"Analyze site / plant performance or capacity",datasets:["Plant Registry"],joins:[]},
    assets:{intent:"Analyze governed asset population",datasets:["Asset Register"],joins:[]},
    workorders:{intent:"Analyze maintenance work orders",datasets:["Work Orders"],joins:[]},
    spares:{intent:"Analyze spares and inventory",datasets:["Spare Parts / Inventory"],joins:[]},
    esg:{intent:"Analyze sustainability / ESG measures",datasets:["Sustainability Data"],joins:[]},
    crew:{intent:"Analyze crew, skills and resource data",datasets:["Crew Roster"],joins:[]},
    portfolio:{intent:"Analyze portfolio information",datasets:["AIP Portfolio Data"],joins:[]}
  };
  const base=map[domain]||map.portfolio;
  const filters=[];
  const grouping=[];
  const calculations=[];

  const win=gqParseWindow(q,[],[]);
  const n=aiTopN(q,null);
  if(/\bcritical\b/.test(q))filters.push("Critical only");
  if(/\bhigh[- ]risk|high risk\b/.test(q))filters.push("High-risk records only");
  if(/\boverdue\b/.test(q))filters.push("Overdue records only");
  if(/\bopen\b/.test(q))filters.push("Open status where applicable");
  if(/\bclosed\b/.test(q))filters.push("Closed status where applicable");
  if(/\bpreventive\b/.test(q))filters.push("Preventive maintenance");
  if(/\bcorrective\b/.test(q))filters.push("Corrective maintenance");
  if(/\bpredictive\b/.test(q))filters.push("Predictive maintenance");
  if(/\badaptive\b/.test(q))filters.push("Adaptive maintenance");
  if(/\blowest|bottom|least\b/.test(q))calculations.push("Sort ascending by requested metric");
  if(/\bhighest|top|best\b/.test(q))calculations.push("Sort descending by requested metric");
  if(Number.isFinite(n))filters.push(`Limit output to ${n} record(s)`);
  if(/\bby site|by plant\b/.test(q))grouping.push("Site / Plant");
  if(/\bby priority\b/.test(q))grouping.push("Priority");
  if(/\bby status\b/.test(q))grouping.push("Status");
  if(/\bby type\b/.test(q))grouping.push("Type");
  if(/\baverage|avg|mean\b/.test(q))calculations.push("Calculate arithmetic mean");
  if(/\bcount|how many|number of|total\b/.test(q))calculations.push("Count qualifying governed records");
  if(/\btrend|over time|monthly\b/.test(q))calculations.push("Order measures chronologically for trend analysis");
  if(!calculations.length)calculations.push("Apply requested selection, ordering and presentation logic");

  return {
    intent:base.intent,
    datasets:base.datasets,
    joins:base.joins,
    filters,
    grouping,
    calculations,
    validation:"Query executed only against fields available in the active governed AIP dataset.",
    status:"Executed"
  };
}
function gqAppendPlan(result,plan){
  if(!result)return result;
  if(!result.html)result.html="";
  if(!/class="gq-plan"/.test(result.html))result.html+=gqPlanBox(plan);
  result.queryPlan=plan;
  return result;
}

function gqCrewCertificationQuery(q){
  const isCrew=/\b(crew|crew members?|technicians?|people|staff)\b/.test(q);
  const isCert=/\b(certification|certifications|certified|certificate|certificates)\b/.test(q);
  const asksMissing=/\b(no|none|without|don'?t have|do not have|not have|missing|lack|lacking|uncertified|not certified)\b/.test(q);
  if(!(isCrew&&isCert&&asksMissing))return null;

  const rows=(CREW_ROSTER||[]).slice();
  const normalizeCert=v=>String(v??"").trim();
  const isMissingCert=v=>{
    const s=normalizeCert(v).toLowerCase();
    return !s || ["none","no","n/a","na","not certified","uncertified","missing","-","—"].includes(s);
  };

  const missing=rows.filter(c=>isMissingCert(gqValue(c,"certification","Certification","certificate","Certificate")));
  const table=missing.length?aiTable(
    ["Technician","Skill","Certification","Availability"],
    missing.map(c=>[
      gqValue(c,"name","Name","technician","Technician","id")||"—",
      gqValue(c,"skill","skills","Skill","Skills")||"—",
      normalizeCert(gqValue(c,"certification","Certification","certificate","Certificate"))||"None",
      gqValue(c,"availability","Availability","status","Status")||"—"
    ])
  ):"";

  const plan={
    intent:"Identify crew members who do not have a recorded certification",
    datasets:["Crew Roster"],
    joins:[],
    filters:["Certification is blank, None, N/A, Not Certified, Uncertified, Missing, or equivalent governed empty value"],
    grouping:[],
    calculations:[
      "Inspect the Certification field for every crew record",
      "Classify records with no valid certification as uncertified",
      "Count qualifying crew members",
      "Return the qualifying technicians with Skill, Certification and Availability"
    ],
    validation:`Checked ${rows.length} governed crew record${rows.length===1?"":"s"}; ${missing.length} record${missing.length===1?"":"s"} matched the no-certification condition.`,
    status:"Executed"
  };

  return {
    html:`<b>${missing.length?`Yes. ${missing.length} crew member${missing.length===1?"":"s"} do not have a recorded certification.`:`No. All ${rows.length} crew members have a recorded certification.`}</b>
      ${table}${gqPlanBox(plan)}`,
    chart:null,
    queryPlan:plan
  };
}
function gqUnsupportedComplexity(q){
  /* Detect conjunction-heavy questions spanning multiple governed domains that
     have no implemented safe join. We refuse rather than silently answer only one clause. */
  const domains=[];
  if(/\bassets?|oem|health score|risk band|inverter|transformer\b/.test(q))domains.push("assets");
  if(/\bwork orders?|maintenance order|corrective|preventive|predictive|adaptive\b/.test(q))domains.push("workorders");
  if(/\bspares?|inventory|reorder|stock|parts?\b/.test(q))domains.push("spares");
  if(/\bcrew|technician|skills?\b/.test(q))domains.push("crew");
  if(/\bsite|sites|plant|plants|capacity|performance ratio|availability\b/.test(q))domains.push("plants");
  const uniq=[...new Set(domains)];
  if(uniq.length<2 || !/\b(and|with|which|that|but|while)\b/.test(q))return null;

  /* Supported cross-domain families are handled before this check. */
  const plan={
    intent:"Multi-domain governed query",
    datasets:uniq.map(d=>({assets:"Asset Register",workorders:"Work Orders",spares:"Spare Parts / Inventory",crew:"Crew Roster",plants:"Plant Registry"}[d]||d)),
    joins:["Join requested but no governed join key is safely available for this query shape"],
    filters:[],
    grouping:[],
    calculations:[],
    validation:"AIP will not infer a join key or fabricate a cross-domain relationship.",
    status:"Limited by governed data model",
    note:"Refine the question to a supported relationship or add the required governed key mapping."
  };
  return {html:`<b>I can interpret this as a multi-dataset question, but I cannot execute it safely with the currently governed join map.</b>
    <div class="gq-warning">No result has been fabricated. The lineage below shows the datasets detected and the missing governed relationship.</div>${gqPlanBox(plan)}`,chart:null,queryPlan:plan};
}

/* v432 — Governed semantic/schema layer.
   Purpose: interpret requested concepts, validate them against active governed
   datasets/fields, and prevent irrelevant generic fallbacks. */
function gqObjectFields(rows){
  const set=new Set();
  (rows||[]).slice(0,200).forEach(r=>{
    if(r&&typeof r==="object")Object.keys(r).forEach(k=>set.add(k));
  });
  return [...set];
}
function gqNormKey(v){return String(v||"").toLowerCase().replace(/[^a-z0-9]+/g,"");}
function gqFindField(rows,candidates){
  const fields=gqObjectFields(rows);
  const normMap=new Map(fields.map(f=>[gqNormKey(f),f]));
  for(const c of (candidates||[])){
    const exact=normMap.get(gqNormKey(c));
    if(exact)return exact;
  }
  return null;
}
function gqCoverage(rows,field){
  if(!field)return {total:(rows||[]).length,populated:0,blank:(rows||[]).length,pct:0};
  const total=(rows||[]).length;
  const populated=(rows||[]).filter(r=>{
    const v=r? r[field] : null;
    return v!==undefined&&v!==null&&String(v).trim()!=="";
  }).length;
  return {total,populated,blank:total-populated,pct:total?Math.round(populated/total*1000)/10:0};
}
