function gqResolveDomain(q){
  const registry=gqDatasetRegistry();
  let best=null,bestScore=0;
  for(const [key,d] of Object.entries(registry)){
    let score=0;
    (d.aliases||[]).forEach(a=>{if(q.includes(a))score+=a.includes(" ")?3:2;});
    for(const [concept,aliases] of Object.entries(d.concepts||{})){
      (aliases||[]).forEach(a=>{if(q.includes(a))score+=a.includes(" ")?2:1;});
    }
    if(score>bestScore){best={key,...d};bestScore=score;}
  }
  return bestScore?best:null;
}
function gqRequestedConcepts(q,domain){
  const hits=[];
  if(!domain)return hits;
  for(const [concept,aliases] of Object.entries(domain.concepts||{})){
    if((aliases||[]).some(a=>q.includes(a)))hits.push({concept,aliases});
  }
  return hits;
}
function gqCandidateFieldsForConcept(concept){
  const map={
    name:["name","Name","technician","Technician"],
    skill:["skill","skills","Skill","Skills"],
    certification:["certification","Certification","certificate","Certificate"],
    certification_expiry:["certExpiry","certificationExpiry","Certification_Expiry","Certificate_Expiry"],
    availability:["availability","Availability","status","Status"],
    experience:["experience","Experience","yearsExperience","Years_Experience"],
    hourly_cost:["hourlyCost","Hourly_Cost","hourly_cost","rate"],
    region:["region","Region","state","State"],
    crew:["crew","Crew","team","Team"],
    asset_id:["id","Asset_ID","assetId","AssetId"],
    site:["plant","Plant_ID","plantId","site","Site_ID","siteId"],
    class:["cls","class","Asset_Class","type"],
    oem:["oem","OEM","manufacturer","Manufacturer"],
    model:["model","Model"],
    health:["healthScore","Health_Score","health","Health"],
    risk:["riskBand","Risk_Band","risk","Risk"],
    status:["status","Status"],
    install_year:["installYear","Install_Year","installationYear"],
    last_maintenance:["lastMaintenance","Last_Maintenance","maintenanceDate"],
    work_order_id:["id","WO_ID","Work_Order_ID","wo"],
    asset:["asset","Asset_ID","assetId","Asset"],
    type:["type","Type","WO_Type"],
    priority:["priority","Priority"],
    created:["created","Created_Date","createdDate","date"],
    sla:["slaHours","SLA_Hours","sla"],
    description:["desc","description","Description"],
    part:["part","sku","name","Part","SKU"],
    stock:["stock","quantity","qty","onHand"],
    reorder:["reorder","reorderLevel","reorderPoint"],
    lead_time:["leadTime","leadDays","Lead_Time"],
    supplier:["supplier","vendor","Supplier"],
    cost:["cost","unitCost","value","Unit_Cost"],
    site_id:["id","Site_ID","Plant_ID"],
    capacity:["mw","capacity","capacityMW","Capacity_MW"],
    pr:["pr","PR","performanceRatio","Performance_Ratio"]
  };
  return map[concept]||[concept];
}
function gqSchemaInspection(q){
  const domain=gqResolveDomain(q);
  if(!domain)return {domain:null,requested:[],resolved:[],missing:[]};
  const rows=domain.rows();
  const requested=gqRequestedConcepts(q,domain);
  const resolved=[],missing=[];
  requested.forEach(rc=>{
    const field=gqFindField(rows,gqCandidateFieldsForConcept(rc.concept));
    if(field){
      resolved.push({...rc,field,coverage:gqCoverage(rows,field)});
    }else{
      missing.push(rc);
    }
  });
  return {domain,rows,requested,resolved,missing};
}
function gqSchemaUnavailableResult(q,inspection){
  const d=inspection.domain;
  const missing=inspection.missing||[];
  if(!d||!missing.length)return null;
  const requestedNames=missing.map(x=>x.concept.replace(/_/g," "));
  const resolvedNames=(inspection.resolved||[]).map(x=>`${x.concept.replace(/_/g," ")} → ${x.field}`);
  const plan={
    intent:`Answer a natural-language question about ${d.label}`,
    datasets:[d.label],
    joins:[],
    filters:[],
    grouping:[],
    calculations:["Inspect requested concepts against the active governed schema before executing the query"],
    validation:`Requested field${missing.length===1?"":"s"} not found: ${requestedNames.join(", ")}.`,
    status:"Data not available",
    note:resolvedNames.length?`Other requested concepts were mapped: ${resolvedNames.join("; ")}.`:"No substitute field was used."
  };
  return {
    html:`<b>I cannot answer this reliably from the current governed data.</b>
      <div class="gq-warning">${gqEsc(d.label)} does not contain a governed field for <b>${gqEsc(requestedNames.join(", "))}</b>. I have not substituted a different field or returned a generic ${gqEsc(d.label.toLowerCase())} summary.</div>
      ${gqPlanBox(plan)}`,
    chart:null,
    queryPlan:plan
  };
}
function gqSchemaAwareSimpleQuery(q){
  const inspection=gqSchemaInspection(q);
  if(!inspection.domain)return null;
  if(inspection.missing.length)return gqSchemaUnavailableResult(q,inspection);

  const rows=(inspection.rows||[]).slice();
  const resolved=inspection.resolved||[];
  if(!resolved.length)return null;

  const asksMissing=/\b(without|missing|blank|empty|none|no\s+\w+|don'?t have|do not have|not have|lack|lacking)\b/.test(q);
  const asksCount=/\b(how many|count|number of|total|are there any|any)\b/.test(q);
  if(asksMissing){
    const target=resolved.find(r=>!["name","site","asset_id","work_order_id"].includes(r.concept))||resolved[0];
    const missingRows=rows.filter(r=>{
      const v=r[target.field];
      const s=String(v??"").trim().toLowerCase();
      return !s || ["none","no","n/a","na","missing","unknown","-","—"].includes(s);
    });
    const displayFields=[];
    const nameField=gqFindField(rows,gqCandidateFieldsForConcept(
      inspection.domain.key==="crew"?"name":
      inspection.domain.key==="assets"?"asset_id":
      inspection.domain.key==="workorders"?"work_order_id":
      inspection.domain.key==="plants"?"name":"part"
    ));
    if(nameField)displayFields.push(["Record",nameField]);
    const skillField=inspection.domain.key==="crew"?gqFindField(rows,gqCandidateFieldsForConcept("skill")):null;
    if(skillField)displayFields.push(["Skill",skillField]);
    displayFields.push([target.concept.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase()),target.field]);

    const table=missingRows.length?aiTable(
      displayFields.map(x=>x[0]),
      missingRows.slice(0,50).map(r=>displayFields.map(x=>String(r[x[1]]??"").trim()||"None"))
    ):"";
    const plan={
      intent:`Identify ${inspection.domain.label} records with missing ${target.concept.replace(/_/g," ")}`,
      datasets:[inspection.domain.label],
      joins:[],
      filters:[`${target.field} is blank / None / N/A / Missing or equivalent empty value`],
      grouping:[],
      calculations:[
        `Map natural-language concept “${target.concept.replace(/_/g," ")}” to governed field ${target.field}`,
        `Check all ${rows.length} records`,
        `Count records with no populated ${target.field}`
      ],
      validation:`${target.coverage.populated} of ${target.coverage.total} records have a populated ${target.field} value (${target.coverage.pct}% coverage).`,
      status:"Executed"
    };
    const lead=asksCount
      ? `${missingRows.length} record${missingRows.length===1?"":"s"} have no recorded ${target.concept.replace(/_/g," ")}.`
      : `${missingRows.length?`Yes. ${missingRows.length}`:`No`} ${missingRows.length===1?"record has":"records have"} no recorded ${target.concept.replace(/_/g," ")}.`;
    return {html:`<b>${gqEsc(lead)}</b>${table}${gqPlanBox(plan)}`,chart:null,queryPlan:plan};
  }

  return null;
}
function gqSchemaGuard(q){
  const inspection=gqSchemaInspection(q);
  if(!inspection.domain)return null;
  if(inspection.missing.length)return gqSchemaUnavailableResult(q,inspection);
  return null;
}
function governedComplexQuery(qRaw){
  const q=aiNormalize(qRaw);
  if(!q)return null;
  try{
    return gqSchemaAwareSimpleQuery(q) || gqFailureQuery(q) || gqSiteCapacityAssetCountQuery(q) || gqCrewCertificationQuery(q) || gqUnsupportedComplexity(q) || gqSchemaGuard(q) || null;
  }catch(e){
    console.warn("Governed complex query failed",e);
    return {html:`<b>Unable to execute the governed query.</b><div class="gq-warning">${gqEsc(e.message||String(e))}</div>`,chart:null};
  }
}

function genericOfflineAnalysis(qRaw){
  const q=aiNormalize(qRaw);
  if(!q) return null;

  const governed=governedComplexQuery(qRaw);
  if(governed)return governed;

  if(/\b(summarize|summary|executive overview|management summary|what should management|top actions)\b/.test(q)){
    return gqAppendPlan(aiExecutiveSummary(),{
      intent:"Generate governed portfolio summary / management view",
      datasets:["Portfolio KPI Data","Plant Registry","Work Orders","Asset Register"],
      joins:["Portfolio aggregation by governed site / asset context where available"],
      filters:[],grouping:["Portfolio"],
      calculations:["Aggregate governed portfolio measures","Rank material management signals"],
      validation:"Summary uses only the AIP datasets available in the active mode.",
      status:"Executed"
    });
  }

  const domain=aiDetectDomain(q);
  const plan=gqDomainPlan(q,domain);

  /* Only permit generic domain responses for clear supported query shapes.
     Unknown requested concepts must never collapse into a generic summary. */
  const supportedShape=
    /\b(show|list|compare|rank|ranking|top|bottom|lowest|highest|average|avg|mean|count|how many|number of|total|distribution|trend|summary|summarize)\b/.test(q) ||
    /\b(by site|by plant|by priority|by status|by type|overdue|critical|high risk|low health|reorder|inventory value)\b/.test(q);

  if(!supportedShape){
    const inspection=gqSchemaInspection(q);
    if(inspection.domain){
      const requested=(inspection.requested||[]).map(x=>x.concept.replace(/_/g," "));
      const planUnknown={
        intent:`Interpret question about ${inspection.domain.label}`,
        datasets:[inspection.domain.label],
        joins:[],filters:[],grouping:[],calculations:[],
        validation:requested.length
          ? `Recognized requested concept(s): ${requested.join(", ")}, but no governed query operator was confidently identified.`
          : "No governed metric/filter/operator could be identified with sufficient confidence.",
        status:"Query not understood safely",
        note:"No generic domain answer was substituted."
      };
      return {html:`<b>I understood the subject area, but not the exact governed operation you want me to perform.</b>
        <div class="gq-warning">I have not returned a generic ${gqEsc(inspection.domain.label.toLowerCase())} summary because that could be misleading. Please phrase the request as a count, list, comparison, threshold, missing-data check, ranking, or time-window condition.</div>
        ${gqPlanBox(planUnknown)}`,chart:null,queryPlan:planUnknown};
    }
  }

  try{
    if(domain==="plants") return gqAppendPlan(aiPlantRows(q),plan);
    if(domain==="workorders") return gqAppendPlan(aiWorkOrderRows(q),plan);
    if(domain==="spares") return gqAppendPlan(aiSparesRows(q),plan);
    if(domain==="assets") return gqAppendPlan(aiAssetRows(q),plan);
    if(domain==="esg") return gqAppendPlan(aiESGRows(q),plan);
    if(domain==="crew"){
      const rows=(CREW_ROSTER||[]).slice();
      const avg=rows.reduce((s,c)=>s+Number(c.hourlyCost||0),0)/(rows.length||1);
      return gqAppendPlan({html:`There are <b>${rows.length}</b> technicians. Average hourly cost is <b>₹${aiNum(avg)}</b>.${aiTable(["Technician","Skill","Certification","Availability","Hourly Cost"],rows.slice(0,10).map(c=>[c.name||c.id,c.skill||c.skills||"–",c.certification||"None",c.availability||c.status||"–",Number(c.hourlyCost||0)]))}${aiSourceTag("Crew Roster")}`,chart:null},plan);
    }
  }catch(e){console.warn("Generic analysis failed",e);}
  return null;
}

function offlineAnswer(q){
  const generic=genericOfflineAnalysis(q);
  if(generic){
    const rawText=generic.html.replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim();
    return {html:generic.html,chart:generic.chart||null,rawText};
  }

  const nq=aiNormalize(q);
  const semanticDomain=gqResolveDomain(nq);
  if(semanticDomain){
    const plan={
      intent:`Interpret question about ${semanticDomain.label}`,
      datasets:[semanticDomain.label],
      joins:[],filters:[],grouping:[],calculations:[],
      validation:"A governed answer could not be produced with sufficient confidence from the available schema and supported operators.",
      status:"Unable to answer safely",
      note:"No generic or legacy substitute answer was used."
    };
    const html=`<b>I cannot answer that reliably from the current governed data and query rules.</b>
      <div class="gq-warning">I recognized the question as relating to ${gqEsc(semanticDomain.label)}, but I could not map the requested condition or calculation with sufficient confidence. I have therefore not returned an unrelated ${gqEsc(semanticDomain.label.toLowerCase())} summary.</div>${gqPlanBox(plan)}`;
    return {html,chart:null,rawText:html.replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim(),queryPlan:plan};
  }

  const legacyHtml=answerDataQuestion(q);
  const legacyChart=offlineChartForQuery(q);
  const fallbackPlan={
    intent:"Legacy governed query interpretation",
    datasets:["Active AIP governed data"],
    joins:[],filters:[],grouping:[],
    calculations:["Execute existing governed AIP query rule"],
    validation:"This question did not map to a governed semantic domain and was handled by the existing local rule library.",
    status:"Executed"
  };
  const htmlWithPlan=/class="gq-plan"/.test(legacyHtml)?legacyHtml:(legacyHtml+gqPlanBox(fallbackPlan));
  return {html:htmlWithPlan,chart:legacyChart,rawText:legacyHtml.replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim(),queryPlan:fallbackPlan};
}

async function dxAsk(q){
  DX_HISTORY.push({role:"user", rawText:q, html:q.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"), chart:null});
  const pendingIdx = DX_HISTORY.push({role:"bot", rawText:"", html:`<span class="dx-typing">${window.OA_MODE==="offline"?"Analyzing local data":"Thinking"}…</span>`, pending:true, chart:null}) - 1;
  renderDataExplorer();
  if(window.OA_MODE==="offline"){
    await new Promise(r=>setTimeout(r,180));
    const result=offlineAnswer(q);
    const chartId=result.chart?`dxChart${DX_CHART_SEQ++}`:null;
    DX_HISTORY[pendingIdx]={role:"bot",rawText:result.rawText,html:result.html,pending:false,chart:result.chart,chartId};
    renderDataExplorer();
    return;
  }
  try{
    const apiMessages = DX_HISTORY.filter(m=>!m.pending).map(m=>({role:m.role==="user"?"user":"assistant", content:m.rawText}));
    const raw = await callAssistantAPI(apiMessages);
    const { text, chart } = dxExtractChart(raw);
    const chartId = chart ? `dxChart${DX_CHART_SEQ++}` : null;
    DX_HISTORY[pendingIdx] = { role:"bot", rawText: raw, html: dxMdToHtml(text), pending:false, chart, chartId };
  }catch(err){
    DX_HISTORY[pendingIdx] = { role:"bot", rawText: String(err.message||err), html: `<b>Online connection unavailable.</b><br>${String(err.message||err).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}<br><br>Switch to <b>Offline NLP</b> or open <b>Connection</b> and verify the endpoint.`, pending:false, chart:null, error:true };
  }
  renderDataExplorer();
}
function dxSubmit(){
  const inp = document.getElementById("dxInput");
  if(!inp) return;
  const q = inp.value.trim();
  if(!q) return;
  inp.value = "";
  dxAsk(q);
}
function dxClear(){DX_HISTORY=[];renderDataExplorer();}
window.OA_CONNECTION=window.OA_CONNECTION||{state:"disconnected",message:"Endpoint not verified",endpoint:""};
function oaSetConnection(state,message,endpoint){
  window.OA_CONNECTION={state,message,endpoint:endpoint||window.OA_CONNECTION.endpoint||""};
  const st=document.getElementById("oaStatus");
  if(st){st.className="oa-status "+(state==="connected"?"connected":state==="testing"?"testing":state==="error"?"err":"");st.innerHTML=`<i></i> ${state==="connected"?"Connected":state==="testing"?"Testing…":state==="error"?"Connection failed":"Not connected"}`;st.title=message||"";}
  const send=document.getElementById("oaSendBtn");
  if(send)send.disabled=(window.OA_MODE==="online"&&state!=="connected");
  const r=document.getElementById("oaTestResult");
  if(r){r.className="oa-test-result "+(state==="connected"?"ok":state==="error"?"err":"");r.textContent=message||"";}
}
function oaToggleConfig(){const x=document.getElementById("oaConfig");if(x)x.classList.toggle("open")}
async function oaTestConnection(save){
  const i=document.getElementById("oaEndpoint");
  const endpoint=(i?i.value.trim():localStorage.getItem("eam_ai_assistant_endpoint"))||"/api/assistant";
  if(save)localStorage.setItem("eam_ai_assistant_endpoint",endpoint);
  oaSetConnection("testing","Contacting "+endpoint,endpoint);
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);
  try{
    const response=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({health_check:true,max_tokens:24,system:"Return only OK.",messages:[{role:"user",content:"Connection test"}]}),signal:controller.signal});
    clearTimeout(timer);if(!response.ok)throw new Error("HTTP "+response.status);
    const data=await response.json();
    if(!(typeof data.reply==="string"||typeof data.message==="string"||Array.isArray(data.content)||data.ok===true||data.status==="ok"))throw new Error("Unrecognized JSON response schema");
    oaSetConnection("connected","Verified: "+endpoint,endpoint);showToast("Connection verified","Online AI is ready.");return true;
  }catch(err){
    clearTimeout(timer);const msg=err.name==="AbortError"?"Connection timed out after 12 seconds":String(err.message||err);
    oaSetConnection("error",msg,endpoint);showToast("Connection failed",msg);return false;
  }
}
async function oaSaveEndpoint(){const i=document.getElementById("oaEndpoint");if(!i)return;const endpoint=i.value.trim()||"/api/assistant";localStorage.setItem("eam_ai_assistant_endpoint",endpoint);await oaTestConnection(false)}
window.OA_FILES=window.OA_FILES||[];
function oaPickFiles(input){Array.from(input.files||[]).forEach(f=>window.OA_FILES.push(f));renderDataExplorer()}
function oaRemoveFile(i){window.OA_FILES.splice(i,1);renderDataExplorer()}
function oaStopVoice(silent=true){
  window.OA_VOICE_ACTIVE=false;
  if(window.OA_RECOGNITION){
    try{window.OA_RECOGNITION.stop()}catch(e){}
    window.OA_RECOGNITION=null;
  }
  const b=document.getElementById("oaVoiceBtn");
  if(b){b.classList.remove("listening");b.setAttribute("aria-pressed","false");}
  if(typeof oaVoiceStatus==="function")oaVoiceStatus("");
  if(!silent)showToast("Voice input stopped","Review the question, then press ↑ to ask.");
}
function oaStopCurrent(){
  /* Stop only the current active operation. Do not clear the typed prompt,
     prior messages, results or attachments. */
  if(window.OA_RECOGNITION||window.OA_VOICE_ACTIVE){
    oaStopVoice(true);
    const t=document.getElementById("oaInput");
    if(t){t.focus();try{t.setSelectionRange(t.value.length,t.value.length)}catch(_){}}
    oaVoiceStatus("Stopped.",false);
    return;
  }

  const pending=DX_HISTORY.findIndex(m=>m&&m.pending);
  if(pending>=0){
    DX_HISTORY.splice(pending,1);
    renderDataExplorer();
    showToast("Stopped","Current Assistant activity stopped.");
    return;
  }

  showToast("Nothing running","There is no active Assistant operation to stop.");
}
function oaResetStudio(){
  oaStopVoice(true);
  DX_HISTORY=[];
  window.OA_FILES=[];
  const t=document.getElementById("oaInput");if(t)t.value="";
  renderDataExplorer();
}
function oaDismissMessage(i){
  if(i<0||i>=DX_HISTORY.length)return;
  /* Keep conversation coherent: when a bot response is dismissed, also dismiss
     its immediately preceding user question. When a user question is dismissed,
     remove its immediately following bot answer. */
  let start=i,count=1;
  if(DX_HISTORY[i]?.role==="bot"&&i>0&&DX_HISTORY[i-1]?.role==="user"){start=i-1;count=2;}
  else if(DX_HISTORY[i]?.role==="user"&&DX_HISTORY[i+1]?.role==="bot"){count=2;}
  DX_HISTORY.splice(start,count);
  renderDataExplorer();
}
function oaNewChat(){oaResetStudio()}
function oaUseSuggestion(q){const t=document.getElementById("oaInput");if(t){t.value=q;t.focus();}}
