function rememberDatabaseReturnState(){
  try{
    const state=captureDatasetViewState();
    if(state && state.view && state.view!=='datamanagement'){
      const payload=JSON.stringify(state);
      sessionStorage.setItem('aip_database_return_state',payload);
      localStorage.setItem('aip_database_return_state',payload);
      window.__aipDatabaseReturnState=state;
    }
  }catch(e){ console.warn('Unable to remember database return state',e); }
}
function resolveDatabaseSourceExitState(currentState){
  if(!currentState || currentState.view!=='datamanagement') return currentState;
  try{
    const direct=window.__aipDatabaseReturnState;
    const raw=sessionStorage.getItem('aip_database_return_state') || localStorage.getItem('aip_database_return_state');
    const saved=direct || (raw ? JSON.parse(raw) : null);
    if(saved && saved.view && saved.view!=='datamanagement') return saved;
  }catch(e){ console.warn('Unable to resolve database return state',e); }
  return currentState;
}
function clearDatabaseReturnState(){
  try{
    delete window.__aipDatabaseReturnState;
    sessionStorage.removeItem('aip_database_return_state');
    localStorage.removeItem('aip_database_return_state');
  }catch(e){}
}
