/* ============================================================
   V2 ADDITIVE EXECUTIVE INTELLIGENCE
   Existing views and data engines remain unchanged.
   ============================================================ */
function v2Rows(name){
  const mode=String(typeof APM_DATA_MODE!=='undefined'?APM_DATA_MODE:'').toLowerCase();
  if(mode==='demo data'&&AIP_INDEPENDENT_SYNTHETIC_DATA&&Array.isArray(AIP_INDEPENDENT_SYNTHETIC_DATA[name])&&AIP_INDEPENDENT_SYNTHETIC_DATA[name].length)return AIP_INDEPENDENT_SYNTHETIC_DATA[name];
  return (APM_IMPORTED_DATA&&APM_IMPORTED_DATA[name]&&APM_IMPORTED_DATA[name].length)?APM_IMPORTED_DATA[name]:null;
}
function v2Money(v){return fmtINR(Number(v)||0)}
function v2MoneyWhole(v){return "₹"+Math.round(Number(v)||0).toLocaleString("en-IN")}
function v2Num(v,d=1){return (Number(v)||0).toLocaleString("en-IN",{minimumFractionDigits:d,maximumFractionDigits:d})}
function v2Head(title,sub,view){return `<div class="page-head"><div><h1>${title}</h1></div></div>`}
function v2SyntheticExecutive(){
  const latestByPlant=new Map();
  ESG_MONTHLY.forEach(r=>{const old=latestByPlant.get(r.plant);if(!old||String(r.month)>String(old.month))latestByPlant.set(r.plant,r)});
  return PLANTS.map((p,i)=>{
    const e=latestByPlant.get(p.id)||{};
    const actual=Number(e.generation)||Math.round(p.mw*122);
    const expected=Number(e.expected)||actual/(1-((100-p.pr)/100)*.55);
    const budget=expected*1.012, tariff=2.65+(i%6)*.13;
    const rec=Math.max(0,expected-actual)*.68;
    return {Plant_ID:p.id,Plant_Name:p.name,Capacity_MW:p.mw,Actual_Generation_MWh:actual,Budget_Generation_MWh:budget,
      Generation_Variance_MWh:actual-budget,Generation_Variance_Pct:(actual-budget)/budget*100,PR_Actual_Pct:p.pr,PR_Target_Pct:95,
      Availability_Actual_Pct:p.availability,Availability_Target_Pct:98,PPA_Tariff_INR_kWh:tariff,
      Revenue_Actual_INR:actual*1000*tariff,Revenue_Budget_INR:budget*1000*tariff,
      Revenue_Variance_INR:(actual-budget)*1000*tariff,Recoverable_Generation_MWh:rec,Recoverable_Revenue_INR:rec*1000*tariff,
      Executive_Status:(actual-budget)/budget<-.06?"Critical":((actual-budget)/budget<-.03?"Watch":"On Track"),
      Required_Action:(actual-budget)/budget<-.06?"Approve priority intervention":((actual-budget)/budget<-.03?"Review loss drivers":"Monitor"),
      Action_Owner:"Head – Asset Management"}
  })
}
function v2ExecData(){return v2Rows("Executive Portfolio Summary")||v2SyntheticExecutive()}
function renderExecutivePerformance(){
  const a=v2ExecData(), actual=a.reduce((s,r)=>s+(Number(r.Actual_Generation_MWh)||0),0), budget=a.reduce((s,r)=>s+(Number(r.Budget_Generation_MWh)||0),0);
  const rev=a.reduce((s,r)=>s+(Number(r.Revenue_Actual_INR)||0),0), revb=a.reduce((s,r)=>s+(Number(r.Revenue_Budget_INR)||0),0);
  const rec=a.reduce((s,r)=>s+(Number(r.Recoverable_Generation_MWh)||0),0), recr=a.reduce((s,r)=>s+(Number(r.Recoverable_Revenue_INR)||0),0);
  const critical=a.filter(r=>String(r.Executive_Status).toLowerCase()==="critical").length;
  document.getElementById("view-executiveperformance").innerHTML=v2Head("Executive Performance","Generation, revenue, recovery potential and decisions across the solar portfolio.","executiveperformance")+`
  <div class="grid g6" style="margin-bottom:16px">
    <div class="card"><div class="kpi-label">Actual generation</div><div class="kpi-value">${v2Num(actual,0)}<span class="kpi-unit">MWh</span></div></div>
    <div class="card"><div class="kpi-label">Generation vs budget</div><div class="kpi-value">${v2Num((actual-budget)/budget*100,1)}<span class="kpi-unit">%</span></div></div>
    <div class="card executive-revenue-kpi"><div class="kpi-label">Revenue vs budget</div><div class="kpi-value executive-money-value">${v2MoneyWhole(rev-revb)}</div></div>
    <div class="card"><div class="kpi-label">Recoverable generation</div><div class="kpi-value">${v2Num(rec,0)}<span class="kpi-unit">MWh</span></div></div>
    <div class="card"><div class="kpi-label">Recoverable revenue opportunity</div><div class="kpi-value">${v2Money(recr)}</div></div>
    <div class="card"><div class="kpi-label">Critical sites</div><div class="kpi-value">${critical}</div></div>
  </div>
  <div class="card"><div class="panel-title"><div><h3>Executive site summary</h3><div class="sub">Uploaded V2 worksheet when available; otherwise generated from the same synthetic data engine.</div></div></div><table class="executive-site-summary-table"><thead><tr><th>Site</th><th>Generation vs budget</th><th>Revenue variance</th><th>PR</th><th>Availability</th><th>Recoverable value</th><th>Status</th><th class="exec-required-action-head">Required action</th></tr></thead><tbody>
  ${a.sort((x,y)=>(Number(x.Generation_Variance_Pct)||0)-(Number(y.Generation_Variance_Pct)||0)).map(r=>`<tr><td><b>${r.Plant_ID}</b> · ${r.Plant_Name||""}</td><td>${v2Num(r.Generation_Variance_Pct,1)}%</td><td>${v2Money(r.Revenue_Variance_INR)}</td><td>${v2Num(r.PR_Actual_Pct,1)}%</td><td>${v2Num(r.Availability_Actual_Pct,1)}%</td><td>${v2Money(r.Recoverable_Revenue_INR)}</td><td>${statusTag(r.Executive_Status||"Watch")}</td><td class="exec-required-action-cell">${r.Required_Action||"Review"}</td></tr>`).join("")}
  </tbody></table></div>`
}
function v2LossData(){
  const rows=v2Rows("Generation Loss Attribution");if(rows)return rows;
  return v2ExecData().map((r,i)=>{const loss=Math.max(0,(Number(r.Budget_Generation_MWh)||0)-(Number(r.Actual_Generation_MWh)||0));return {
    Plant_ID:r.Plant_ID,Theoretical_Generation_MWh:Number(r.Budget_Generation_MWh)*1.03,Weather_Adjusted_Expected_MWh:Number(r.Budget_Generation_MWh),
    Actual_Generation_MWh:Number(r.Actual_Generation_MWh),Inverter_Loss_MWh:loss*.23,Soiling_Loss_MWh:loss*.17,Module_Degradation_Loss_MWh:loss*.12,
    Tracker_Loss_MWh:loss*.08,DC_String_Loss_MWh:loss*.07,Transformer_Loss_MWh:loss*.06,Grid_Outage_Loss_MWh:loss*.12,
    Curtailment_Loss_MWh:loss*.08,Planned_Maintenance_Loss_MWh:loss*.04,Unexplained_Loss_MWh:loss*.03,Total_Loss_MWh:loss,Recoverable_Loss_MWh:loss*.65}})
}
function renderLossIntelligence(){
  const pc=window.AIPPortfolioContext?.get?.()||{};
  const scoped=!!pc.plantId;
  const rows=window.AIPPortfolioContext?.viewRows(v2LossData())||v2LossData(), ex=rows.reduce((s,r)=>s+(Number(r.Weather_Adjusted_Expected_MWh)||0),0), ac=rows.reduce((s,r)=>s+(Number(r.Actual_Generation_MWh)||0),0);
  const fields=[["Inverter","Inverter_Loss_MWh"],["Soiling","Soiling_Loss_MWh"],["Module degradation","Module_Degradation_Loss_MWh"],["Tracker","Tracker_Loss_MWh"],["DC strings","DC_String_Loss_MWh"],["Transformer","Transformer_Loss_MWh"],["Grid outage","Grid_Outage_Loss_MWh"],["Curtailment","Curtailment_Loss_MWh"],["Planned maintenance","Planned_Maintenance_Loss_MWh"],["Unexplained","Unexplained_Loss_MWh"]];
  const totals=fields.map(([n,f])=>[n,rows.reduce((s,r)=>s+(Number(r[f])||0),0)]).sort((a,b)=>b[1]-a[1]);
  const siteName=String(pc.plantName||pc.plantId||'').trim();
  const title=scoped?`Generation & Revenue Loss Intelligence · ${siteName}`:"Generation & Revenue Loss Intelligence";
  const subtitle=scoped?`${pc.plantId} · Site-filtered expected-to-actual generation and loss attribution.`:"Expected-to-actual generation bridge with controllable and external loss attribution.";
  const bridgeTitle=scoped?`${siteName} loss bridge`:'Portfolio loss bridge';
  const rightTitle=scoped?'Selected site loss profile':'Site loss ranking';
  document.getElementById("view-lossintelligence").innerHTML=v2Head(title,subtitle,"lossintelligence")+`
  ${portfolioKpis([["Expected generation",`${v2Num(ex,0)} MWh`],["Actual generation",`${v2Num(ac,0)} MWh`],["Total loss",`${v2Num(ex-ac,0)} MWh`],["Attainment",`${v2Num(ex?ac/ex*100:0,1)}%`]])}
  <div class="grid g2"><div class="card"><div class="panel-title"><div><h3>${bridgeTitle}</h3><div class="sub">Ranked by energy impact</div></div></div><table class="loss-intelligence-table"><thead><tr><th>Loss driver</th><th>Loss</th><th>Share</th></tr></thead><tbody>${totals.map(x=>`<tr><td>${x[0]}</td><td>${v2Num(x[1],1)} MWh</td><td>${v2Num(x[1]/Math.max(1,ex-ac)*100,1)}%</td></tr>`).join("")}</tbody></table></div>
  <div class="card"><div class="panel-title" style="align-items:flex-end;gap:12px;flex-wrap:wrap"><div><h3>${rightTitle}</h3><div class="sub">Recoverable loss is prioritised for maintenance action</div></div><div style="margin-left:auto;min-width:260px;max-width:340px;flex:1 1 280px"><input id="site-loss-ranking-search" type="search" placeholder="Search site loss ranking…" aria-label="Search Site Loss Ranking across all columns" oninput="filterSiteLossRanking(this.value)" style="width:100%;height:36px;border:1px solid #cbd5e1;border-radius:8px;padding:0 11px;font:14px Arial,sans-serif;background:#fff;color:#0f172a;outline:none"></div></div><table class="loss-intelligence-table" id="site-loss-ranking-table"><thead><tr><th>Plant</th><th>Total loss</th><th>Recoverable</th><th>External loss</th></tr></thead><tbody>${rows.sort((a,b)=>(Number(b.Total_Loss_MWh)||0)-(Number(a.Total_Loss_MWh)||0)).map(r=>{const p=(typeof PLANTS!=='undefined'?PLANTS.find(x=>String(x.id)===String(r.Plant_ID)):null);const label=p?`${r.Plant_ID} · ${p.name}`:r.Plant_ID;const lossRecord=String(r.Loss_Record_ID||r.Loss_ID||r.id||'');return `<tr data-loss-record="${lossRecord}"><td><b>${label}</b>${lossRecord?`<div class="v560-loss-record-id">${lossRecord}</div>`:''}</td><td>${v2Num(r.Total_Loss_MWh,1)} MWh</td><td>${v2Num(r.Recoverable_Loss_MWh,1)} MWh</td><td>${v2Num((Number(r.Grid_Outage_Loss_MWh)||0)+(Number(r.Curtailment_Loss_MWh)||0),1)} MWh</td></tr>`}).join("")}</tbody></table></div></div>`
}

function filterSiteLossRanking(value){
  const q=String(value||'').trim().toLowerCase();
  const table=document.getElementById('site-loss-ranking-table');
  if(!table)return;
  table.querySelectorAll('tbody tr').forEach(tr=>{
    const text=Array.from(tr.cells).slice(0,4).map(td=>td.textContent||'').join(' ').toLowerCase();
    tr.style.display=!q||text.includes(q)?'':'none';
  });
}


function portfolioPerformanceHead(){
  return `<div class="f1-help-top-right"></div><div class="page-head"><div><h1>Portfolio Performance</h1></div></div>`;
}
function portfolioKpiEsc(v){return String(v??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]||c));}
function portfolioKpiDisplay(value){
  const raw=String(value??'').trim();
  const m=raw.match(/^([₹$€£]?)([-+]?\d[\d,]*(?:\.\d+)?)(.*)$/);
  if(!m)return `<span class="aip-kpi-number">${portfolioKpiEsc(raw)}</span>`;
  return `${m[1]?`<span class="aip-kpi-prefix">${portfolioKpiEsc(m[1])}</span>`:''}<span class="aip-kpi-number">${portfolioKpiEsc(m[2])}</span>${m[3].trim()?`<span class="aip-kpi-unit">${portfolioKpiEsc(m[3].trim())}</span>`:''}`;
}
function portfolioKpiBars(){return '<span class="aip-kpi-master-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span>';}
function portfolioKpis(items){
  /* Render the authoritative universal KPI structure immediately.  The hidden source
     label/value are retained so AIPKPIMaster can safely re-scan without replacing or
     de-normalizing the card.  There is no legacy ax-kpi/rigour-kpi first frame. */
  return `<div class="ax-kpis portfolio-kpis" style="--pp-cols:${Math.max(1,Math.min(6,items.length))}">${items.map((x,i)=>{
    const label=String(x[0]??''),value=String(x[1]??'');
    return `<div class="aip-kpi-master" data-aip-kpi-index="${i%8}"><span class="kpi-label" data-kpi-label>${portfolioKpiEsc(label)}</span><b class="kpi-value" data-kpi-value>${portfolioKpiEsc(value)}</b><span class="aip-kpi-display-label">${portfolioKpiEsc(label)}</span><span class="aip-kpi-display-value">${portfolioKpiDisplay(value)}</span>${portfolioKpiBars()}</div>`;
  }).join('')}</div>`;
}
var PORTFOLIO_PERFORMANCE_TAB = window.PORTFOLIO_PERFORMANCE_TAB || 'performance';
function portfolioPerformanceTabs(active){
  return `<div class="portfolio-performance-tabs" role="tablist" aria-label="Portfolio Performance views">
    <button data-pp-tab="performance" class="${active==='performance'?'active':''}" onclick="setPortfolioPerformanceTab('performance')">Performance</button>
    <button data-pp-tab="benchmarking" class="${active==='benchmarking'?'active':''}" onclick="setPortfolioPerformanceTab('benchmarking')">Site Benchmarking</button>
    <button data-pp-tab="loss" class="${active==='loss'?'active':''}" onclick="setPortfolioPerformanceTab('loss')">Loss &amp; Recovery</button>
  </div>`;
}
function setPortfolioPerformanceTab(tab){
  PORTFOLIO_PERFORMANCE_TAB=tab;window.PORTFOLIO_PERFORMANCE_TAB=tab;renderPortfolioBenchmarking();
  document.getElementById('main')?.scrollTo(0,0);
}
function renderPortfolioPerformanceTab(){
  const host=document.getElementById('view-portfoliobenchmarking'); if(!host)return;
  const a=v2ExecData(), actual=a.reduce((s,r)=>s+(Number(r.Actual_Generation_MWh)||0),0), budget=a.reduce((s,r)=>s+(Number(r.Budget_Generation_MWh)||0),0);
  const rev=a.reduce((s,r)=>s+(Number(r.Revenue_Actual_INR)||0),0), revb=a.reduce((s,r)=>s+(Number(r.Revenue_Budget_INR)||0),0);
  const rec=a.reduce((s,r)=>s+(Number(r.Recoverable_Generation_MWh)||0),0), recr=a.reduce((s,r)=>s+(Number(r.Recoverable_Revenue_INR)||0),0);
  const av=a.length?a.reduce((s,r)=>s+(Number(r.Availability_Actual_Pct)||0),0)/a.length:0;
  const ranked=[...a].sort((x,y)=>{
    const xv=Number(x.Generation_Variance_Pct)||0,yv=Number(y.Generation_Variance_Pct)||0;
    if(xv!==yv)return xv-yv;
    return (Number(y.Recoverable_Revenue_INR)||0)-(Number(x.Recoverable_Revenue_INR)||0);
  });
  host.innerHTML=portfolioPerformanceHead()+portfolioPerformanceTabs('performance')+aipRecoveryScopeHtml(rows)+portfolioKpis([
    ['Actual generation',`${v2Num(actual,0)} MWh`,Math.min(100,budget?actual/budget*100:0)],
    ['Generation vs budget',`${v2Num(budget?(actual-budget)/budget*100:0,1)}%`,Math.min(100,Math.max(18,50+(budget?(actual-budget)/budget*250:0)))],
    ['Revenue vs budget',v2MoneyWhole(rev-revb),Math.min(100,Math.max(18,50+(revb?(rev-revb)/revb*250:0)))],
    ['Availability',`${v2Num(av,1)}%`,av]
  ])+`
  <div class="card site-performance-league-card"><div class="panel-title"><div><h3>Site Performance Ranking</h3><div class="v230-ranking-basis">Ranked by Generation Variance vs Budget</div><div class="sub">Single authoritative management ranking · performance, value leakage, exception status and required action in one register.</div></div></div><div class="table-scroll"><table class="site-performance-league-table"><thead><tr><th>Site</th><th>Capacity</th><th>Generation variance</th><th>Revenue variance</th><th>PR</th><th>Availability</th><th>Recoverable generation</th><th>Recoverable revenue opportunity</th><th>Status</th><th>Required action</th><th>Owner</th></tr></thead><tbody>${ranked.map((r,i)=>`<tr><td>${typeof portfolioSiteCode==='function'?portfolioSiteCode(r.Plant_ID,r.Plant_Name||''):r.Plant_ID} · ${r.Plant_Name||''}</td><td>${v2Num(r.Capacity_MW,0)} MW</td><td>${v2Num(r.Generation_Variance_Pct,1)}%</td><td>${v2Money(r.Revenue_Variance_INR)}</td><td>${v2Num(r.PR_Actual_Pct,1)}%</td><td>${v2Num(r.Availability_Actual_Pct,1)}%</td><td>${v2Num(r.Recoverable_Generation_MWh,1)} MWh</td><td>${v2Money(r.Recoverable_Revenue_INR)}</td><td>${statusTag(r.Executive_Status||'Watch')}</td><td>${r.Required_Action||'Review'}</td><td>${r.Action_Owner||'Plant Head'}</td></tr>`).join('')}</tbody></table></div></div>`;
}

function aipRecoveryPeriodScope(rows){
  const vals=(Array.isArray(rows)?rows:[]).map(r=>String(r?.Month||r?.Date||'').slice(0,10)).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x));
  if(!vals.length)return 'Active reporting period · accumulated';
  const months=[...new Set(vals.map(x=>x.slice(0,7)))].sort();
  const fmt=ym=>{const [y,m]=ym.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('en-GB',{month:'short',year:'numeric'})};
  const label=months.length===1?fmt(months[0]):`${fmt(months[0])}–${fmt(months[months.length-1])}`;
  return `${label} · accumulated`;
}
function aipRecoveryScopeHtml(rows){
  return `<div class="aip317-period-scope"><span>Reporting period</span><b>${aipRecoveryPeriodScope(rows)}</b></div>`;
}
function renderLossRecoveryTab(){
  const host=document.getElementById('view-portfoliobenchmarking'); if(!host)return;
  const rows=window.AIPPortfolioContext?.viewRows(v2LossData())||v2LossData();
  const fields=[['Inverter','Inverter_Loss_MWh'],['Soiling','Soiling_Loss_MWh'],['Module degradation','Module_Degradation_Loss_MWh'],['Tracker','Tracker_Loss_MWh'],['DC strings','DC_String_Loss_MWh'],['Transformer','Transformer_Loss_MWh'],['Grid outage','Grid_Outage_Loss_MWh'],['Curtailment','Curtailment_Loss_MWh'],['Planned maintenance','Planned_Maintenance_Loss_MWh'],['Unexplained','Unexplained_Loss_MWh']];
  const total=rows.reduce((s,r)=>s+(Number(r.Total_Loss_MWh)||0),0), recoverable=rows.reduce((s,r)=>s+(Number(r.Recoverable_Loss_MWh)||0),0);
  const external=rows.reduce((s,r)=>s+(Number(r.Grid_Outage_Loss_MWh)||0)+(Number(r.Curtailment_Loss_MWh)||0),0), unexplained=rows.reduce((s,r)=>s+(Number(r.Unexplained_Loss_MWh)||0),0);
  const exec=v2ExecData(), tariffByPlant=new Map(exec.map(r=>[String(r.Plant_ID),Number(r.PPA_Tariff_INR_kWh)||0])),nameByPlant=new Map(exec.map(r=>[String(r.Plant_ID),r.Plant_Name||'']));
  const revenueOpportunity=rows.reduce((s,r)=>s+(Number(r.Recoverable_Loss_MWh)||0)*1000*(tariffByPlant.get(String(r.Plant_ID))||0),0);
  const driverTotals=new Map(fields.map(([name,key])=>[name,rows.reduce((s,r)=>s+(Number(r[key])||0),0)]));
  const driverMeta={
    'Inverter':['Controllable','Maintenance / ERCI'],'Soiling':['Controllable','Cleaning / Operations'],'Module degradation':['Controllable','Asset Health / Maintenance'],Tracker:['Controllable','Maintenance'],'DC strings':['Controllable','Maintenance / Asset Explorer'],Transformer:['Controllable','Maintenance / ERCI'],'Grid outage':['External','Commercial & PPA'],Curtailment:['External','Commercial & PPA'],'Planned maintenance':['Controllable','Maintenance Planning'],Unexplained:['Investigate','Event & Root Cause Intelligence']
  };
  const opportunities=[];
  rows.forEach(r=>{
    const siteTotal=Number(r.Total_Loss_MWh)||0,siteRecoverable=Number(r.Recoverable_Loss_MWh)||0,siteExternal=(Number(r.Grid_Outage_Loss_MWh)||0)+(Number(r.Curtailment_Loss_MWh)||0);
    const controllableLoss=fields.filter(([n])=>!['Grid outage','Curtailment'].includes(n)).reduce((s,[,k])=>s+(Number(r[k])||0),0);
    fields.forEach(([driver,key])=>{
      const loss=Number(r[key])||0;if(loss<=0)return;
      const meta=driverMeta[driver]||['Investigate','Asset Explorer'];
      const driverRecoverable=meta[0]==='External'?0:(controllableLoss?siteRecoverable*(loss/controllableLoss):0);
      const value=driverRecoverable*1000*(tariffByPlant.get(String(r.Plant_ID))||0);
      opportunities.push({plant:r.Plant_ID,name:nameByPlant.get(String(r.Plant_ID))||'',driver,loss,portfolioDriverLoss:driverTotals.get(driver)||0,share:total?loss/total*100:0,siteTotal,siteRecoverable,siteExternal,driverRecoverable,value,control:meta[0],route:meta[1]});
    });
  });
  opportunities.sort((a,b)=>b.value-a.value||b.loss-a.loss);
  host.innerHTML=portfolioPerformanceHead()+portfolioPerformanceTabs('loss')+aipRecoveryScopeHtml(rows)+portfolioKpis([
    ['Total attributed loss',`${v2Num(total,0)} MWh`,100],
    ['Recoverable loss',`${v2Num(recoverable,0)} MWh`,total?recoverable/total*100:0],
    ['External loss',`${v2Num(external,0)} MWh`,total?external/total*100:0],
    ['Unexplained loss',`${v2Num(unexplained,0)} MWh`,total?unexplained/total*100:0],
    ['Recoverable revenue opportunity',v2Money(revenueOpportunity),total?recoverable/total*100:0]
  ])+`
  <div class="card"><div class="panel-title"><div><h3>Recovery Opportunities</h3><div class="v230-ranking-basis">Ordered by Recovery Value</div><div class="sub">Single integrated loss register · preserves portfolio loss-driver attribution and site recovery detail without a second bridge table.</div></div></div><div class="table-scroll"><table><thead><tr><th>Site</th><th>Loss driver</th><th>Driver loss</th><th>Portfolio share</th><th>Portfolio driver total</th><th>Site total loss</th><th>Site recoverable</th><th>Site external loss</th><th>Recoverable from driver</th><th>Recovery value</th><th>Controllability</th><th>Action route</th></tr></thead><tbody>${opportunities.map(o=>`<tr><td>${typeof portfolioSiteCode==='function'?portfolioSiteCode(o.plant,o.name||''):o.plant}${o.name?` · ${o.name}`:''}</td><td>${o.driver}</td><td>${v2Num(o.loss,1)} MWh</td><td>${v2Num(o.share,1)}%</td><td>${v2Num(o.portfolioDriverLoss,1)} MWh</td><td>${v2Num(o.siteTotal,1)} MWh</td><td>${v2Num(o.siteRecoverable,1)} MWh</td><td>${v2Num(o.siteExternal,1)} MWh</td><td>${v2Num(o.driverRecoverable,1)} MWh</td><td>${v2Money(o.value)}</td><td>${o.control}</td><td>${o.route}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function renderPortfolioBenchmarking(){
  const tab=PORTFOLIO_PERFORMANCE_TAB||'performance';
  if(tab==='benchmarking'){
    renderSiteBenchmarkingContent();
    const host=document.getElementById('view-portfoliobenchmarking');
    if(host){const head=host.querySelector(':scope > .page-head, :scope > .view-head'); if(head) head.insertAdjacentHTML('afterend',portfolioPerformanceTabs('benchmarking')); else host.insertAdjacentHTML('afterbegin',portfolioPerformanceTabs('benchmarking'));}
  } else if(tab==='loss') renderLossRecoveryTab(); else renderPortfolioPerformanceTab();
  /* Portfolio Performance uses the finalized compact KPI format; do not pass these KPIs through the legacy enhancer. */
}
