    PPA_Tariff_INR_kWh:x.PPA_Tariff_INR_kWh,Delivered_Energy_MWh:x.Actual_Generation_MWh,Scheduled_Energy_MWh:x.Budget_Generation_MWh,
    Shortfall_Energy_MWh:Math.max(0,-Number(x.Generation_Variance_MWh)),Availability_Penalty_INR:Math.max(0,-Number(x.Revenue_Variance_INR))*.1,
