function ai3Rows(name){if(String(APM_DATA_MODE||'').toLowerCase().includes('synthetic'))return null;const r=(window.APM_IMPORTED_DATA||APM_IMPORTED_DATA||{})[name];return Array.isArray(r)&&r.length?r:null}
