function ai3Date(v){const d=new Date(v);return isNaN(d)?null:d}
function ai3Source(){return APM_DATA_MODE==='Uploaded data'?'Excel upload':APM_DATA_MODE==='Excel demo data'?'Excel demo':'Synthetic'}
