   if(/synthetic|demo data/i.test(sourceMode)&&Array.isArray(independent?.[n])&&independent[n].length)return 'Synthetic';
   if(Array.isArray(imported?.[n])&&imported[n].length)return 'Excel / Imported';
   if(Array.isArray(runtimeExcel?.[n])&&runtimeExcel[n].length)return 'Bundled Excel';
