 const sites=[...new Map(caseRows.map(r=>[String(r.Plant_ID),{id:String(r.Plant_ID),name:String(r.Plant_Name||r.Plant_ID)}])).values()];
 let siteId=window.RC_SELECTED_SITE_ID||String(caseRows[0].Plant_ID);if(!sites.some(s=>s.id===siteId))siteId=sites[0].id;window.RC_SELECTED_SITE_ID=siteId;
 const siteCases=caseRows.filter(r=>String(r.Plant_ID)===siteId);
 const assets=[...new Map(siteCases.map(r=>[String(r.Asset_ID),{Asset_ID:String(r.Asset_ID),Asset_Tag:String(r.Asset_Tag||r.Asset_ID),Asset_Class:String(r.Asset_Class||'Asset'),Plant_ID:String(r.Plant_ID),Plant_Name:String(r.Plant_Name||r.Plant_ID),OEM:String(r.OEM||'—'),Model:String(r.Model||'—')}])).values()];
 const persisted=(()=>{try{return window.AIP_SELECTED_EVENT_CONTEXT||window.AIP_CONTEXT_NAV||window.AIP_SELECTED_ASSET_CONTEXT||{}}catch(_){return {}}})();
 const incoming=String(persisted.assetId||persisted.Asset_ID||persisted.tag||persisted.assetTag||'');
 let aid=window.RC_SELECTED_ASSET_ID||incoming||assets[0]?.Asset_ID||'';if(!assets.some(a=>norm(a.Asset_ID)===norm(aid)||norm(a.Asset_Tag)===norm(aid)))aid=assets[0]?.Asset_ID||'';window.RC_SELECTED_ASSET_ID=aid;
 const asset=assets.find(a=>norm(a.Asset_ID)===norm(aid)||norm(a.Asset_Tag)===norm(aid))||assets[0];
 const events=caseRows.filter(r=>String(r.Asset_ID)===String(asset.Asset_ID));
 const incomingEvent=String(persisted.eventId||persisted.Event_ID||persisted.recordId||persisted.sourceRecordId||'');
 let eventId=incomingEvent||window.RC_ACTIVE_EVENT;if(!events.some(r=>String(r.Event_ID)===String(eventId)))eventId=String(events[0].Event_ID);window.RC_ACTIVE_EVENT=eventId;
 const ev=events.find(r=>String(r.Event_ID)===eventId)||events[0];
 const ref=taxonomyRows.find(r=>String(r.Reference_ID)===String(ev.Reference_ID));
 const expectedGroup=groupFor(ev.Asset_Class),referenceValid=!!ref&&String(ref.Asset_Group||'')===expectedGroup&&norm(ref.Cause_Name)===norm(ev.Event_Type);
 const causeName=referenceValid?String(ev.Cause_Name):'Reference validation required';
 const evidence=evidenceRows.filter(r=>String(r.Event_ID)===String(ev.Event_ID)).sort((a,b)=>String(a.Evidence_ID).localeCompare(String(b.Evidence_ID))).slice(0,5);
 const outcomeRows=rowsFrom('Maintenance Learning Outcomes').filter(r=>r&&r.Outcome_ID);
 const assetCases=caseRows.filter(r=>String(r.Asset_ID)===String(ev.Asset_ID)&&String(r.Validation_Status||'').toLowerCase()==='validated');
 const peerCases=caseRows.filter(r=>String(r.Asset_Class)===String(ev.Asset_Class)&&String(r.Asset_ID)!==String(ev.Asset_ID)&&String(r.Validation_Status||'').toLowerCase()==='validated');
 const distFor=rows=>{const m={};rows.forEach(r=>{const k=String(r.Cause_Name||'Unclassified');m[k]=(m[k]||0)+1});return Object.entries(m).map(([name,count])=>({name,count})).sort((a,b)=>b.count-a.count)};
 const assetDist=distFor(assetCases),peerDist=distFor(peerCases),maxAsset=Math.max(1,...assetDist.map(d=>d.count)),maxPeer=Math.max(1,...peerDist.map(d=>d.count));
