  let pan=null;
  canvas.addEventListener('wheel',e=>{e.preventDefault();const rect=svg.getBoundingClientRect(),x=(e.clientX-rect.left)*900/rect.width,y=(e.clientY-rect.top)*540/rect.height;arGraphZoom(e.deltaY<0?1.12:.89,x,y)},{passive:false});
  canvas.addEventListener('pointerdown',e=>{if(e.target.closest('.ar-node,.ar-rel,#arFullscreenExit'))return;pan={x:e.clientX,y:e.clientY,tx:s.tx,ty:s.ty};canvas.setPointerCapture(e.pointerId);canvas.classList.add('panning')});
