  const id=n.dataset.node,e=ents.find(x=>x.Entity_ID===id);let drag=null,moved=false;
  n.addEventListener('mouseenter',ev=>showTip(`<b>${arEsc(e?.Entity_Name||id)}</b>${arEsc(e?.Entity_Type||'Entity')}<br>Risk: ${arNum(e?.Risk_Score).toFixed(2)} · ${arEsc(e?.Status||'')}`,ev));
  n.addEventListener('mousemove',ev=>showTip(`<b>${arEsc(e?.Entity_Name||id)}</b>${arEsc(e?.Entity_Type||'Entity')}<br>Risk: ${arNum(e?.Risk_Score).toFixed(2)} · ${arEsc(e?.Status||'')}`,ev));
