  n.addEventListener('pointermove',ev=>{if(!drag)return;const rect=svg.getBoundingClientRect(),kx=900/rect.width/s.scale,ky=540/rect.height/s.scale;const dx=(ev.clientX-drag.x)*kx,dy=(ev.clientY-drag.y)*ky;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;pos[id].x=drag.px+dx;pos[id].y=drag.py+dy;s.positions[id]={...pos[id]};drawARGraph(true)});
