 const nodes=ents.map(e=>{const p=pos[e.Entity_ID];if(!p)return'';const isFocus=e.Entity_ID===focus,r=isFocus?24:11+Math.min(8,arNum(e.Risk_Score)/13),labelY=p.y+r+19;return `<g class="ar-node ${isFocus?'focus':''}" data-node="${arEsc(e.Entity_ID)}" tabindex="-1" focusable="true" role="button" aria-label="${arEsc((e.Entity_Name||e.Entity_ID)+' · '+(e.Entity_Type||'Entity'))}"><circle cx="${p.x}" cy="${p.y}" r="${r}" fill="${colors[e.Entity_Type]||'#5B7083'}"></circle>${arSvgTextBlock(e.Entity_Name,p.x,labelY,'ar-node-label',18,3,11)}</g>`}).join('');
