 if(!clear)return;
 e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();
 const input=document.getElementById('arGraphSearch'),box=document.getElementById('arSearchResults'),note=document.getElementById('arNetworkNote');
 if(input)input.textContent='';
 if(box)box.innerHTML='';
 window.AIPARSearchHoverReset?.();
