  const prs=x.map(r=>wdNum(r.PR_Pct)).sort((a,b)=>a-b),median=prs.length?(prs[Math.floor((prs.length-1)/2)]+prs[Math.ceil((prs.length-1)/2)])/2:0;
  if(!window.__WD_BENCH_SELECTED||!x.some(r=>r.Site_Name===window.__WD_BENCH_SELECTED))window.__WD_BENCH_SELECTED=x[0]?.Site_Name||'';
  const selected=x.find(r=>r.Site_Name===window.__WD_BENCH_SELECTED)||x[0]||{};
