/* v87_42: final Portfolio Performance dispatcher. Keep worksheet-driven Site Benchmarking,
   while restoring the agreed Performance and Loss & Recovery tabs. */
renderPortfolioBenchmarking=function(){
  const tab=window.PORTFOLIO_PERFORMANCE_TAB||PORTFOLIO_PERFORMANCE_TAB||'performance';
  PORTFOLIO_PERFORMANCE_TAB=tab;
  if(tab==='benchmarking'){
    renderWorksheetSiteBenchmarking();
    const host=document.getElementById('view-portfoliobenchmarking');
    if(host){
      const head=host.querySelector(':scope > .page-head, :scope > .view-head, :scope > .rigour-head');
      if(head) head.insertAdjacentHTML('afterend',portfolioPerformanceTabs('benchmarking'));
      else host.insertAdjacentHTML('afterbegin',portfolioPerformanceTabs('benchmarking'));
    }
  } else if(tab==='loss') {
    renderLossRecoveryTab();
  } else {
    renderPortfolioPerformanceTab();
  }
  /* Portfolio Performance must use only the authoritative universal KPI format.
     Normalize synchronously before the browser paints, then re-check after any
     legacy/global observer has had an opportunity to touch the freshly rendered DOM. */
  const ppHost=document.getElementById('view-portfoliobenchmarking');
  const normalizePP=()=>{
    if(!ppHost)return;
    try{window.AIPKPIMaster?.scan?.(ppHost)}catch(e){console.warn('Portfolio KPI normalization failed',e)}
  };
  normalizePP();
  requestAnimationFrame(()=>{normalizePP();requestAnimationFrame(normalizePP)});
  [25,80,180].forEach(ms=>setTimeout(normalizePP,ms));
};
window.renderPortfolioBenchmarking=renderPortfolioBenchmarking;
window.setPortfolioPerformanceTab=setPortfolioPerformanceTab;

