/* ================= CONFIGURABLE ASSET HEALTH MODEL ================= */
const AIP_HEALTH_MODEL_DEFAULTS = {
  version:1,
  profileName:'Enterprise default',
  thresholds:{healthy:80,watch:65},
  weights:{performance:25,electrical:20,alarms:15,predictive:15,maintenance:15,inspection:10},
  riskBands:{healthy:[1,20],watch:[21,45],critical:[46,99]},
  rulBands:{healthy:[180,730],watch:[60,179],critical:[1,59]},
  overrides:{criticalAlarm:true,severeThermal:true,extendedOutage:true,staleData:true},
  lastUpdated:null
};
function aipClone(v){return JSON.parse(JSON.stringify(v))}
function loadAIPHealthModel(){
  try{
    const saved=JSON.parse(localStorage.getItem('aip_asset_health_model')||'null');
    if(!saved)return aipClone(AIP_HEALTH_MODEL_DEFAULTS);
    return {
      ...aipClone(AIP_HEALTH_MODEL_DEFAULTS),...saved,
      thresholds:{...AIP_HEALTH_MODEL_DEFAULTS.thresholds,...(saved.thresholds||{})},
      weights:{...AIP_HEALTH_MODEL_DEFAULTS.weights,...(saved.weights||{})},
      riskBands:{...AIP_HEALTH_MODEL_DEFAULTS.riskBands,...(saved.riskBands||{})},
      rulBands:{...AIP_HEALTH_MODEL_DEFAULTS.rulBands,...(saved.rulBands||{})},
      overrides:{...AIP_HEALTH_MODEL_DEFAULTS.overrides,...(saved.overrides||{})}
    };
  }catch(_){return aipClone(AIP_HEALTH_MODEL_DEFAULTS)}
}
function aipHealthBand(health,model=loadAIPHealthModel()){
  const h=Number(health);
  if(!Number.isFinite(h))return 'unknown';
  if(h>=Number(model.thresholds.healthy))return 'healthy';
  if(h>=Number(model.thresholds.watch))return 'watch';
  return 'critical';
}
window.AIPHealthModel={
  defaults:AIP_HEALTH_MODEL_DEFAULTS,
  get:loadAIPHealthModel,
  band:aipHealthBand,
  status(health){
    const m=loadAIPHealthModel(),h=Number(health),band=aipHealthBand(h,m);
    if(band==='unknown')return {key:'unknown',label:'No data',detail:'No source Health Score is available for this asset.'};
    if(band==='healthy')return {key:'healthy',label:'Healthy',detail:`Health Score ${Math.round(h)}% is at or above the configured Healthy threshold of ${m.thresholds.healthy}%.`};
    if(band==='watch')return {key:'watch',label:'Watch',detail:`Health Score ${Math.round(h)}% is between the configured Watch threshold ${m.thresholds.watch}% and Healthy threshold ${m.thresholds.healthy}%.`};
    return {key:'critical',label:'Critical',detail:`Health Score ${Math.round(h)}% is below the configured Watch threshold of ${m.thresholds.watch}%.`};
  }
};
function ahmNum(id,fallback){const v=Number(document.getElementById(id)?.value);return Number.isFinite(v)?v:fallback}
function ahmChecked(id){return !!document.getElementById(id)?.checked}
function collectAIPHealthModel(){
 const d=loadAIPHealthModel();
 return {...d,
  profileName:document.getElementById('ahmProfile')?.value.trim()||'Enterprise default',
  thresholds:{healthy:ahmNum('ahmHealthy',80),watch:ahmNum('ahmWatch',65)},
  weights:{performance:ahmNum('ahmWPerformance',25),electrical:ahmNum('ahmWElectrical',20),alarms:ahmNum('ahmWAlarms',15),predictive:ahmNum('ahmWPredictive',15),maintenance:ahmNum('ahmWMaintenance',15),inspection:ahmNum('ahmWInspection',10)},
  riskBands:{healthy:[ahmNum('ahmRiskHealthyMin',1),ahmNum('ahmRiskHealthyMax',20)],watch:[ahmNum('ahmRiskWatchMin',21),ahmNum('ahmRiskWatchMax',45)],critical:[ahmNum('ahmRiskCriticalMin',46),ahmNum('ahmRiskCriticalMax',99)]},
  rulBands:{healthy:[ahmNum('ahmRulHealthyMin',180),ahmNum('ahmRulHealthyMax',730)],watch:[ahmNum('ahmRulWatchMin',60),ahmNum('ahmRulWatchMax',179)],critical:[ahmNum('ahmRulCriticalMin',1),ahmNum('ahmRulCriticalMax',59)]},
  overrides:{criticalAlarm:ahmChecked('ahmCriticalAlarm'),severeThermal:ahmChecked('ahmSevereThermal'),extendedOutage:ahmChecked('ahmExtendedOutage'),staleData:ahmChecked('ahmStaleData')},
  lastUpdated:new Date().toISOString()
 };
}
function validateAIPHealthModel(m){
 const errors=[];const sum=Object.values(m.weights).reduce((a,b)=>a+Number(b||0),0);
 if(Math.abs(sum-100)>.001)errors.push(`Component weights total ${sum.toFixed(1)}%; they must total 100%.`);
 if(!(m.thresholds.healthy>m.thresholds.watch))errors.push('Healthy threshold must be greater than the Watch threshold.');
 if(m.thresholds.watch<1||m.thresholds.healthy>100)errors.push('Condition thresholds must remain between 1% and 100%.');
 for(const [k,v] of Object.entries(m.riskBands))if(v[0]>v[1]||v[0]<0||v[1]>100)errors.push(`${k} Failure Risk range is invalid.`);
 for(const [k,v] of Object.entries(m.rulBands))if(v[0]>v[1]||v[0]<0)errors.push(`${k} RUL range is invalid.`);
 if(m.riskBands.healthy[1]>=m.riskBands.watch[0]||m.riskBands.watch[1]>=m.riskBands.critical[0])errors.push('Failure Risk bands must not overlap and must increase from Healthy to Critical.');
 if(m.rulBands.critical[1]>=m.rulBands.watch[0]||m.rulBands.watch[1]>=m.rulBands.healthy[0])errors.push('RUL bands must not overlap and must increase from Critical to Healthy.');
 return {errors,sum};
}
function ahmField(id,label,value,min=0,max=100,step=1,suffix=''){return `<label class="ahm-field"><span>${label}</span><div><input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"><em>${suffix}</em></div></label>`}
function renderAssetHealthModel(){
 const root=document.getElementById('view-assethealthmodel');if(!root)return;let m=loadAIPHealthModel();try{m=JSON.parse(localStorage.getItem('aip_asset_health_model_draft')||'null')||m}catch(_){}
 root.innerHTML=`<div class="view-head"><div><div class="eyebrow" style="color:var(--teal)">GOVERNED CONDITION INTELLIGENCE</div><h1>Asset Health Scoring Framework</h1></div></div>
 
 <div class="ahm-grid">
  <section class="ahm-card"><h3>Model identity and condition bands</h3><p>These thresholds control the Solar Fleet badge and Health Score interpretation. They are governance defaults, not claimed industry standards.</p>
   <label class="ahm-field wide"><span>Scoring Profile</span><div><input id="ahmProfile" type="text" value="${String(m.profileName).replace(/"/g,'&quot;')}"></div></label>
   <div class="ahm-three">${ahmField('ahmHealthy','Healthy begins at',m.thresholds.healthy,1,100,1,'%')}${ahmField('ahmWatch','Watch begins at',m.thresholds.watch,1,99,1,'%')}<div class="ahm-readonly"><span>Critical</span><b>Below Watch threshold</b></div></div>
  </section>
  <section class="ahm-card"><h3>Health Score component weights</h3><p>Weights apply when component-level evidence is available. Component evidence is normalized to 0–100 and consolidated dynamically. A source Health Score is used only when detailed evidence is unavailable.</p>
   <div class="ahm-three">${ahmField('ahmWPerformance','Performance',m.weights.performance,0,100,1,'%')}${ahmField('ahmWElectrical','Electrical / thermal',m.weights.electrical,0,100,1,'%')}${ahmField('ahmWAlarms','Alarms / events',m.weights.alarms,0,100,1,'%')}${ahmField('ahmWPredictive','Predictive condition',m.weights.predictive,0,100,1,'%')}${ahmField('ahmWMaintenance','Maintenance history',m.weights.maintenance,0,100,1,'%')}${ahmField('ahmWInspection','Inspection / AI Vision',m.weights.inspection,0,100,1,'%')}</div><div class="ahm-total" id="ahmWeightTotal">Total: 100%</div>
  </section>
  <section class="ahm-card"><h3>Failure Risk consistency bands</h3><p>Failure Risk remains a separate model output, but contradictory values are constrained to the configured band for the selected health category.</p>
   <div class="ahm-band-table"><b>Condition</b><b>Minimum</b><b>Maximum</b><span>Healthy</span>${ahmField('ahmRiskHealthyMin','',m.riskBands.healthy[0],0,100,1,'%')}${ahmField('ahmRiskHealthyMax','',m.riskBands.healthy[1],0,100,1,'%')}<span>Watch</span>${ahmField('ahmRiskWatchMin','',m.riskBands.watch[0],0,100,1,'%')}${ahmField('ahmRiskWatchMax','',m.riskBands.watch[1],0,100,1,'%')}<span>Critical</span>${ahmField('ahmRiskCriticalMin','',m.riskBands.critical[0],0,100,1,'%')}${ahmField('ahmRiskCriticalMax','',m.riskBands.critical[1],0,100,1,'%')}</div>
  </section>
  <section class="ahm-card"><h3>RUL consistency bands</h3><p>RUL remains independently estimated. These configurable ranges prevent a visibly incompatible operating horizon from appearing beside the Health category.</p>
   <div class="ahm-band-table"><b>Condition</b><b>Minimum days</b><b>Maximum days</b><span>Healthy</span>${ahmField('ahmRulHealthyMin','',m.rulBands.healthy[0],0,5000,1,'')}${ahmField('ahmRulHealthyMax','',m.rulBands.healthy[1],0,5000,1,'')}<span>Watch</span>${ahmField('ahmRulWatchMin','',m.rulBands.watch[0],0,5000,1,'')}${ahmField('ahmRulWatchMax','',m.rulBands.watch[1],0,5000,1,'')}<span>Critical</span>${ahmField('ahmRulCriticalMin','',m.rulBands.critical[0],0,5000,1,'')}${ahmField('ahmRulCriticalMax','',m.rulBands.critical[1],0,5000,1,'')}</div>
  </section>
  <section class="ahm-card ahm-wide"><h3>Critical override policy</h3><p>Overrides prevent a weighted average from hiding a severe present condition. They are policy controls; evidence must exist before an override can trigger.</p><div class="ahm-checks">
   <label><input id="ahmCriticalAlarm" type="checkbox" ${m.overrides.criticalAlarm?'checked':''}><span><b>Safety-critical or protection alarm</b><small>Maximum status becomes Critical when a validated critical alarm is active.</small></span></label>
   <label><input id="ahmSevereThermal" type="checkbox" ${m.overrides.severeThermal?'checked':''}><span><b>Severe thermal / arcing finding</b><small>Confirmed severe hotspot, arcing or comparable inspection evidence overrides the weighted score.</small></span></label>
   <label><input id="ahmExtendedOutage" type="checkbox" ${m.overrides.extendedOutage?'checked':''}><span><b>Extended unavailability</b><small>Persistent asset unavailability can trigger a critical operating state.</small></span></label>
   <label><input id="ahmStaleData" type="checkbox" ${m.overrides.staleData?'checked':''}><span><b>Stale or insufficient data protection</b><small>Missing or stale evidence produces a data-quality warning rather than a fabricated Healthy status.</small></span></label>
  </div></section>
 </div><div class="ahm-validation" id="ahmValidation"></div><div class="ahm-actions"><button id="ahmReset" class="ahm-btn secondary">Restore defaults</button><button id="ahmValidate" class="ahm-btn secondary">Validate configuration</button><button id="ahmSave" class="ahm-btn primary">Save configuration</button><button id="ahmRecalculate" class="ahm-btn primary">Recalculate All Assets</button></div>`;
 const updateTotal=()=>{const mm=collectAIPHealthModel(),v=validateAIPHealthModel(mm),el=document.getElementById('ahmWeightTotal');if(el){el.textContent=`Total: ${v.sum.toFixed(1)}%`;el.classList.toggle('bad',Math.abs(v.sum-100)>.001)}};
 root.querySelectorAll('input').forEach(x=>x.addEventListener('input',updateTotal));updateTotal();
 document.getElementById('ahmValidate').onclick=()=>{const v=validateAIPHealthModel(collectAIPHealthModel()),box=document.getElementById('ahmValidation');box.className='ahm-validation '+(v.errors.length?'bad':'ok');box.innerHTML=v.errors.length?'<b>Configuration not valid</b><br>'+v.errors.map(e=>'• '+e).join('<br>'):'<b>Configuration valid</b><br>Weights total 100%, thresholds are ordered, and Failure Risk/RUL bands do not overlap.'};
 document.getElementById('ahmSave').onclick=()=>{const mm=collectAIPHealthModel(),v=validateAIPHealthModel(mm),box=document.getElementById('ahmValidation');if(v.errors.length){box.className='ahm-validation bad';box.innerHTML='<b>Not saved</b><br>'+v.errors.map(e=>'• '+e).join('<br>');return}localStorage.setItem('aip_asset_health_model_draft',JSON.stringify(mm));box.className='ahm-validation ok';box.innerHTML='<b>Configuration saved</b><br>Press Recalculate All Assets to apply it to fleet health scores.';window.showToast?.('Configuration saved','Use Recalculate All Assets to apply the model.');};
 document.getElementById('ahmRecalculate').onclick=()=>{const box=document.getElementById('ahmValidation');let mm;try{mm=JSON.parse(localStorage.getItem('aip_asset_health_model_draft')||'null')}catch(_){}mm=mm||collectAIPHealthModel();const v=validateAIPHealthModel(mm);if(v.errors.length){box.className='ahm-validation bad';box.innerHTML='<b>Recalculation blocked</b><br>'+v.errors.map(e=>'• '+e).join('<br>');return}mm.lastRecalculated=new Date().toISOString();mm.calcRevision=Number(mm.calcRevision||0)+1;localStorage.setItem('aip_asset_health_model',JSON.stringify(mm));localStorage.removeItem('aip_asset_health_model_draft');window.AIP_HEALTH_CACHE?.clear?.();box.className='ahm-validation ok';box.innerHTML=`<b>Fleet recalculated</b><br>All loaded assets were evaluated using the active ${mm.profileName} scoring framework.`;document.dispatchEvent(new CustomEvent('aip:health-model-changed',{detail:mm}));try{window.renderAssetExplorer?.()}catch(_){}window.showToast?.('Asset health recalculated','The active fleet now uses the saved model.');};
 document.getElementById('ahmReset').onclick=()=>{
   const defaults=aipClone(AIP_HEALTH_MODEL_DEFAULTS);
   defaults.lastUpdated=new Date().toISOString();
   localStorage.setItem('aip_asset_health_model_draft',JSON.stringify(defaults));
   renderAssetHealthModel();
   const box=document.getElementById('ahmValidation');
   if(box){box.className='ahm-validation ok';box.innerHTML='<b>Default configuration restored as a draft</b><br>The active fleet model has not changed. Validate, save, and then select Recalculate All Assets to apply the defaults.';}
   window.showToast?.('Defaults restored as draft','The active fleet is unchanged until recalculation.');
 };
}


