  const chartsBooted = {};
  const viewRendered = {};

  window.refreshAllAPM = function(){
    const active=document.querySelector(".view.active")?.id.replace("view-","")||"overview";
    Object.keys(CH).forEach(k=>CH[k]=[]);
    Object.keys(chartsBooted).forEach(k=>delete chartsBooted[k]);
    Object.keys(viewRendered).forEach(k=>delete viewRendered[k]);
    Object.keys(CH_LAYOUT_SIG).forEach(k=>delete CH_LAYOUT_SIG[k]);
    if(renderFns[active]){
      try{renderFns[active](); viewRendered[active]=true;}catch(e){console.error('Refresh failed for view',active,e);}
    }
    setBadges();

    // Dataset refresh rebuilds the KPI card HTML. Reapply the visual KPI
    // treatment synchronously so Excel, uploaded and synthetic modes use
    // the same coloured icons, sparklines, rings and accent palettes.
    if(typeof window.enhanceAllKPIs === "function") window.enhanceAllKPIs(document);
    if(typeof window.updateKPIContext === "function") window.updateKPIContext(document);

    activate(active, true);

    // Run once more after layout/chart activation to cover cards created by
    // view-specific initialisers without relying only on MutationObserver timing.
    requestAnimationFrame(()=>requestAnimationFrame(()=>{
      if(typeof window.enhanceAllKPIs === "function") window.enhanceAllKPIs(document);
      if(typeof window.updateKPIContext === "function") window.updateKPIContext(document);
    }));
  };

